 * <ul>
 *   <li>"status" : {@code "HEALTHY"} (String)</li>
 *   <li>"heapMemoryUsage" : current heap memory usage in bytes (Long)</li>
 *   <li>"nonHeapMemoryUsage" : current non‑heap memory usage in bytes (Long)</li>
 *   <li>"systemLoadAverage" : system load average over the last minute (Double)
 *       – may be {@code -1.0} if unavailable.</li>
 *   <li>"availableProcessors" : number of processors available to the JVM (Integer)
 *       – must be positive.</li>
 *   <li>"uptime" : JVM uptime in milliseconds (Long)</li>
 *   <li>"totalMemory" : total memory available to the JVM in bytes (Long)</li>
 *   <li>"freeMemory" : free memory available to the JVM in bytes (Long)</li>
 *   <li>"threadCount" : current number of active threads (Integer, at least 1)</li>
 * </ul>
 */
public class SystemHealthMonitor {

    /**
     * Gathers system health metrics and returns them in a map.
     *
     * @return a map containing the health metrics.
     * @throws IllegalStateException if any required key is missing or has an unexpected type.
     */
    public Map<String, Object> getSystemHealth() {
        Map<String, Object> healthMetrics = new HashMap<>();

        // 1. Overall status
        healthMetrics.put("status", "HEALTHY");

        // 2. Memory usage
        MemoryMXBean memoryBean = ManagementFactory.getMemoryMXBean();

        // Heap memory usage
        MemoryUsage heapUsage = memoryBean.getHeapMemoryUsage();
        long heapUsedBytes = heapUsage.getUsed();
        healthMetrics.put("heapMemoryUsage", heapUsedBytes);

        // Non‑heap memory usage
        MemoryUsage nonHeapUsage = memoryBean.getNonHeapMemoryUsage();
        long nonHeapUsedBytes = nonHeapUsage.getUsed();
        healthMetrics.put("nonHeapMemoryUsage", nonHeapUsedBytes);

        // 3. Operating system metrics
        OperatingSystemMXBean osBean = ManagementFactory.getOperatingSystemMXBean();

        // System load average (may be -1.0 if unavailable)
        double loadAverage = osBean.getSystemLoadAverage();
        healthMetrics.put("systemLoadAverage", loadAverage);

        // Available processors (must be positive)
        int availableProcessors = osBean.getAvailableProcessors();
        if (availableProcessors <= 0) {
            throw new IllegalStateException(
                "Available processors reported as non‑positive: " + availableProcessors);
        }
        healthMetrics.put("availableProcessors", availableProcessors);

        // 4. Runtime metrics
        RuntimeMXBean runtimeBean = ManagementFactory.getRuntimeMXBean();
        long uptimeMillis = runtimeBean.getUptime();
        healthMetrics.put("uptime", uptimeMillis);

        Runtime runtime = Runtime.getRuntime();
        long totalMemory = runtime.totalMemory();
        long freeMemory = runtime.freeMemory();
        healthMetrics.put("totalMemory", totalMemory);
        healthMetrics.put("freeMemory", freeMemory);

        // 5. Thread count
        int threadCount = Thread.activeCount();
        if (threadCount < 1) {
            threadCount = 1; // Ensure at least 1
        }
        healthMetrics.put("threadCount", threadCount);

        // 6. Validate that all required keys and types are present
        validateHealthMetrics(healthMetrics);

        return healthMetrics;
    }

    /**
     * Validates that the health metrics map contains all required keys with the expected types.
     *
     * @param metrics the map to validate
     * @throws IllegalStateException if validation fails
     */
    private void validateHealthMetrics(Map<String, Object> metrics) {
        // Expected key‑type pairs
        Map<String, Class<?>> expected = Map.of(
            "status", String.class,
            "heapMemoryUsage", Long.class,
            "nonHeapMemoryUsage", Long.class,
            "systemLoadAverage", Double.class,
            "availableProcessors", Integer.class,
            "uptime", Long.class,
            "totalMemory", Long.class,
            "freeMemory", Long.class,
            "threadCount", Integer.class
        );

        for (Map.Entry<String, Class<?>> entry : expected.entrySet()) {
            String key = entry.getKey();
            Class<?> expectedType = entry.getValue();

            if (!metrics.containsKey(key)) {
                throw new IllegalStateException("Missing required key: " + key);
            }

            Object value = metrics.get(key);
            if (value == null || !expectedType.isInstance(value)) {
                throw new IllegalStateException(
                    "Key '" + key + "' has unexpected type. Expected: "
                    + expectedType.getSimpleName() + ", Actual: "
                    + (value == null ? "null" : value.getClass().getSimpleName()));
            }
        }
    }
}
