            this.lastErrorMessage = "Language and country cannot be null";
            return false;
        }

        Locale newLocale = new Locale(language, country);
        Locale.setDefault(newLocale);
        this.currentLocale = newLocale;
        this.lastErrorMessage = null;
        return true;
    }

