        gameState.put("gamePaused", false);
        gameState.put("gameOver", false);
        score = 0; // reset score when a new game starts
    }

    /**
     * Moves the player one unit in the specified direction.
     *
     * @param direction one of "UP", "DOWN", "LEFT", "RIGHT" (case‑insensitive)
