                break;
            case "DOWN":
                player.move(0, 1);
                break;
            case "LEFT":
                player.move(-1, 0);
                break;
            case "RIGHT":
                player.move(1, 0);
                break;
            default:
                // Invalid direction; do nothing
                break;
        }
        return player.getPosition();
