        IntBuffer intBuffer = IntBuffer.allocate(bufferSize);

        try {
            // Write values into the buffer (up to its capacity)
            for (int value : writeValues) {
                intBuffer.put(value); // may throw BufferOverflowException
            }
        } catch (BufferOverflowException e) {
            // Return an error message if the buffer capacity is exceeded
            return "Error: Attempted to write beyond buffer capacity";
