import java.nio.ReadOnlyBufferException;

class AdvancedBufferOperations {
    /**
     * Performs advanced IntBuffer operations: writes values, reads them back,
     * manipulates position and limit, and returns a formatted string.
     *
     * @param bufferSize  the capacity of the IntBuffer to allocate
     * @param writeValues the values to write into the buffer
     * @return a string containing the buffer contents and partial content,
     *         or an error message if a buffer overflow occurs
     */
    public String performAdvancedBufferOperations(int bufferSize, int[] writeValues) {
        StringBuilder result = new StringBuilder();

        // Allocate the buffer with the requested capacity
        IntBuffer intBuffer = IntBuffer.allocate(bufferSize);

        try {
            // Write values into the buffer (may throw BufferOverflowException)
            for (int value : writeValues) {
                intBuffer.put(value);
            }
        } catch (BufferOverflowException e) {
            // Return an error message if the buffer capacity is exceeded
            return "Error: Attempted to write beyond buffer capacity";
        }

        // Prepare the buffer for reading the full content
        intBuffer.flip();

        // Read the full content and build the result string
        result.append("Initial buffer content: ");
        while (intBuffer.hasRemaining()) {
            result.append(intBuffer.get()).append(" ");
        }
        result.append("\n");

        // Reset the buffer for partial read
        intBuffer.rewind();                 // position = 0, limit = capacity
        intBuffer.position(1);              // set position to 1
        intBuffer.limit(Math.min(3, intBuffer.capacity())); // set limit to 3 (or capacity if smaller)

        // Read the partial content and append to the result
        result.append("Partial buffer content (position 1, limit 3): ");
        while (intBuffer.hasRemaining()) {
            result.append(intBuffer.get()).append(" ");
        }
        result.append("\n");

        return result.toString();
    }

    /**
     * Performs ByteBuffer operations: writes an int, a double, and a char,
     * then reads them back, and demonstrates read‑only buffer protection.
     *
     * @return a string containing the read values and the read‑only buffer test
     */
    public String performByteBufferOperations() {
        StringBuilder result = new StringBuilder();

        // Allocate a ByteBuffer with sufficient capacity
        ByteBuffer byteBuffer = ByteBuffer.allocate(1024);

        // Write an int, a double, and a char
        byteBuffer.putInt(100);
        byteBuffer.putDouble(3.14159);
        byteBuffer.putChar('A');

        // Prepare the buffer for reading
        byteBuffer.flip();

        // Read the values back
        int readInt = byteBuffer.getInt();
        double readDouble = byteBuffer.getDouble();
        char readChar = byteBuffer.getChar();

        // Append each read value with the required format
        result.append("Read int: ").append(readInt).append("\n");
        result.append("Read double: ").append(readDouble).append("\n");
        result.append("Read char: ").append(readChar).append("\n");

        // Create a read‑only view of the buffer
        ByteBuffer readOnlyBuffer = byteBuffer.asReadOnlyBuffer();

        // Attempt to write to the read‑only buffer and catch the exception
        try {
            readOnlyBuffer.putInt(200);
        } catch (ReadOnlyBufferException e) {
            result.append("Successfully prevented write to read-only buffer\n");
        }

        return result.toString();
    }

