public class FunctionDemonstrator {

    public List<String> demonstrateFunctionConcepts(int baseValue) {
        List<String> results = new ArrayList<>();

        // 1. Primitive function: square
        int squared = baseValue * baseValue;
        results.add("Primitive function (square) result: " + squared);

        // 2. Variable assignment: double
        int doubled = baseValue * 2;
        results.add("Variable assignment result: " + doubled);

        // 3. Parameter passing using a method reference
        Function<Integer, Integer> addFiveRef = this::addFive;
        int addedFive = addFiveRef.apply(baseValue);
        results.add("Parameter passing result: " + addedFive);

        // 4. Higher‑order function: compose square then add five
        Function<Integer, Integer> square = x -> x * x;
        Function<Integer, Integer> composed = compose(square, addFiveRef);
        int composedResult = composed.apply(baseValue);
        results.add("Higher-order function result: " + composedResult);

        // 5. Recursive factorial
        int factorialResult = factorial(baseValue);
        results.add("Recursive factorial result: " + factorialResult);

        return results;
    }

    // Private helper method used via method reference
    private int addFive(int x) {
        return x + 5;
    }

    // Higher‑order function that composes two unary functions
    private Function<Integer, Integer> compose(
            Function<Integer, Integer> first,
            Function<Integer, Integer> second) {
        return first.andThen(second);
    }

