import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;

public class UserAuthenticationService {

    private final Map<String, User> userDatabase;
    private final MessageDigest sha256Digest;

    public UserAuthenticationService() throws NoSuchAlgorithmException {
        this.userDatabase = new HashMap<>();
        this.sha256Digest = MessageDigest.getInstance("SHA-256");
    }

    public static class User {
        private final String email;
        private final String passwordHash;
        private final String role;

        public User(String email, String passwordHash, String role) {
            this.email = email;
            this.passwordHash = passwordHash;
            this.role = role;
        }

        public String getEmail() {
            return email;
        }

        public String getPasswordHash() {
            return passwordHash;
        }

        public String getRole() {
            return role;
        }
    }

    private String hashPassword(String password) {
        byte[] hashBytes = sha256Digest.digest(password.getBytes());
        return Base64.getEncoder().encodeToString(hashBytes);
    }

    // Optional helper methods
    public void addUser(String email, String password, String role) {
        String hashed = hashPassword(password);
        User user = new User(email, hashed, role);
        userDatabase.put(email, user);
    }

    public User getUserByEmail(String email) {
        return userDatabase.get(email);
    }
}

