     * @return a map with keys: "isValid", "authority", "path", "type"
     */
    public static Map<String, Object> processContentUri(String uriString) {
        Map<String, Object> result = new HashMap<>();

        // Assume all URIs are valid for now
        result.put("isValid", true);

        String authority = "";
        String path = "";

        if (uriString != null) {
            String schemePrefix = "content://";
            String rest = uriString;

            // Remove the scheme prefix if present
            if (uriString.startsWith(schemePrefix)) {
                rest = uriString.substring(schemePrefix.length());
            }

            // Find the first '/' to separate authority and path
            int slashIndex = rest.indexOf('/');
            if (slashIndex >= 0) {
                authority = rest.substring(0, slashIndex);
                path = rest.substring(slashIndex); // include the '/' in the path
            } else {
                authority = rest;
                path = "";
            }
        }

        result.put("authority", authority);
        result.put("path", path);
        result.put("type", "UNKNOWN");

        return result;
    }
}

