/**
 * Utility class for analyzing file paths.
 */
public class PathAnalyzer {

    /**
     * Analyzes the given file path and returns a map containing the filename,
     * its extension, and the parent directory path in normalized form.
     *
     * @param filePath the file path to analyze
     * @return a map with three entries:
     *         - "filename"  : the file name component
     *         - "extension" : the file extension (empty string if none)
     *         - "parentDir" : the normalized parent directory path (empty string if none)
     * @throws IllegalArgumentException if {@code filePath} is {@code null} or empty
