            // Both patterns are valid; check credentials against the map
            String storedPassword = VALID_USERS.get(username);
            boolean authenticated = storedPassword != null && storedPassword.equals(password);
            result.put("authenticated", authenticated);
            result.put("message", authenticated ? "Authentication successful" : "Invalid credentials");
        }

        return result;
    }
}

