public class LinkedList<D> {
    // Node class for doubly linked structure
    private static class Node<D> {
        D data;
        Node<D> prev;
        Node<D> next;

        Node(D data) {
            this.data = data;
        }
    }

    private Node<D> head;   // first node
    private Node<D> tail;   // last node
    private int size;       // number of elements

    public LinkedList() {
        head = null;
        tail = null;
        size = 0;
    }

    // Add element to the end of the list
    public void add(D data) {
        Node<D> newNode = new Node<>(data);
        if (head == null) {          // list is empty
            head = tail = newNode;
        } else {                     // append after tail
            tail.next = newNode;
            newNode.prev = tail;
            tail = newNode;
        }
        size++;
    }

    // Return current size of the list
    public int size() {
        return size;
    }
}

