public class LinkedList<D> {
    // Node class for doubly linked structure
    private static class Node<D> {
        D data;
        Node<D> prev;
        Node<D> next;

        Node(D data) {
            this.data = data;
        }
    }

    private Node<D> head;   // first node
    private Node<D> tail;   // last node
    private int size;       // number of elements

    public LinkedList() {
        head = null;
        tail = null;
        size = 0;
    }

    // Add element to the end of the list
    public void add(D data) {
        Node<D> newNode = new Node<>(data);
        if (head == null) {          // list is empty
            head = tail = newNode;
        } else {                     // append after tail
            tail.next = newNode;
            newNode.prev = tail;
            tail = newNode;
        }
        size++;
    }

    // Return current size of the list
    public int size() {
        return size;
    }

    // Return the data at the specified index
    public D get(int index) {
        return getNode(index).data;
    }

    // Efficiently traverse from head or tail to find the node at index
    private Node<D> getNode(int index) {
        if (index < 0 || index >= size) {
            throw new IndexOutOfBoundsException(
                "Index: " + index + ", Size: " + size);
        }

        Node<D> current;
        if (index < size / 2) {          // start from head
            current = head;
            for (int i = 0; i < index; i++) {
                current = current.next;
            }
        } else {                         // start from tail
            current = tail;
            for (int i = size - 1; i > index; i--) {
                current = current.prev;
            }
        }
        return current;
    }
}

