import java.util.*;

public class FinancialReportAnalyzer {

    /**
     * Analyzes a list of PolicyData objects and returns a map containing
     * the total premium amount and the number of policies processed.
     *
     * @param policies List of PolicyData objects to analyze.
     * @return Map with keys "totalPremium" (Double) and "policyCount" (Integer).
     */
    public static Map<String, Object> analyze(List<PolicyData> policies) {
        Map<String, Object> result = new HashMap<>();
        double totalPremium = 0.0;
        int policyCount = 0;

        if (policies != null) {
            for (PolicyData pd : policies) {
                if (pd != null) {
                    totalPremium += pd.getPremiumAmount();
                    policyCount++;
                }
            }
        }

        result.put("totalPremium", totalPremium);
        result.put("policyCount", policyCount);
        return result;
    }

    // Optional main method for quick demonstration
    public static void main(String[] args) {
        List<PolicyData> list = new ArrayList<>();
        list.add(new PolicyData("RC1", "Risk1", "RC2", "Risk2", 1000.0));
        list.add(new PolicyData("RC3", "Risk3", "RC4", "Risk4", 2000.0));

        Map<String, Object> report = analyze(list);
        System.out.println("Total Premium: " + report.get("totalPremium"));
        System.out.println("Policy Count: " + report.get("policyCount"));
    }
}

class PolicyData {
    private final String previousRiskCode;
    private final String previousRiskName;
    private final String currentRiskCode;
    private final String currentRiskName;
    private final double premiumAmount;

    public PolicyData(String previousRiskCode, String previousRiskName,
                      String currentRiskCode, String currentRiskName,
                      double premiumAmount) {
        this.previousRiskCode = previousRiskCode;
        this.previousRiskName = previousRiskName;
        this.currentRiskCode = currentRiskCode;
        this.currentRiskName = currentRiskName;
        this.premiumAmount = premiumAmount;
    }

    public String getPreviousRiskCode() {
        return previousRiskCode;
    }

    public String getPreviousRiskName() {
        return previousRiskName;
    }

    public String getCurrentRiskCode() {
        return currentRiskCode;
    }

    public String getCurrentRiskName() {
        return currentRiskName;
    }

    public double getPremiumAmount() {
        return premiumAmount;
    }

    @Override
    public String toString() {
        return "PolicyData{" +
                "previousRiskCode='" + previousRiskCode + '\'' +
                ", previousRiskName='" + previousRiskName + '\'' +
                ", currentRiskCode='" + currentRiskCode + '\'' +
                ", currentRiskName='" + currentRiskName + '\'' +
                ", premiumAmount=" + premiumAmount +
                '}';
    }
}

