import java.sql.Timestamp;
import java.util.ArrayList;
import java.util.List;

/**
 * Basic implementation of a BudgetVersionManager that validates, filters,
 * and analyzes budget versions.
 */
class BudgetVersionManager {

    /* --------------------------------------------------------------------- */
    /* Validation methods                                                   */
    /* --------------------------------------------------------------------- */

    /**
     * Validates the given budget version.
     *
     * @param version the budget version to validate
     * @return a list of error messages; empty if the version is valid
     */
    public List<String> validateBudgetVersion(VersaoOrcamento version) {
        List<String> errors = new ArrayList<>();

        if (version == null) {
            errors.add("Budget version cannot be null");
            return errors; // No need to check further if the object itself is null
        }

        // Validate ID
        if (version.getIdVersaoOrcamento() == null) {
            errors.add("Version ID cannot be null");
        }

        // Validate description message
        String descricao = version.getDescricaoMensagem();
        if (descricao == null || descricao.trim().isEmpty()) {
            errors.add("Description message is required");
        }

        // Validate status
        String status = version.getIdtStatus();
        if (status == null || !isValidStatus(status)) {
            errors.add("Status must be one of A, R, or P");
        }

        // Validate effective date
        if (version.getDataVigencia() == null) {
            errors.add("Effective date is required");
        }

        return errors;
    }

    private boolean isValidStatus(String status) {
        return status.equals("A") || status.equals("R") || status.equals("P");
    }

    /* --------------------------------------------------------------------- */
    /* Filtering method                                                     */
    /* --------------------------------------------------------------------- */

    /**
     * Filters a list of budget versions by optional status, fromDate, and toDate.
     *
     * @param versions the list of versions to filter
     * @param status   optional status filter (exact match); if null, ignored
     * @param fromDate optional start date filter (inclusive); if null, ignored
     * @param toDate   optional end date filter (inclusive); if null, ignored
     * @return a new list containing only the versions that match all provided criteria
     */
    public List<VersaoOrcamento> filterVersions(
            List<VersaoOrcamento> versions,
            String status,
            Timestamp fromDate,
            Timestamp toDate) {

        List<VersaoOrcamento> result = new ArrayList<>();

        if (versions == null) {
            return result; // return empty list if input is null
        }

        for (VersaoOrcamento v : versions) {
            if (v == null) {
                continue; // skip null elements
            }

            // Status filter
            if (status != null && !status.equals(v.getIdtStatus())) {
                continue;
            }

            // From date filter (inclusive)
            if (fromDate != null) {
                Timestamp data = v.getDataVigencia();
                if (data == null || data.before(fromDate)) {
                    continue;
                }
            }

            // To date filter (inclusive)
            if (toDate != null) {
                Timestamp data = v.getDataVigencia();
                if (data == null || data.after(toDate)) {
                    continue;
                }
            }

            result.add(v);
        }

        return result;
    }

    /* --------------------------------------------------------------------- */
    /* Analysis method                                                      */
    /* --------------------------------------------------------------------- */

    /**
     * Analyzes a list of budget versions and returns a {@link BudgetVersionAnalysis}
     * object containing counts and date ranges.
     *
     * @param versions the list of versions to analyze
     * @return a {@link BudgetVersionAnalysis} object with the analysis results
     */
    public BudgetVersionAnalysis analyzeVersions(List<VersaoOrcamento> versions) {
        BudgetVersionAnalysis analysis = new BudgetVersionAnalysis();

        if (versions == null || versions.isEmpty()) {
            // All counts are already zero and dates are null by default
            return analysis;
        }

        Timestamp earliest = null;
        Timestamp latest = null;

        for (VersaoOrcamento v : versions) {
            if (v == null) {
                continue;
            }

            analysis.incrementTotal();

            String status = v.getIdtStatus();
            if ("A".equals(status)) {
                analysis.incrementApproved();
            } else if ("R".equals(status)) {
                analysis.incrementRejected();
            } else if ("P".equals(status)) {
                analysis.incrementPending();
            }

            Timestamp date = v.getDataVigencia();
            if (date != null) {
                if (earliest == null || date.before(earliest)) {
                    earliest = date;
                }
                if (latest == null || date.after(latest)) {
                    latest = date;
                }
            }
        }

        analysis.setEarliest(earliest);
        analysis.setLatest(latest);

        return analysis;
    }
}

