        boolean[] zeroCols = new boolean[cols];
        int zeroCount = 0;

        long startTime = System.currentTimeMillis();

        // First pass: identify rows and columns that contain a zero
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    zeroRows[r] = true;
                    zeroCols[c] = true;
