class MatrixProcessor {
    public MatrixResult processMatrix(int[][] matrix, boolean useSpaceEfficient) {
        // Input validation
        if (matrix == null || matrix.length == 0 ||
            matrix[0] == null || matrix[0].length == 0) {
            throw new IllegalArgumentException("Matrix cannot be null or empty");
        }

        int rows = matrix.length;
        int cols = matrix[0].length;

        // Count zeros in the original matrix
        int zeroCount = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    zeroCount++;
                }
            }
        }

        // Deep copy of the original matrix for the result
        int[][] originalCopy = deepCopy(matrix);

        // Create a copy to process so the original matrix stays unchanged
        int[][] toProcess = deepCopy(matrix);

        long startTime = System.currentTimeMillis();

        int[][] processed;
        String methodUsed;
        if (useSpaceEfficient) {
            processed = zeroMatrixSpaceEfficient(toProcess);
            methodUsed = "Space-Efficient";
        } else {
            processed = zeroMatrixWithSets(toProcess);
            methodUsed = "HashSet-Based";
        }

        long endTime = System.currentTimeMillis();
        long processingTimeMs = endTime - startTime;

        return new MatrixResult(processed, originalCopy, zeroCount, processingTimeMs, methodUsed);
    }

    // O(n+m) space algorithm using HashSet
    private int[][] zeroMatrixWithSets(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        java.util.Set<Integer> zeroRows = new java.util.HashSet<>();
        java.util.Set<Integer> zeroCols = new java.util.HashSet<>();

        // First pass: identify rows and columns that contain a zero
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    zeroRows.add(r);
                    zeroCols.add(c);
                }
            }
        }

        // Second pass: zero out identified rows and columns
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (zeroRows.contains(r) || zeroCols.contains(c)) {
                    matrix[r][c] = 0;
                }
            }
        }

        return matrix;
    }

    // O(1) space algorithm using first row and column as markers
    private int[][] zeroMatrixSpaceEfficient(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        boolean firstRowHasZero = false;
        boolean firstColHasZero = false;

        // Check if first row has a zero
        for (int c = 0; c < cols; c++) {
            if (matrix[0][c] == 0) {
                firstRowHasZero = true;
                break;
            }
        }

        // Check if first column has a zero
        for (int r = 0; r < rows; r++) {
            if (matrix[r][0] == 0) {
                firstColHasZero = true;
                break;
            }
        }

        // Use first row and column to mark zeros
        for (int r = 1; r < rows; r++) {
            for (int c = 1; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    matrix[r][0] = 0;
                    matrix[0][c] = 0;
                }
            }
        }

        // Zero out cells based on markers
        for (int r = 1; r < rows; r++) {
            for (int c = 1; c < cols; c++) {
                if (matrix[r][0] == 0 || matrix[0][c] == 0) {
                    matrix[r][c] = 0;
                }
            }
        }

        // Zero out first row if needed
        if (firstRowHasZero) {
            for (int c = 0; c < cols; c++) {
                matrix[0][c] = 0;
            }
        }

        // Zero out first column if needed
        if (firstColHasZero) {
            for (int r = 0; r < rows; r++) {
                matrix[r][0] = 0;
            }
        }

        return matrix;
    }

    // Helper method to create a deep copy of a 2D integer array
    private static int[][] deepCopy(int[][] source) {
        if (source == null) {
            return null;
        }
        int[][] copy = new int[source.length][];
        for (int i = 0; i < source.length; i++) {
            if (source[i] != null) {
                copy[i] = new int[source[i].length];
                System.arraycopy(source[i], 0, copy[i], 0, source[i].length);
            } else {
                copy[i] = null;
            }
        }
        return copy;
    }

    static class MatrixResult {
        final int[][] processedMatrix;
        final int[][] originalMatrix;
        final int zeroCount;
        final long processingTimeMs;
        final String methodUsed;

        public MatrixResult(int[][] processedMatrix, int[][] originalMatrix,
                            int zeroCount, long processingTimeMs, String methodUsed) {
            this.processedMatrix = processedMatrix;
            this.originalMatrix = originalMatrix;
            this.zeroCount = zeroCount;
            this.processingTimeMs = processingTimeMs;
            this.methodUsed = methodUsed;
        }
    }
}
