import java.util.concurrent.ConcurrentHashMap;

public class UserSettingsManager {
    // Thread‑safe storage for all users and their settings
    private final ConcurrentHashMap<String, ConcurrentHashMap<String, Object>> userSettings =
            new ConcurrentHashMap<>();

    /**
     * Stores a setting for a specific user.
     *
     * @param key      the setting key
     * @param value    the setting value (must be String, Integer, or Boolean)
     * @param username the user whose setting is being stored
     * @throws IllegalArgumentException if the value type is unsupported
     */
    public void saveUserSetting(String key, Object value, String username) {
        if (!(value instanceof String || value instanceof Integer || value instanceof Boolean)) {
            throw new IllegalArgumentException(
                    "Unsupported value type: " + value.getClass().getName());
        }

        // Create the inner map for the user if it doesn't exist yet
        ConcurrentHashMap<String, Object> settings =
                userSettings.computeIfAbsent(username, k -> new ConcurrentHashMap<>());

        // Store the setting
        settings.put(key, value);
    }

    /**
     * Retrieves a setting for a specific user.
     *
     * @param key      the setting key
     * @param username the user whose setting is being retrieved
     * @return the setting value, or {@code null} if not found
     */
    public Object getUserSetting(String key, String username) {
        ConcurrentHashMap<String, Object> settings = userSettings.get(username);
        return (settings != null) ? settings.get(key) : null;
    }
}

