// Product entity
class Product {
    private int id;
    private String name;
    private int categoryId;

    public Product(int id, String name, int categoryId) {
        this.id = id;
        this.name = name;
        this.categoryId = categoryId;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public int getCategoryId() { return categoryId; }

    public void setId(int id) { this.id = id; }
    public void setName(String name) { this.name = name; }
    public void setCategoryId(int categoryId) { this.categoryId = categoryId; }
}

// Enhanced product manager with logging, validation, restricted categories and unique ID enforcement
class EnhancedProductManager {
    private final Map<Integer, Product> productDatabase;
    private final LoggerService logger;
    private final Set<Integer> restrictedCategories;

    public EnhancedProductManager(LoggerService logger, List<Integer> restrictedCategories) {
        this.productDatabase = new HashMap<>();
        this.logger = logger;
        this.restrictedCategories = (restrictedCategories == null)
                ? new HashSet<>()
                : new HashSet<>(restrictedCategories);
    }

    // Add a product with validation and uniqueness check
    public Map<String, String> addProduct(Product product) {
        Map<String, String> result = new HashMap<>();

        if (product == null) {
            result.put("status", "error");
            result.put("message", "Product cannot be null");
            return result;
        }

        String name = product.getName();
        if (name == null || name.trim().isEmpty()) {
            result.put("status", "error");
            result.put("message", "Product name cannot be empty");
            return result;
        }

        int catId = product.getCategoryId();
        if (restrictedCategories.contains(catId)) {
            result.put("status", "error");
            result.put("message", "Products in category " + catId + " are not allowed");
            return result;
        }

        int id = product.getId();
        if (productDatabase.containsKey(id)) {
            result.put("status", "error");
            result.put("message", "Product ID " + id + " already exists");
            return result;
        }

        productDatabase.put(id, product);
        result.put("status", "success");
        result.put("message", "Product added successfully");
        logger.log("Product added: " + product.getName());
        return result;
    }

    // Remove a product by ID with existence check
    public Map<String, String> removeProduct(int id) {
        Map<String, String> result = new HashMap<>();

        if (!productDatabase.containsKey(id)) {
            result.put("status", "error");
            result.put("message", "Product with ID " + id + " does not exist");
            return result;
        }

        Product removed = productDatabase.remove(id);
        result.put("status", "success");
        result.put("message", "Product removed successfully");
        logger.log("Product removed: " + removed.getName());
        return result;
    }

    public List<Product> getAllProducts() {
        return new ArrayList<>(productDatabase.values());
    }
}

