import java.util.*;

class StringProcessor {

    public static Map<String, Object> processString(String input) {
        // Use LinkedHashMap to preserve insertion order
        Map<String, Object> results = new LinkedHashMap<>();

        // 1. Reverse the entire string
        String reversed = new StringBuilder(input).reverse().toString();
        results.put("reversedString", reversed);

        // 2. Reverse each word individually while keeping word order
        String trimmed = input.trim();
        String[] words = trimmed.isEmpty() ? new String[0] : trimmed.split("\\s+");
        StringBuilder wordsReversedBuilder = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            wordsReversedBuilder.append(new StringBuilder(words[i]).reverse());
            if (i < words.length - 1) {
                wordsReversedBuilder.append(' ');
            }
        }
        results.put("wordsReversed", wordsReversedBuilder.toString());

        // 3. Count the number of words
        results.put("wordCount", words.length);

        // 4. Count non‑space characters as a long
        long charCount = 0;
        for (int i = 0; i < input.length(); i++) {
            if (input.charAt(i) != ' ') {
                charCount++;
            }
        }
        results.put("charCount", charCount);

        return results;
    }
}

