public class UserManager {

    // Thread-safe counter for unique user IDs
    private static final AtomicLong ID_GENERATOR = new AtomicLong(1);

    // Internal list to store users
    private final List<User> users = Collections.synchronizedList(new ArrayList<>());

    /**
     * Creates a new user with a unique ID, adds it to the internal list,
     * and returns the created user.
     *
     * @param username the username of the new user
     * @param email    the email address of the new user
     * @param password the password of the new user
     * @return the newly created User instance
     */
    public User createUser(String username, String email, String password) {
        Long newId = ID_GENERATOR.getAndIncrement();
        User newUser = new User(newId, username, email, password);
        users.add(newUser);
        return newUser;
    }

    /**
     * Returns an unmodifiable view of the current users.
     *
     * @return list of users
     */
    public List<User> getUsers() {
        return Collections.unmodifiableList(users);
    }

    /**
     * Nested User class representing a user entity.
     */
    public static class User {
        private final Long id;
        private final String username;
        private final String email;
        private final String password;
        private boolean active;

        /**
         * Constructs a User with the specified id, username, email, and password.
         * The active flag defaults to true.
         *
         * @param id       unique identifier for the user
         * @param username the username
         * @param email    the email address
         * @param password the password
         */
        public User(Long id, String username, String email, String password) {
            this.id = id;
            this.username = username;
            this.email = email;
            this.password = password;
            this.active = true;
        }

        // Getters
        public Long getId() {
            return id;
        }

        public String getUsername() {
            return username;
        }

        public String getEmail() {
            return email;
        }

        public String getPassword() {
            return password;
        }

        public boolean isActive() {
            return active;
        }

        // Setter for active status
        public void setActive(boolean active) {
            this.active = active;
        }

        @Override
        public String toString() {
            return "User{id=" + id + ", username='" + username + '\'' +
                    ", email='" + email + '\'' + ", active=" + active + '}';
        }
    }
}

