import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Collectors;

public class UserManager {

    // Thread‑safe counter for unique user IDs
    private static final AtomicLong ID_GENERATOR = new AtomicLong(1);

    // Internal list to store users
    private final List<User> users = Collections.synchronizedList(new ArrayList<>());

    /**
     * Creates a new user with a unique ID, adds it to the internal list,
     * and returns the created user.
     *
     * @param username the username of the new user
     * @param email    the email address of the new user
     * @param password the password of the new user
     * @return the newly created User instance
     * @throws IllegalArgumentException if any argument is null or if the
     *                                  username/email already exist
     */
    public User createUser(String username, String email, String password) {
        if (username == null || email == null || password == null) {
            throw new IllegalArgumentException("Username, email, and password must not be null");
        }

        synchronized (users) {
            // Check uniqueness across all users (including inactive)
            boolean usernameTaken = users.stream()
                    .anyMatch(u -> username.equals(u.getUsername()));
            if (usernameTaken) {
                throw new IllegalArgumentException("Username already taken: " + username);
            }

            boolean emailTaken = users.stream()
                    .anyMatch(u -> email.equals(u.getEmail()));
            if (emailTaken) {
                throw new IllegalArgumentException("Email already taken: " + email);
            }

            Long newId = ID_GENERATOR.getAndIncrement();
            User newUser = new User(newId, username, email, password);
            users.add(newUser);
            return newUser;
        }
    }

    /**
     * Finds a user by its unique ID.
     *
     * @param id the ID to search for
     * @return an Optional containing the User if found, otherwise Optional.empty()
     */
    public Optional<User> findUserById(Long id) {
        synchronized (users) {
            return users.stream()
                    .filter(u -> u.getId().equals(id))
                    .findFirst();
        }
    }

    /**
     * Returns a list of all users that are currently active.
     *
     * @return list of active users
     */
    public List<User> getAllActiveUsers() {
        synchronized (users) {
            return users.stream()
                    .filter(User::isActive)
                    .collect(Collectors.toList());
        }
    }

    /**
     * Deactivates the user with the specified ID.
     *
     * @param id the ID of the user to deactivate
     * @return true if the user was found and deactivated, false otherwise
     */
    public boolean deactivateUser(Long id) {
        synchronized (users) {
            Optional<User> opt = users.stream()
                    .filter(u -> u.getId().equals(id))
                    .findFirst();
            if (opt.isPresent()) {
                opt.get().setActive(false);
                return true;
            }
            return false;
        }
    }

    /**
     * Updates the user identified by {@code id}. Only non‑null fields are
     * updated. {@code username} and {@code email} must remain unique across
     * all users (including inactive ones). If the user is not found,
     * an {@link IllegalArgumentException} is thrown. If a uniqueness conflict
     * occurs, an {@link IllegalArgumentException} is also thrown.
     *
     * @param id       the ID of the user to update
     * @param username the new username (or {@code null} to leave unchanged)
     * @param email    the new email (or {@code null} to leave unchanged)
     * @param password the new password (or {@code null} to leave unchanged)
     * @return the updated {@link User}
     * @throws IllegalArgumentException if the user is not found or a
     *                                  uniqueness conflict occurs
     */
    public User updateUser(Long id, String username, String email, String password) {
        synchronized (users) {
            User target = users.stream()
                    .filter(u -> u.getId().equals(id))
                    .findFirst()
                    .orElseThrow(() -> new IllegalArgumentException("User not found: " + id));

            // Check uniqueness for username
            if (username != null) {
                boolean conflict = users.stream()
                        .anyMatch(u -> !u.getId().equals(id) && username.equals(u.getUsername()));
                if (conflict) {
                    throw new IllegalArgumentException("Username already taken: " + username);
                }
                target.setUsername(username);
            }

            // Check uniqueness for email
            if (email != null) {
                boolean conflict = users.stream()
                        .anyMatch(u -> !u.getId().equals(id) && email.equals(u.getEmail()));
                if (conflict) {
                    throw new IllegalArgumentException("Email already taken: " + email);
                }
                target.setEmail(email);
            }

            // Update password if provided
            if (password != null) {
                target.setPassword(password);
            }

            return target;
        }
    }

    /**
     * Returns an unmodifiable view of the current users.
     *
     * @return list of users
     */
    public List<User> getUsers() {
        return Collections.unmodifiableList(users);
    }

    /**
     * Nested User class representing a user entity.
     */
    public static class User {
        private final Long id;
        private String username;
        private String email;
        private String password;
        private boolean active;

        /**
         * Constructs a User with the specified id, username, email, and password.
         * The active flag defaults to true.
         *
         * @param id       unique identifier for the user
         * @param username the username
         * @param email    the email address
         * @param password the password
         */
        public User(Long id, String username, String email, String password) {
            this.id = id;
            this.username = username;
            this.email = email;
            this.password = password;
            this.active = true;
        }

        // Getters
        public Long getId() {
            return id;
        }

        public String getUsername() {
            return username;
        }

        public String getEmail() {
            return email;
        }

        public String getPassword() {
            return password;
        }

        public boolean isActive() {
            return active;
        }

        // Setters for mutable fields
        public void setUsername(String username) {
            this.username = username;
        }

        public void setEmail(String email) {
            this.email = email;
        }

        public void setPassword(String password) {
            this.password = password;
        }

        public void setActive(boolean active) {
            this.active = active;
        }

        @Override
        public String toString() {
            return "User{id=" + id + ", username='" + username + '\'' +
                    ", email='" + email + '\'' + ", active=" + active + '}';
        }
    }
}
