import java.time.format.DateTimeFormatter;

class TaskDatabaseManager {
    private List<Map<String, Object>> taskCache;

    public TaskDatabaseManager() {
        this.taskCache = new ArrayList<>();
    }

    /**
     * Inserts a new task into the in‑memory cache.
     *
     * @param taskType    the type of the task (e.g., 1 for assignment, 2 for quiz)
     * @param taskName    the name/title of the task
     * @param taskContent the full content or description of the task
     * @param studentId   the ID of the student who owns the task
     * @param studentName the name of the student
     * @return a map containing the status of the operation, the generated taskId,
     *         and the number of affected rows
     */
    public Map<String, Object> insertTask(int taskType, String taskName, String taskContent,
                                          int studentId, String studentName) {
        // Generate a UUID-based task ID
        String taskId = UUID.randomUUID().toString();

        // Current timestamp in 'yyyy-MM-dd HH:mm:ss' format
        String timestamp = LocalDateTime.now()
                .format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"));

        // Build the task record
        Map<String, Object> taskRecord = new HashMap<>();
        taskRecord.put("taskId", taskId);
        taskRecord.put("taskType", taskType);
        taskRecord.put("taskName", taskName);
        taskRecord.put("taskContent", taskContent);
        taskRecord.put("studentId", studentId);
        taskRecord.put("studentName", studentName);
        taskRecord.put("creationTime", timestamp);
        taskRecord.put("successCount", 0);
        taskRecord.put("failCount", 0);
        taskRecord.put("score", 0);
        taskRecord.put("status", "pending");

        // Store the task
        taskCache.add(taskRecord);

        // Prepare the response
        Map<String, Object> response = new HashMap<>();
        response.put("status", "success");
        response.put("taskId", taskId);
        response.put("affectedRows", 1);
        return response;
    }

    /**
     * Queries tasks based on the provided criteria and pagination parameters.
     *
     * @param criteria   a map of key/value pairs that must match exactly in a task
     * @param pageNumber the 1‑based page number to retrieve
     * @param pageSize   the number of items per page
     * @return a map containing the paginated tasks and pagination metadata
     */
    public Map<String, Object> queryTasks(Map<String, Object> criteria, int pageNumber, int pageSize) {
        // 1. Filter tasks that match all criteria
        List<Map<String, Object>> filtered = new ArrayList<>();
        for (Map<String, Object> task : taskCache) {
            boolean matches = true;
            for (Map.Entry<String, Object> entry : criteria.entrySet()) {
                Object taskValue = task.get(entry.getKey());
                if (taskValue == null || !taskValue.equals(entry.getValue())) {
                    matches = false;
                    break;
                }
            }
            if (matches) {
                filtered.add(task);
            }
        }

        // 2. Pagination calculations
        int totalItems = filtered.size();
        int totalPages = (pageSize <= 0) ? 0 : (int) Math.ceil((double) totalItems / pageSize);

        // Clamp pageNumber to valid range
        int currentPage = pageNumber;
        if (totalPages == 0) {
            currentPage = 1;
        } else {
            if (currentPage < 1) {
                currentPage = 1;
            } else if (currentPage > totalPages) {
                currentPage = totalPages;
            }
        }

        // 3. Determine sublist for the current page
        List<Map<String, Object>> pageTasks = Collections.emptyList();
        if (totalPages > 0) {
            int startIndex = (currentPage - 1) * pageSize;
            int endIndex = Math.min(startIndex + pageSize, totalItems);
            pageTasks = filtered.subList(startIndex, endIndex);
        }

        // 4. Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("tasks", pageTasks);
        result.put("currentPage", currentPage);
        result.put("totalPages", totalPages);
        result.put("totalItems", totalItems);
        return result;
    }

    // Optional helper to retrieve a task by ID (useful for testing or further operations)
    public Map<String, Object> getTaskById(String taskId) {
        for (Map<String, Object> task : taskCache) {
            if (task.get("taskId").equals(taskId)) {
                return task;
            }
        }
        return null;
    }
}

