import java.util.*;

public class FragmentManager {
    private final Map<String, Fragment> fragments = new HashMap<>();
    private Fragment currentFragment = null;
    private String currentTag = null;

    /**
     * Adds a fragment with the specified tag.
     *
     * @param tag      the unique tag for the fragment
     * @param fragment the fragment instance
     * @throws IllegalArgumentException if tag or fragment is null
     */
    public void addFragment(String tag, Fragment fragment) {
        if (tag == null || fragment == null) {
            throw new IllegalArgumentException("Tag and fragment cannot be null");
        }
        fragments.put(tag, fragment);
    }

    /**
     * Switches the current fragment to the one identified by the given tag.
     *
     * @param tag the tag of the fragment to switch to
     * @return {@code true} if the fragment was found and switched to,
     *         {@code false} otherwise (current fragment remains unchanged)
     */
    public boolean switchFragment(String tag) {
        if (tag == null) {
            return false;
        }

        // If the requested fragment is already current, do nothing but return true
        if (tag.equals(currentTag)) {
            return true;
        }

        Fragment fragment = fragments.get(tag);
        if (fragment == null) {
            return false;
        }

        currentFragment = fragment;
        currentTag = tag;
        return true;
    }

    /**
