import java.util.*;

class TwoSatSolver {
    // Set of all variables that appear in clauses
    private final Set<Integer> variables = new HashSet<>();

    // List of all clauses added (each clause is a pair of literals)
    private final List<int[]> clauses = new ArrayList<>();

    // Implication graph: maps a literal to the list of literals it implies
    private final Map<Integer, List<Integer>> graph = new HashMap<>();

    // Reverse implication graph: maps a literal to the list of literals that imply it
    private final Map<Integer, List<Integer>> reverseGraph = new HashMap<>();

    // Finishing times computed during the first pass of Kosaraju's algorithm
    private final Map<Integer, Integer> finishingTimes = new HashMap<>();

    // Leader of each literal after the second pass
    private final Map<Integer, Integer> leaders = new HashMap<>();

    public TwoSatSolver() {
        // No additional initialization required
    }

    /**
     * Adds a clause (a ∨ b) to the solver.
     *
     * @param a first literal (positive for the variable, negative for its negation)
     * @param b second literal
     */
    public void addClause(int a, int b) {
        // Record the variables involved
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        // Store the clause itself
        clauses.add(new int[]{a, b});

        // Add implication edges: (-a → b) and (-b → a)
        addEdge(-a, b);
        addEdge(-b, a);

        // Add reverse edges for the first pass of Kosaraju
        addReverseEdge(b, -a);
        addReverseEdge(a, -b);
    }

    /**
     * Adds an implication edge from src to dest in the graph.
     *
     * @param src source literal
     * @param dest destination literal
     */
    private void addEdge(int src, int dest) {
        graph.computeIfAbsent(src, k -> new ArrayList<>()).add(dest);
    }

    /**
     * Adds an implication edge from src to dest in the reverse graph.
     *
     * @param src source literal
     * @param dest destination literal
     */
    private void addReverseEdge(int src, int dest) {
        reverseGraph.computeIfAbsent(src, k -> new ArrayList<>()).add(dest);
    }

    /**
     * Performs the first pass of Kosaraju's algorithm on the reverse graph
     * to compute finishing times of all literals, then performs the second
     * pass on the original graph to determine strongly connected components.
     *
     * @return true if the set of clauses is satisfiable, false otherwise
     */
    public boolean isSatisfiable() {
        // First pass: compute finishing times
        finishingTimes.clear();
        Set<Integer> allLiterals = new HashSet<>();
        for (int var : variables) {
            allLiterals.add(var);
            allLiterals.add(-var);
        }
        Set<Integer> visited = new HashSet<>();
        int counter = 1;
        for (int literal : allLiterals) {
            if (!visited.contains(literal)) {
                counter = dfsReverse(literal, visited, counter);
            }
        }

        // Second pass: determine SCCs and leaders
        secondPass();

        // Check for contradictions: a variable and its negation must not share a leader
        for (int var : variables) {
            int leaderPos = leaders.get(var);
            int leaderNeg = leaders.get(-var);
            if (leaderPos == leaderNeg) {
                return false; // Contradiction found
            }
        }
        return true; // No contradictions
    }

    /**
     * Depth‑first search on the reverse graph to compute finishing times.
     *
     * @param node   current literal
     * @param visited set of already visited literals
     * @param counter current finishing time counter
     * @return updated counter after processing this node
     */
    private int dfsReverse(int node, Set<Integer> visited, int counter) {
        visited.add(node);
        for (int neighbor : reverseGraph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                counter = dfsReverse(neighbor, visited, counter);
            }
        }
        finishingTimes.put(node, counter);
        return counter + 1;
    }

    /**
     * Performs the second pass of Kosaraju's algorithm on the original graph.
     * Nodes are processed in decreasing order of finishing times.
     */
    private void secondPass() {
        leaders.clear();
        Set<Integer> visited = new HashSet<>();

        // Sort literals by decreasing finishing time
        List<Integer> sortedLiterals = new ArrayList<>(finishingTimes.keySet());
        sortedLiterals.sort((a, b) -> Integer.compare(finishingTimes.get(b), finishingTimes.get(a)));

        for (int literal : sortedLiterals) {
            if (!visited.contains(literal)) {
                dfsOriginal(literal, literal, visited);
            }
        }
    }

    /**
     * Depth‑first search on the original graph to assign leaders.
     *
     * @param node   current literal
     * @param leader the leader of the current SCC
     * @param visited set of already visited literals
     */
    private void dfsOriginal(int node, int leader, Set<Integer> visited) {
        visited.add(node);
        leaders.put(node, leader);
        for (int neighbor : graph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                dfsOriginal(neighbor, leader, visited);
            }
        }
    }

    // Optional helper methods for inspection

    public Set<Integer> getVariables() {
        return Collections.unmodifiableSet(variables);
    }

    public List<int[]> getClauses() {
        return Collections.unmodifiableList(clauses);
    }

    public Map<Integer, List<Integer>> getGraph() {
        Map<Integer, List<Integer>> unmodifiable = new HashMap<>();
        for (Map.Entry<Integer, List<Integer>> entry : graph.entrySet()) {
            unmodifiable.put(entry.getKey(), Collections.unmodifiableList(entry.getValue()));
        }
        return Collections.unmodifiableMap(unmodifiable);
    }

    public Map<Integer, List<Integer>> getReverseGraph() {
        Map<Integer, List<Integer>> unmodifiable = new HashMap<>();
        for (Map.Entry<Integer, List<Integer>> entry : reverseGraph.entrySet()) {
            unmodifiable.put(entry.getKey(), Collections.unmodifiableList(entry.getValue()));
        }
        return Collections.unmodifiableMap(unmodifiable);
    }

