        notifMsg.put("title", "Update");
        notifMsg.put("body", "Your profile has been updated.");
        wsHandler.processMessage("notification", notifMsg);

        // Simulate receiving an unknown message type
        Map<String, Object> unknownMsg = new HashMap<>();
        unknownMsg.put("data", "Some data");
        wsHandler.processMessage("unknown", unknownMsg);
    }
}

