    private final Map<String, Consumer<Map<String, Object>>> messageHandlers;
    private final BiConsumer<String, String> errorLogger;
    private final RateLimiter rateLimiter;

    public WebSocketMessageHandler(BiConsumer<String, String> errorLogger) {
        this.messageHandlers = new HashMap<>();
        this.errorLogger = errorLogger;
        this.rateLimiter = new RateLimiter(100, 1000); // 100 messages per 1000 ms
    }

    /**
     * Registers a handler for a specific message type.
     *
     * @param messageType the type of the message
     * @param handler     the consumer that will process the message data
     */
    public void addMessageHandler(String messageType, Consumer<Map<String, Object>> handler) {
        messageHandlers.put(messageType, handler);
    }

    /**
     * Removes the handler for the given message type.
     *
     * @param messageType the type of the message
     */
    public void removeMessageHandler(String messageType) {
        messageHandlers.remove(messageType);
    }

    /**
     * Processes an incoming message by looking up the handler for its type.
     * Validates that the message type is not null/empty and that the message data is not null.
     * Enforces a rate limit of 100 messages per second.
     *
     * @param messageType the type of the message
     * @param messageData the payload of the message
     * @return true if a handler was found and executed, false otherwise
     */
    public boolean processMessage(String messageType, Map<String, Object> messageData) {
        // Rate limiting
        if (!rateLimiter.allow()) {
            errorLogger.accept(messageType, "Rate limit exceeded");
            return false;
        }

        // Validation
        if (messageType == null || messageType.isEmpty() || messageData == null) {
            errorLogger.accept(messageType, "Invalid message: type or data is null/empty");
            return false;
        }

        Consumer<Map<String, Object>> handler = messageHandlers.get(messageType);
        if (handler != null) {
            handler.accept(messageData);
            return true;
        } else {
            errorLogger.accept(messageType, "No handler registered for message type");
            return false;
        }
    }

    /**
     * Simple sliding‑window rate limiter.
     */
    private static class RateLimiter {
        private final int maxRequests;
        private final long perMillis;
        private final Deque<Long> timestamps = new ArrayDeque<>();

        public RateLimiter(int maxRequests, long perMillis) {
            this.maxRequests = maxRequests;
            this.perMillis = perMillis;
        }

        public synchronized boolean allow() {
            long now = System.currentTimeMillis();
            long windowStart = now - perMillis;

            // Remove timestamps outside the window
            while (!timestamps.isEmpty() && timestamps.peekFirst() < windowStart) {
                timestamps.pollFirst();
            }

            if (timestamps.size() >= maxRequests) {
                return false; // limit exceeded
            }

            timestamps.addLast(now);
            return true;
        }
    }

    // Demo usage
    public static void main(String[] args) throws InterruptedException {
        // Simple error logger that prints to console
        BiConsumer<String, String> logger = (type, msg) -> System.err.println("[" + type + "] " + msg);

        WebSocketMessageHandler wsHandler = new WebSocketMessageHandler(logger);

        // Register a handler for chat messages
        wsHandler.addMessageHandler("chat", data -> {
            String user = (String) data.get("user");
            String text = (String) data.get("text");
            System.out.println("Chat from " + user + ": " + text);
        });

        // Register a handler for notification messages
        wsHandler.addMessageHandler("notification", data -> {
            String title = (String) data.get("title");
            String body = (String) data.get("body");
            System.out.println("Notification - " + title + ": " + body);
        });

        // Simulate receiving a chat message
        Map<String, Object> chatMsg = new HashMap<>();
        chatMsg.put("user", "Alice");
        chatMsg.put("text", "Hello, world!");
        wsHandler.processMessage("chat", chatMsg);

        // Simulate receiving a notification
        Map<String, Object> notifMsg = new HashMap<>();
        notifMsg.put("title", "Update");
        notifMsg.put("body", "Your profile has been updated.");
        wsHandler.processMessage("notification", notifMsg);

        // Simulate receiving an unknown message type
        Map<String, Object> unknownMsg = new HashMap<>();
        unknownMsg.put("data", "Some data");
        wsHandler.processMessage("unknown", unknownMsg);

        // Simulate invalid messages
        wsHandler.processMessage(null, chatMsg);          // null type
        wsHandler.processMessage("", chatMsg);           // empty type
        wsHandler.processMessage("chat", null);          // null data

        // Simulate rate limiting: send 101 messages in quick succession
        for (int i = 0; i < 101; i++) {
            Map<String, Object> msg = new HashMap<>();
            msg.put("user", "User" + i);
            msg.put("text", "Message " + i);
            boolean ok = wsHandler.processMessage("chat", msg);
            if (!ok) {
                System.out.println("Message " + i + " rejected due to rate limiting");
            }
        }

        // Wait a second and send another message to show the limiter resets
        Thread.sleep(1000);
        wsHandler.processMessage("chat", chatMsg);
    }
}
