import java.util.HashMap;
import java.util.function.Consumer;

class AsyncResponseHandler {
    private final HashMap<String, Consumer<Object>> callbacks = new HashMap<>();
    private Consumer<Exception> errorHandler;

    /**
     * Registers a callback for a specific response type.
     *
     * @param responseType the type of response to listen for
     * @param callback     the consumer that will be invoked when a response of the given type is received
     */
    public void registerCallback(String responseType, Consumer<Object> callback) {
        if (responseType == null || callback == null) {
            throw new IllegalArgumentException("responseType and callback must not be null");
        }
        callbacks.put(responseType, callback);
    }

    /**
     * Sets a global error handler that will be invoked when an exception occurs.
     *
     * @param handler the consumer that will receive the exception
     */
    public void setErrorHandler(Consumer<Exception> handler) {
        this.errorHandler = handler;
    }

    /**
     * Invokes the callback associated with the given response type.
     *
     * @param responseType the type of the response
     * @param response     the response object to pass to the callback
     */
    public void handleResponse(String responseType, Object response) {
        Consumer<Object> callback = callbacks.get(responseType);
        if (callback != null) {
            try {
                callback.accept(response);
            } catch (Exception e) {
                if (errorHandler != null) {
                    errorHandler.accept(e);
                } else {
                    throw new RuntimeException(e);
                }
            }
        } else {
            // No callback registered for this type; optionally handle this case
        }
    }
}

