import java.util.HashMap;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;

class AsyncResponseHandler {
    private final HashMap<String, Consumer<Object>> callbacks = new HashMap<>();
    private Consumer<Exception> errorHandler;

    /**
     * Registers a callback for a specific response type.
     *
     * @param responseType the type of response to listen for
     * @param callback     the consumer that will be invoked when a response of the given type is received
     */
    public void registerCallback(String responseType, Consumer<Object> callback) {
        if (responseType == null || callback == null) {
            throw new IllegalArgumentException("responseType and callback must not be null");
        }
        callbacks.put(responseType, callback);
    }

    /**
     * Registers a global error handler that will be invoked for any exception
     * thrown by a callback or when a response type has no registered callback.
     *
     * @param handler the consumer that will receive the exception
     */
    public void registerErrorHandler(Consumer<Exception> handler) {
        this.errorHandler = handler;
    }

    /**
     * Processes a response by looking up the callback for the given response type.
     * If a callback exists, it is executed with the provided response.
     * If no callback is registered and an error handler is set, the error handler
     * is invoked with an IllegalArgumentException indicating the missing handler.
     *
     * @param responseType the type of the response
     * @param response     the response object to pass to the callback
     */
    public void processResponse(String responseType, Object response) {
        Consumer<Object> callback = callbacks.get(responseType);
        if (callback != null) {
            try {
                callback.accept(response);
            } catch (Exception e) {
                if (errorHandler != null) {
                    errorHandler.accept(e);
                } else {
                    throw new RuntimeException(e);
                }
            }
        } else if (errorHandler != null) {
            errorHandler.accept(new IllegalArgumentException(
                    "No callback registered for response type: " + responseType));
        }
    }

    /**
     * Executes the given task asynchronously. On successful completion, a success
     * message is processed with the specified response type. If the task throws
     * an exception, the global error handler (if registered) is invoked with that
     * exception.
     *
     * @param task          the task to run asynchronously
     * @param responseType  the response type to use when reporting success
     */
    public void executeAsync(Runnable task, String responseType) {
        CompletableFuture.runAsync(task)
                .whenComplete((result, ex) -> {
                    if (ex != null) {
                        if (errorHandler != null) {
                            errorHandler.accept((Exception) ex);
