     *
     * @param key   the option name
     * @param value the option value (must not be null)
     * @throws IllegalArgumentException if value is null or fails validation
     */
    public void setOption(String key, Object value) {
        if (value == null) {
            throw new IllegalArgumentException("Option value cannot be null for key: " + key);
        }
        validateOption(key, value);
        options.put(key, value);
    }

