    private void validateOption(String key, Object value) {
        switch (key) {
            case "safe":
                if (!(value instanceof Integer)) {
                    throw new IllegalArgumentException("'safe' must be an Integer");
                }
                int safeVal = (Integer) value;
                if (safeVal < 0 || safeVal > 3) {
                    throw new IllegalArgumentException("'safe' must be between 0 and 3");
                }
                break;

            case "template_dirs":
                if (!(value instanceof List) && !(value instanceof String[])) {
                    throw new IllegalArgumentException("'template_dirs' must be a List or String array");
                }
                break;

            case "backend":
                if (!(value instanceof String)) {
                    throw new IllegalArgumentException("'backend' must be a String");
                }
                break;

            default:
                // No specific validation for other options
                break;
        }
    }

    // Optional getters for internal structures
    public Set<String> getRequiredOptions() {
        return Collections.unmodifiableSet(requiredOptions);
    }

