import java.util.*;

/**
 * A minimal naval battle adapter that manages ship placement, attack processing,
 * and game state reporting.
 */
public class NavalBattleAdapter {

    /** Positions occupied by ships. */
    private final Set<String> shipPositions;

    /** Positions that have been attacked. */
    private final Set<String> attackPositions;

    /** Indicates whether the game has ended. */
    private boolean gameOver;

    /** The winner of the game ("Opponent" when all ships are sunk). */
    private String winner;

    /**
     * Constructs a new adapter with no ships and no attacks.
     */
    public NavalBattleAdapter() {
        this.shipPositions = new HashSet<>();
        this.attackPositions = new HashSet<>();
        this.gameOver = false;
        this.winner = null;
    }

    /**
     * Places ships at the specified coordinates.
     *
     * @param coordinates a list of coordinate strings (e.g., "A1", "B3")
     * @throws IllegalArgumentException if {@code coordinates} is {@code null} or empty
     */
    public void placeShips(List<String> coordinates) {
        if (coordinates == null || coordinates.isEmpty()) {
            throw new IllegalArgumentException("Coordinates list cannot be null or empty.");
        }
        shipPositions.addAll(coordinates);
    }

    /**
     * Processes an attack at the given coordinate.
     *
     * @param coordinate the attack coordinate
     * @return {@link HitResult#HIT} if a ship occupies the coordinate,
     *         {@link HitResult#MISS} if no ship occupies it,
     *         {@link HitResult#SUNK} if the hit removes the last remaining ship position.
     * @throws IllegalArgumentException if {@code coordinate} is {@code null} or empty
     */
    public HitResult receiveAttack(String coordinate) {
        if (coordinate == null || coordinate.isEmpty()) {
            throw new IllegalArgumentException("Coordinate cannot be null or empty.");
        }

        attackPositions.add(coordinate);

        if (shipPositions.contains(coordinate)) {
            // Remove the hit position
            shipPositions.remove(coordinate);

            // If this was the last ship position, the ship is sunk
            if (shipPositions.isEmpty()) {
                gameOver = true;
                winner = "Opponent";
                return HitResult.SUNK;
            }
            return HitResult.HIT;
        }

        return HitResult.MISS;
    }

    /**
     * Returns the current game state.
     *
     * @return a {@link GameState} object containing remaining ships, attacks made,
     *         gameOver status, and winner.
     */
    public GameState getGameState() {
        return new GameState(
                shipPositions,
                attackPositions,
                gameOver,
                winner
        );
    }

    /**
     * Possible results of an attack.
     */
    public enum HitResult {
        HIT,
        MISS,
        SUNK
    }

    /**
     * Immutable snapshot of the game's current state.
     */
    public static class GameState {
        private final Set<String> remainingShips;
        private final Set<String> attacksMade;
        private final boolean gameOver;
        private final String winner;

        public GameState(Set<String> remainingShips,
                         Set<String> attacksMade,
                         boolean gameOver,
                         String winner) {
            this.remainingShips = new HashSet<>(remainingShips);
            this.attacksMade = new HashSet<>(attacksMade);
            this.gameOver = gameOver;
            this.winner = winner;
        }

        public Set<String> getRemainingShips() {
            return Collections.unmodifiableSet(remainingShips);
        }

        public Set<String> getAttacksMade() {
            return Collections.unmodifiableSet(attacksMade);
        }

        public boolean isGameOver() {
            return gameOver;
        }

        public String getWinner() {
            return winner;
        }
    }
}

