import java.util.*;

public class AdditionChainFinder {

    /**
     * Finds the shortest addition chain that starts with 1 and ends with the given target.
     * Each element after the first is the sum of two (not necessarily distinct) previous elements.
     *
     * @param target the final number of the addition chain (must be >= 1)
     * @return a list of integers representing the shortest addition chain
     */
    public List<Integer> findShortestAdditionChain(int target) {
        if (target < 1) {
            throw new IllegalArgumentException("Target must be at least 1");
        }
        if (target == 1) {
            return Collections.singletonList(1);
        }

        // The maximum possible length of an addition chain for int values is well below 64
        int[] chain = new int[64];
        chain[0] = 1;

        for (int depth = 1; ; depth++) {
            if (dfs(chain, 0, depth, target)) {
                return toList(chain, depth + 1);
            }
        }
    }

    /**
     * Depth‑first search with iterative deepening.
     *
     * @param chain   the current chain (partial)
     * @param index   the index of the last filled element in chain
     * @param maxDepth the maximum depth allowed for this search
     * @param target  the desired final value
     * @return true if a chain ending with target is found
     */
    private boolean dfs(int[] chain, int index, int maxDepth, int target) {
        if (index == maxDepth) {
            return chain[index] == target;
        }

        // Prune: even if we double the current maximum each remaining step,
        // we cannot reach the target.
        int remaining = maxDepth - index;
        long maxPossible = (long) chain[index] << remaining;
        if (maxPossible < target) {
            return false;
        }

        // Generate candidate next values: sums of any two previous numbers,
        // strictly greater than the current maximum and <= target.
        // Use a TreeSet in reverse order to try larger sums first.
        TreeSet<Integer> candidates = new TreeSet<>(Collections.reverseOrder());
        for (int i = index; i >= 0; i--) {
            for (int j = i; j >= 0; j--) {
                int sum = chain[i] + chain[j];
                if (sum > chain[index] && sum <= target) {
                    candidates.add(sum);
                }
            }
        }

        for (int next : candidates) {
            // Additional pruning: if even the largest possible value after this step
            // cannot reach target, skip this candidate.
            long maxAfter = (long) next << (remaining - 1);
            if (maxAfter < target) {
                continue;
            }

            chain[index + 1] = next;
            if (dfs(chain, index + 1, maxDepth, target)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Converts the first 'len' elements of the array into a List<Integer>.
     */
    private List<Integer> toList(int[] array, int len) {
        List<Integer> list = new ArrayList<>(len);
        for (int i = 0; i < len; i++) {
            list.add(array[i]);
        }
        return list;
    }
}

