        // we cannot reach the target.
        int remaining = maxDepth - index;
        long maxPossible = (long) chain[index] << remaining;
        if (maxPossible < target) {
            return false;
        }

        // Generate all possible next values: sums of any two previous numbers,
        // strictly greater than the current maximum and <= target.
        TreeSet<Integer> candidates = new TreeSet<>();
        for (int i = index; i >= 0; i--) {
            for (int j = i; j >= 0; j--) {
                int sum = chain[i] + chain[j];
                if (sum > chain[index] && sum <= target) {
                    candidates.add(sum);
                }
            }
        }

        for (int next : candidates) {
            // Additional pruning: if even the largest possible value after this
            // step cannot reach target, skip this candidate.
            long maxAfter = (long) next << (remaining - 1);
            if (maxAfter < target) {
                continue;
            }

            chain[index + 1] = next;
            if (dfs(chain, index + 1, maxDepth, target)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Converts the first {@code len} elements of {@code array} into a List.
     */
    private List<Integer> toList(int[] array, int len) {
        List<Integer> list = new ArrayList<>(len);
        for (int i = 0; i < len; i++) {
            list.add(array[i]);
        }
        return list;
    }

    /**
     * Validates that the provided chain is a correct addition chain for the given target.
     *
     * @param chain  the list of integers representing the chain
     * @param target the expected final value of the chain
     * @return {@code true} if the chain starts with 1, ends with {@code target},
     *         and each element after the first is the sum of two previous elements;
     *         {@code false} otherwise
     */
    public static boolean validateAdditionChain(List<Integer> chain, int target) {
        if (chain == null || chain.isEmpty()) {
            return false;
        }
        if (chain.get(0) != 1) {
            return false;
        }
        if (chain.get(chain.size() - 1) != target) {
            return false;
        }

        // For each element after the first, check if it can be expressed as the sum
        // of two earlier elements.
        for (int i = 1; i < chain.size(); i++) {
            int value = chain.get(i);
            boolean found = false;
            for (int a = 0; a < i && !found; a++) {
                for (int b = a; b < i; b++) {
                    if (chain.get(a) + chain.get(b) == value) {
                        found = true;
                        break;
                    }
                }
            }
            if (!found) {
                return false;
            }
        }
        return true;
    }
