public class StringProcessor {

    public static String processString(String input) {
        // Return empty string if input is null or empty
        if (input == null || input.isEmpty()) {
            return "";
        }

        // Build a string containing only letters
        StringBuilder lettersOnly = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (Character.isLetter(ch)) {
                lettersOnly.append(ch);
            }
        }

        // If no letters were found, return empty string
        if (lettersOnly.length() == 0) {
            return "";
        }

        // Convert to title case: first letter uppercase, rest lowercase
        char firstChar = Character.toUpperCase(lettersOnly.charAt(0));
        String rest = lettersOnly.substring(1).toLowerCase();

        return firstChar + rest;
    }
}

