import java.util.*;

class GraphAnalyzer {

    /**
     * Computes the shortest distances from the source vertex to all other vertices
     * in a weighted graph represented by an adjacency matrix using Dijkstra's algorithm.
     *
     * @param graph  adjacency matrix where graph[i][j] is the weight of the edge from i to j.
     *               A value of 0 (except on the diagonal) indicates no edge.
     * @param source the index of the source vertex.
     * @return a map containing:
     *         - "distances": int[] of shortest distances from source to each vertex.
     *         - "paths": Map<Integer, List<Integer>> mapping each vertex to the list of vertices
     *           that form the shortest path from source to that vertex.
     */
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        int n = graph.length;
        int[] dist = new int[n];
        int[] prev = new int[n];
        boolean[] visited = new boolean[n];

        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(prev, -1);
        dist[source] = 0;

        PriorityQueue<Vertex> pq = new PriorityQueue<>(Comparator.comparingInt(v -> v.distance));
        pq.offer(new Vertex(source, 0));

        while (!pq.isEmpty()) {
            Vertex current = pq.poll();
            int u = current.index;
            if (visited[u]) continue;
            visited[u] = true;

            for (int v = 0; v < n; v++) {
                int weight = graph[u][v];
                if (weight <= 0 || visited[v]) continue; // no edge or already processed
                if (dist[u] + weight < dist[v]) {
                    dist[v] = dist[u] + weight;
                    prev[v] = u;
                    pq.offer(new Vertex(v, dist[v]));
                }
            }
        }

        // Build paths for each reachable vertex
        Map<Integer, List<Integer>> paths = new HashMap<>();
        for (int v = 0; v < n; v++) {
            if (v == source) continue;
            if (dist[v] == Integer.MAX_VALUE) continue; // unreachable
            List<Integer> path = buildPath(prev, source, v);
            paths.put(v, path);
        }

        Map<String, Object> result = new HashMap<>();
