import java.util.*;

class GraphAnalyzer {

    /**
     * Computes the shortest distances from the source vertex to all other vertices
     * in a weighted graph represented by an adjacency matrix using Dijkstra's algorithm.
     * Additionally, reconstructs the shortest paths from the source to each vertex,
     * counts how many vertices were processed, and determines the maximum finite
     * shortest distance among all reachable vertices.
     *
     * @param graph  adjacency matrix where graph[i][j] is the weight of the edge from i to j.
     *               A value of 0 (except on the diagonal) indicates no edge.
     * @param source the index of the source vertex.
     * @return a map containing:
     *         - "distances": int[] of shortest distances from source to each vertex.
     *         - "paths": List<List<Integer>> where each inner list is the shortest path
     *           from source to the corresponding vertex (empty list if unreachable).
     *         - "visitedCount": int number of vertices dequeued and processed.
     *         - "maxDistance": int maximum finite shortest distance among reachable vertices.
     */
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        int n = graph.length;
        int[] dist = new int[n];
        int[] prev = new int[n];
        boolean[] visited = new boolean[n];

        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(prev, -1);
        dist[source] = 0;

        PriorityQueue<Vertex> pq = new PriorityQueue<>(Comparator.comparingInt(v -> v.distance));
        pq.offer(new Vertex(source, 0));

        int visitedCount = 0; // counter for processed vertices

        while (!pq.isEmpty()) {
            Vertex current = pq.poll();
            int u = current.index;
            if (visited[u]) continue;
            visited[u] = true;
            visitedCount++; // vertex is dequeued and processed

            for (int v = 0; v < n; v++) {
                int weight = graph[u][v];
                if (weight <= 0 || visited[v]) continue; // no edge or already processed
                if (dist[u] + weight < dist[v]) {
                    dist[v] = dist[u] + weight;
                    prev[v] = u;
                    pq.offer(new Vertex(v, dist[v]));
                }
            }
        }

        // Reconstruct paths for each vertex
        List<List<Integer>> paths = new ArrayList<>(n);
        for (int v = 0; v < n; v++) {
            paths.add(buildPath(prev, source, v));
        }

        // Compute maximum finite shortest distance
        int maxDistance = 0;
        for (int d : dist) {
            if (d != Integer.MAX_VALUE && d > maxDistance) {
                maxDistance = d;
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("distances", dist);
