class FileUploadUtil {

    /* ------------------------------------------------------------------ */
    /* 1. Extract filename from a Content‑Disposition header                */
    /* ------------------------------------------------------------------ */

    /**
     * Extracts the filename from a Content-Disposition header.
     * Supports both {@code filename} and {@code filename*} parameters,
     * handles quoted values (single or double) and unquoted values.
     *
     * @param contentDisposition the header string, e.g.
     *        {@code "form-data; name=\"file\"; filename=\"example.txt\""}
     * @return the filename without surrounding quotes, or {@code null} if none found
     */
    public static String getFilename(String contentDisposition) {
        if (contentDisposition == null || contentDisposition.isEmpty()) {
            return null;
        }

        String filename = null;
        String filenameStar = null;

        // Split the header into individual parameters
        String[] parts = contentDisposition.split(";");
        for (String part : parts) {
            part = part.trim();
            int eq = part.indexOf('=');
            if (eq == -1) {
                continue; // not a key=value pair
            }

            String key = part.substring(0, eq).trim().toLowerCase();
            String value = part.substring(eq + 1).trim();

            if ("filename*".equals(key)) {
                filenameStar = parseFilenameStar(value);
            } else if ("filename".equals(key)) {
                filename = parseFilename(value);
            }
        }

        // Prefer filename* if present
        return filenameStar != null ? filenameStar : filename;
    }

    /**
     * Parses a {@code filename} parameter value.
     * Handles quoted (single or double) and unquoted values.
     */
    private static String parseFilename(String value) {
        if (value == null || value.isEmpty()) {
            return null;
        }

        // Strip surrounding quotes if present
        if ((value.startsWith("\"") && value.endsWith("\"")) ||
            (value.startsWith("'") && value.endsWith("'"))) {
            return value.substring(1, value.length() - 1);
        }

        // Return as-is for unquoted values
        return value;
    }

    /**
     * Parses a {@code filename*} parameter value according to RFC 5987.
     * Example: {@code UTF-8''%E2%82%AC%20rates.txt}
     */
    private static String parseFilenameStar(String value) {
        if (value == null || value.isEmpty()) {
            return null;
        }

        // RFC 5987 format: charset'lang'value
        int firstQuote = value.indexOf('\'');
        if (firstQuote == -1) {
            return null; // malformed
        }
        int secondQuote = value.indexOf('\'', firstQuote + 1);
        if (secondQuote == -1) {
            return null; // malformed
        }

        String charsetName = value.substring(0, firstQuote);
        // String lang = value.substring(firstQuote + 1, secondQuote); // ignored
        String encoded = value.substring(secondQuote + 1);

        try {
            Charset charset = Charset.forName(charsetName);
            // URLDecoder decodes percent-encoding and '+' to space
            return URLDecoder.decode(encoded, charset.name());
        } catch (Exception e) {
            // Unsupported charset or decoding error
            return null;
        }
    }

    /* ------------------------------------------------------------------ */
    /* 2. Extract file extension from a filename                           */
    /* ------------------------------------------------------------------ */

    /**
     * Extracts the file extension from a filename.
     *
     * @param filename the filename string
     * @return the extension in lowercase, or an empty string if none exists
     */
    public static String getExtension(String filename) {
        if (filename == null || filename.isEmpty()) {
            return "";
        }

        int lastDot = filename.lastIndexOf('.');
        if (lastDot == -1 || lastDot == filename.length() - 1) {
            return "";
        }

        return filename.substring(lastDot + 1).toLowerCase();
    }

