     * Subsequent key/value pairs are added with lowercase keys and quote‑stripped
     * values.  Keys without an {@code =} are ignored.
     *
     * @param contentDisposition the header string
     * @return a map containing the parsed values
     */
    public static Map<String, String> parseContentDisposition(String contentDisposition) {
        Map<String, String> result = new HashMap<>();

        if (contentDisposition == null || contentDisposition.isEmpty()) {
            return result;
        }

        // Split on ';' but keep the first part as the type
        String[] parts = contentDisposition.split(";");
        if (parts.length == 0) {
            return result;
        }

        // First part is the type
        String type = parts[0].trim();
        if (!type.isEmpty()) {
            result.put("type", type);
        }

        // Process remaining parts
        for (int i = 1; i < parts.length; i++) {
            String part = parts[i].trim();
            int eq = part.indexOf('=');
            if (eq == -1) {
                continue; // not a key=value pair
            }

            String key = part.substring(0, eq).trim().toLowerCase();
            String value = part.substring(eq + 1).trim();

            // Strip surrounding quotes if present
            if ((value.startsWith("\"") && value.endsWith("\"")) ||
                (value.startsWith("'") && value.endsWith("'"))) {
                value = value.substring(1, value.length() - 1);
            }

            result.put(key, value);
        }

        return result;
    }
