solutions.solution:
import java.util.*;
import java.util.concurrent.*;

class MessageProducer {
    private final LinkedBlockingQueue<String> messageQueue;
    private final List<String> sentMessages;
    private final int maxRetries;
    private final long retryDelayMs;

    // Default constructor
    public MessageProducer() {
        this.messageQueue = new LinkedBlockingQueue<>();
        this.sentMessages = new ArrayList<>();
        this.maxRetries = 3;
        this.retryDelayMs = 100L;
    }

    /**
     * Generates messages with the given prefix and count, then adds them to
     * both the internal queue and the sentMessages list.
     *
     * @param prefix the prefix for each message
     * @param count  the number of messages to generate
     */
    public void sendMessages(String prefix, int count) {
        for (int i = 1; i <= count; i++) {
            String message = prefix + " " + i;
            // Add to queue
            this.messageQueue.offer(message);
            // Record sent message
            this.sentMessages.add(message);
        }
    }

    /**
     * Returns the internal message queue.
     *
     * @return the LinkedBlockingQueue containing the messages
     */
    public LinkedBlockingQueue<String> getMessageQueue() {
        return this.messageQueue;
    }

    // Optional getters for maxRetries and retryDelayMs if needed elsewhere
    public int getMaxRetries() {
        return maxRetries;
    }

    public long getRetryDelayMs() {
        return retryDelayMs;
    }

    // Optional getter for sentMessages list
    public List<String> getSentMessages() {
        return Collections.unmodifiableList(sentMessages);
    }
}

