class BSTNode {
    int value;
    BSTNode left;
    BSTNode right;

    public BSTNode(int value) {
        this.value = value;
    }
}

class BSTValidator {
    public static boolean isValidBST(BSTNode root) {
        return validate(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private static boolean validate(BSTNode node, long min, long max) {
        if (node == null) {
            return true;
        }

        long val = node.value;
        if (val < min || val > max) {
            return false;
        }

        // Left subtree: values <= node.value
        // Right subtree: values > node.value
        return validate(node.left, min, val) && validate(node.right, val + 1, max);
    }
}

