/**
 * Manages the current octave of a piano and notifies listeners of changes.
 */
public class PianoOctaveManager {
    private int currentOctave;
    private final int minOctave;
    private final int maxOctave;

    // List of registered listeners
    private final List<PianoOctaveChangeListener> listeners = new ArrayList<>();

    /**
     * Creates a new manager with the specified initial octave and bounds.
     *
     * @param initialOctave the starting octave
     * @param minOctave     the minimum allowed octave
     * @param maxOctave     the maximum allowed octave
     * @throws IllegalArgumentException if minOctave > maxOctave
     */
    public PianoOctaveManager(int initialOctave, int minOctave, int maxOctave) {
        if (minOctave > maxOctave) {
            throw new IllegalArgumentException("minOctave cannot be greater than maxOctave");
        }
        this.minOctave = minOctave;
        this.maxOctave = maxOctave;
        this.currentOctave = clamp(initialOctave, minOctave, maxOctave);
    }

    /**
     * Returns the current octave.
     */
    public int getCurrentOctave() {
        return currentOctave;
    }

    /**
     * Adds a listener to be notified of octave changes.
     */
    public void addListener(PianoOctaveChangeListener listener) {
        listeners.add(listener);
    }

    /**
     * Removes a previously added listener.
     */
    public void removeListener(PianoOctaveChangeListener listener) {
        listeners.remove(listener);
    }

    /**
     * Increments the octave by one if it does not exceed {@code maxOctave}.
     *
     * @return {@code true} if the octave was increased, {@code false} otherwise
     */
    public boolean incrementOctave() {
        if (currentOctave < maxOctave) {
            setCurrentOctave(currentOctave + 1);
            return true;
        }
        return false;
    }

    /**
     * Decrements the octave by one if it does not go below {@code minOctave}.
     *
     * @return {@code true} if the octave was decreased, {@code false} otherwise
     */
    public boolean decrementOctave() {
        if (currentOctave > minOctave) {
            setCurrentOctave(currentOctave - 1);
            return true;
        }
        return false;
    }

    // --------------------------------------------------------------------
    // Private helpers
    // --------------------------------------------------------------------

    /**
     * Updates the current octave and notifies listeners of the change.
     */
    private void setCurrentOctave(int newOctave) {
        int oldOctave = currentOctave;
        currentOctave = newOctave;
        notifyListeners(oldOctave, newOctave);
    }

    /**
     * Notifies all registered listeners of an octave change.
     */
    private void notifyListeners(int oldOctave, int newOctave) {
        for (PianoOctaveChangeListener listener : listeners) {
            listener.onOctaveChanged(oldOctave, newOctave);
        }
    }

    /**
     * Clamps a value to the inclusive range [min, max].
