     * @param message the message content
     * @return a list of delivered messages. If the sender is not active,
     *         the list contains the error message:
     *         "Error: User <sender> is not active".
     *         Otherwise, the list contains the formatted message
     *         "[<sender>] <message>" repeated for each recipient.
     */
    public List<String> processMessage(String sender, String message) {
        if (!activeUsers.contains(sender)) {
            return Collections.singletonList(
                "Error: User " + sender + " is not active");
        }

        String formatted = "[" + sender + "] " + message;
        List<String> delivered = new ArrayList<>();

        for (String user : activeUsers) {
            if (!user.equals(sender)) {
                // Deliver to recipient
                userMessages.get(user).add(formatted);
                delivered.add(formatted);
