            return "BookmarkAnalysisResult{" +
                    "totalCount=" + totalCount +
                    ", shortCount=" + shortCount +
                    ", longCount=" + longCount +
                    ", validCount=" + validCount +
                    ", averageLength=" + averageLength +
                    ", longestBookmark='" + longestBookmark + '\'' +
                    ", shortestBookmark='" + shortestBookmark + '\'' +
                    '}';
        }
    }
}

