    private static boolean isLeapYear(int year) {
        if (year % 4 != 0) {
            return false;
        }
        if (year % 100 != 0) {
            return true;
        }
        return year % 400 == 0;
    }

    /**
     * Returns the number of days in the specified month of the specified year.
     *
     * @param month the month (1‑12)
     * @param year  the year
     * @return the number of days in the month
     */
    private static int getDaysInMonth(int month, int year) {
        switch (month) {
            case 1:  // January
            case 3:  // March
            case 5:  // May
            case 7:  // July
            case 8:  // August
            case 10: // October
            case 12: // December
                return 31;
            case 4:  // April
            case 6:  // June
            case 9:  // September
            case 11: // November
                return 30;
            case 2:  // February
                return isLeapYear(year) ? 29 : 28;
            default:
                // This case should never be reached because month is validated elsewhere
                return 0;
        }
    }

    /**
     * Validates a full date. The year must be greater than or equal to 1,
     * the month must be between 1 and 12, and the day must be within the
