import java.util.*;

class AuthService {
    public Map<String, Object> processOAuth2User(String provider,
                                                Map<String, Object> userAttributes,
                                                Map<String, User> existingUsers,
                                                Set<Role> availableRoles) {
        // Validate provider
        if (provider == null || provider.trim().isEmpty()) {
            throw new IllegalArgumentException("Provider must not be null or empty.");
        }

        // Validate userAttributes
        if (userAttributes == null || userAttributes.isEmpty()) {
            throw new IllegalArgumentException("User attributes must not be null or empty.");
        }

        // Extract and validate email
        Object emailObj = userAttributes.get("email");
        if (emailObj == null || !(emailObj instanceof String) || ((String) emailObj).trim().isEmpty()) {
            throw new IllegalArgumentException("User attributes must contain a non‑empty 'email' field.");
        }
        String email = ((String) emailObj).trim();

        User user = existingUsers.get(email);
        String status;

        if (user == null) {
            // Register a new user
            user = registerNewUser(userAttributes, availableRoles);
            user.setEmail(email);
            String prefix = email.split("@")[0];
            user.setUsername(prefix + "_" + provider);

            existingUsers.put(email, user);
            status = "registered";
        } else {
            status = "authenticated";
        }

        Map<String, Object> result = new HashMap<>();
        result.put("status", status);
        result.put("user", user);
        result.put("provider", provider);
        return result;
    }

    /**
     * Creates a new {@link User} instance, populating name and lastname from the
     * supplied {@code userAttributes}.  The user is enabled and assigned the
     * default {@code ROLE_USER} role from {@code availableRoles}.
     *
     * @param userAttributes map containing OAuth2 user attributes
     * @param availableRoles set of roles that can be assigned
     * @return a fully configured {@link User}
     */
    private User registerNewUser(Map<String, Object> userAttributes, Set<Role> availableRoles) {
        String givenName = (String) userAttributes.getOrDefault("given_name", "");
        String familyName = (String) userAttributes.getOrDefault("family_name", "");

        User user = new User();
        user.setName(givenName);
        user.setLastname(familyName);
        user.setEnabled(true);

        // Find the default ROLE_USER role
        Role roleUser = null;
        if (availableRoles != null) {
            for (Role r : availableRoles) {
                if ("ROLE_USER".equals(r.getName())) {
                    roleUser = r;
                    break;
                }
            }
        }

        // If the role is not present, create a new one
        if (roleUser == null) {
            roleUser = new Role("ROLE_USER");
        }

        user.getRoles().add(roleUser);
        return user;
    }
}

