     * Format: [val1,val2,...,valn] where null represents missing nodes.
     * Trailing nulls are omitted.
     */
    public String levelOrder(TreeNode root) {
        if (root == null) {
            return "[]";
        }

        List<String> result = new ArrayList<>();
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node == null) {
                result.add("null");
                continue;
            }
            result.add(String.valueOf(node.val));
            queue.offer(node.left);
            queue.offer(node.right);
        }

        // Remove trailing "null" entries
        int i = result.size() - 1;
        while (i >= 0 && result.get(i).equals("null")) {
            i--;
        }
        result = result.subList(0, i + 1);

        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (int j = 0; j < result.size(); j++) {
            if (j > 0) sb.append(",");
            sb.append(result.get(j));
        }
        sb.append("]");
        return sb.toString();
