/**
 * Manages users: registration, login, and searching.
 */
public class UserManager {
    private final List<User> users;
    private final Map<String, Integer> failedAttempts; // key: lower‑case username
    private final Set<String> lockedAccounts;          // lower‑case usernames

    private static final int MAX_ATTEMPTS = 3;

    public UserManager() {
        this.users = new ArrayList<>();
        this.failedAttempts = new HashMap<>();
        this.lockedAccounts = new HashSet<>();
    }

    /**
     * Registers a new user.
     */
    public Map<String, Object> registerUser(User user) {
        Map<String, Object> result = new HashMap<>();

        if (user == null) {
            result.put("success", false);
            result.put("message", "User cannot be null.");
            return result;
        }

        String username = user.getUsername();
        String password = user.getPassword();

        if (username == null || username.trim().isEmpty() ||
            password == null || password.trim().isEmpty()) {
            result.put("success", false);
            result.put("message", "Username and password cannot be empty.");
            return result;
        }

        for (User existing : users) {
            if (existing.getUsername().equalsIgnoreCase(username)) {
                result.put("success", false);
                result.put("message", "Username already exists.");
                return result;
            }
        }

        users.add(user);
        result.put("success", true);
        result.put("message", "User registered successfully.");
        return result;
    }

    /**
     * Attempts to log in a user.
     */
    public Map<String, Object> loginUser(String username, String password) {
        Map<String, Object> response = new HashMap<>();

        if (username == null || username.trim().isEmpty() ||
            password == null || password.trim().isEmpty()) {
            response.put("success", false);
            response.put("message", "Username and password cannot be empty.");
            response.put("attemptsRemaining", MAX_ATTEMPTS);
            return response;
        }

        String key = username.toLowerCase();
        User found = null;
        for (User u : users) {
            if (u.getUsername().equalsIgnoreCase(username)) {
                found = u;
                break;
            }
        }

        if (found == null) {
            response.put("success", false);
            response.put("message", "User not found.");
            response.put("attemptsRemaining", MAX_ATTEMPTS);
            return response;
        }

        if (lockedAccounts.contains(key)) {
            response.put("success", false);
            response.put("message", "Account locked.");
            response.put("attemptsRemaining", 0);
            return response;
        }

        if (found.getPassword().equals(password)) {
            // Successful login
            failedAttempts.remove(key);
            response.put("success", true);
            response.put("message", "Login successful.");
            response.put("user", found);
            return response;
        } else {
            // Failed attempt
            int attempts = failedAttempts.getOrDefault(key, 0) + 1;
            failedAttempts.put(key, attempts);
            int attemptsRemaining = MAX_ATTEMPTS - attempts;

            if (attempts >= MAX_ATTEMPTS) {
                lockedAccounts.add(key);
                response.put("success", false);
                response.put("message", "Account locked due to too many failed attempts.");
                response.put("attemptsRemaining", 0);
            } else {
                response.put("success", false);
                response.put("message", "Invalid credentials.");
                response.put("attemptsRemaining", attemptsRemaining);
            }
            return response;
        }
    }

    /**
     * Searches users by optional username and email criteria, supports partial
     * (case‑insensitive) matching, and returns paginated results.
     *
     * @param username  optional username fragment (null or empty means ignore)
     * @param email     optional email fragment (null or empty means ignore)
     * @param pageNumber 1‑based page number
     * @param pageSize   number of items per page
     * @return list of users matching the criteria for the requested page
     */
    public List<User> searchUsers(String username, String email, int pageNumber, int pageSize) {
        List<User> filtered = new ArrayList<>();

        // Normalize search terms for case‑insensitive comparison
        String usernameFilter = (username == null) ? null : username.toLowerCase();
        String emailFilter = (email == null) ? null : email.toLowerCase();

        for (User u : users) {
            boolean matches = true;

            if (usernameFilter != null && !usernameFilter.isEmpty()) {
                if (u.getUsername() == null ||
                    !u.getUsername().toLowerCase().contains(usernameFilter)) {
                    matches = false;
                }
            }

            if (matches && emailFilter != null && !emailFilter.isEmpty()) {
                if (u.getEmail() == null ||
                    !u.getEmail().toLowerCase().contains(emailFilter)) {
                    matches = false;
                }
            }

            if (matches) {
                filtered.add(u);
            }
        }

        // Pagination
        if (pageNumber < 1 || pageSize <= 0) {
            return new ArrayList<>();
        }

        int startIndex = (pageNumber - 1) * pageSize;
        if (startIndex >= filtered.size()) {
            return new ArrayList<>();
        }

        int endIndex = Math.min(startIndex + pageSize, filtered.size());
        return new ArrayList<>(filtered.subList(startIndex, endIndex));
    }
}
