/**
 * PathFinder provides a method to compute the number of unique paths
 * from the top-left corner to the bottom-right corner of a rectangular grid.
 * Movement is restricted to only right or down steps.
 *
 * The result is returned as an instance of the nested {@code PathResult} class,
 * which contains the total number of unique paths.
 */
public class PathFinder {

    /**
     * Result object that holds the total number of unique paths.
     */
    public static class PathResult {
        private final long totalPaths;

        public PathResult(long totalPaths) {
            this.totalPaths = totalPaths;
        }

        public long getTotalPaths() {
            return totalPaths;
        }

        @Override
        public String toString() {
            return "PathResult{totalPaths=" + totalPaths + '}';
        }
    }

    /**
     * Computes the number of unique paths from the top-left corner to the
     * bottom-right corner of the given grid. Movement is allowed only to the
     * right or down.
     *
     * @param grid a 2D integer array representing the grid (values are ignored)
     * @return a {@code PathResult} containing the total number of unique paths
     */
    public PathResult findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathResult(0);
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // Use a 1D DP array to save space: dp[j] represents the number of ways
        // to reach cell (currentRow, j).
        long[] dp = new long[cols];
        // Initialize the first cell
        dp[0] = 1;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i == 0 && j == 0) {
                    continue; // already initialized
                }
                long fromTop = (i > 0) ? dp[j] : 0;
                long fromLeft = (j > 0) ? dp[j - 1] : 0;
                dp[j] = fromTop + fromLeft;
            }
        }

        return new PathResult(dp[cols - 1]);
    }
}

