            sb.append("Total Paths: ").append(totalPaths).append('\n');
            sb.append("Max Path Length: ").append(maxPathLength).append('\n');
            sb.append("Min Path Length: ").append(minPathLength).append('\n');
            sb.append("Sample Path: ").append(samplePath);
            return sb.toString();
        }
    }

    /**
     * Computes the number of unique paths from the top-left corner to the
     * bottom-right corner of the given grid. Movement is allowed only to the
     * right or down. The method also provides additional analysis such as
     * path lengths and a sample path.
     *
     * @param grid a 2D integer array representing the grid (values are ignored)
     * @return a {@code PathAnalysis} containing the total number of unique paths,
     *         the maximum and minimum path lengths, and a sample path
     */
    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // Dynamic programming: 1D array to store number of ways to reach each cell in the current row
        long[] dp = new long[cols];
        dp[0] = 1; // start cell

        for (int i = 0; i < rows; i++) {
