            sb.append("Sample Path: ").append(samplePath);
            return sb.toString();
        }
    }

    /**
     * Computes the number of unique paths from the top-left corner to the
     * bottom-right corner of the given grid, taking obstacles into account.
     * The method also provides additional analysis such as path lengths
     * and a sample path that only traverses cells with value 0.
     *
     * @param grid a 2D integer array where 0 represents a free cell and 1
     *             represents an obstacle
     * @return a {@code PathAnalysis} containing the total number of unique
     *         paths, the maximum and minimum path lengths, and a sample path
     */
    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // 2‑D DP array to store number of ways to reach each cell
        long[][] dp = new long[rows][cols];

        // Initialize start cell
        if (grid[0][0] == 0) {
            dp[0][0] = 1;
        } else {
            // Start is blocked – no paths exist
            return new PathAnalysis(0, 0, 0, new ArrayList<>());
