public class EmployeeValidator {

    /* ---------- Email validation ---------- */
    private static final String EMAIL_REGEX =
            "^[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}$";

    /* ---------- Password validation ---------- */
    private static final int PASSWORD_MIN_LENGTH = 8;
    private static final int PASSWORD_MAX_LENGTH = 255;
    private static final String SPECIAL_CHARS = "!@#$%^&*()";

    private static final String MSG_PASSWORD_MIN =
            "Password must be at least 8 characters long";
    private static final String MSG_PASSWORD_MAX =
            "Password must be at most 255 characters long";
    private static final String MSG_PASSWORD_UPPER =
            "Password must contain at least one uppercase letter";
    private static final String MSG_PASSWORD_LOWER =
            "Password must contain at least one lowercase letter";
    private static final String MSG_PASSWORD_DIGIT =
            "Password must contain at least one digit";
    private static final String MSG_PASSWORD_SPECIAL =
            "Password must contain at least one special character (!@#$%^&*())";

    /**
     * Validates the employee data.
     *
     * @param email    the employee's email address
     * @param password the employee's password
     * @param fcmToken the employee's FCM token
     * @throws IllegalArgumentException if any argument is null/empty,
     *                                  if the email is longer than 30 characters,
     *                                  if the email format is invalid,
     *                                  or if the password does not satisfy any rule
     */
    public static void validateEmployee(String email, String password, String fcmToken) {
        /* ---------- Null / empty checks ---------- */
        if (email == null || email.isEmpty() ||
            password == null || password.isEmpty() ||
            fcmToken == null || fcmToken.isEmpty()) {
            throw new IllegalArgumentException("Invalid employee data");
        }

        /* ---------- Email length ---------- */
        if (email.length() > 30) {
            throw new IllegalArgumentException("Email must be 30 characters or less");
        }

        /* ---------- Email format ---------- */
        if (!email.toUpperCase().matches(EMAIL_REGEX)) {
            throw new IllegalArgumentException("Invalid email format");
        }

        /* ---------- Password length ---------- */
        if (password.length() < PASSWORD_MIN_LENGTH) {
            throw new IllegalArgumentException(MSG_PASSWORD_MIN);
        }
        if (password.length() > PASSWORD_MAX_LENGTH) {
            throw new IllegalArgumentException(MSG_PASSWORD_MAX);
        }

        /* ---------- Password character checks ---------- */
        if (!containsUpperCase(password)) {
            throw new IllegalArgumentException(MSG_PASSWORD_UPPER);
        }
        if (!containsLowerCase(password)) {
            throw new IllegalArgumentException(MSG_PASSWORD_LOWER);
        }
        if (!containsDigit(password)) {
            throw new IllegalArgumentException(MSG_PASSWORD_DIGIT);
        }
        if (!containsSpecialChar(password)) {
            throw new IllegalArgumentException(MSG_PASSWORD_SPECIAL);
        }
    }

    /* ---------- Helper methods ---------- */
    private static boolean containsUpperCase(String s) {
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) return true;
        }
        return false;
    }

    private static boolean containsLowerCase(String s) {
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) return true;
        }
        return false;
    }

    private static boolean containsDigit(String s) {
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) return true;
        }
        return false;
    }

    private static boolean containsSpecialChar(String s) {
        for (char c : s.toCharArray()) {
            if (SPECIAL_CHARS.indexOf(c) >= 0) return true;
        }
        return false;
    }
}

