import java.util.ArrayList;
import java.util.List;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    public TreeNode(int val) {
        this.val = val;
    }
}

class TreeAnalysisResult {
    List<List<Integer>> paths = new ArrayList<>();
    int maxDepth = 0;
    int leafCount = 0;
    boolean hasPathSum = false;

    @Override
    public String toString() {
        return "Paths: " + paths + "\n" +
               "Max Depth: " + maxDepth + "\n" +
               "Leaf Count: " + leafCount + "\n" +
               "Has Path Sum: " + hasPathSum;
    }
}

class TreePathAnalyzer {
    public TreeAnalysisResult analyzeTreePaths(TreeNode root, Integer targetSum) {
        TreeAnalysisResult result = new TreeAnalysisResult();
        if (root == null) {
            return result;
        }

        List<Integer> currentPath = new ArrayList<>();
        traverseTree(root, currentPath, result, targetSum, 0);

        return result;
    }

    private void traverseTree(TreeNode node, List<Integer> currentPath,
                              TreeAnalysisResult result, Integer targetSum,
                              int currentSum) {
        if (node == null) {
            return;
        }

        // Add current node to the path and update sum
        currentPath.add(node.val);
        currentSum += node.val;

        // Update maximum depth
        result.maxDepth = Math.max(result.maxDepth, currentPath.size());

        // If leaf node, record path, update leaf count, and check target sum
        if (node.left == null && node.right == null) {
            result.paths.add(new ArrayList<>(currentPath));
            result.leafCount++;

            if (targetSum != null && currentSum == targetSum) {
                result.hasPathSum = true;
            }
        }

        // Recurse on children
        traverseTree(node.left, currentPath, result, targetSum, currentSum);
        traverseTree(node.right, currentPath, result, targetSum, currentSum);

        // Backtrack: remove current node from path
        currentPath.remove(currentPath.size() - 1);
    }
}
