    public PaginationResult calculatePagination(int totalItems, int pageSize, int currentPage) {
        if (totalItems < 0) {
            throw new IllegalArgumentException("totalItems cannot be negative");
        }
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be greater than 0");
        }
        if (currentPage <= 0) {
            throw new IllegalArgumentException("currentPage must be greater than 0");
        }

        int totalPages = (totalItems == 0) ? 0 : (int) Math.ceil((double) totalItems / pageSize);

        // Cap currentPage at totalPages if it exceeds
        if (currentPage > totalPages) {
            currentPage = totalPages;
        }

        int startItem;
        int endItem;
        if (totalItems == 0) {
            startItem = 0;
            endItem = 0;
        } else {
            startItem = (currentPage - 1) * pageSize + 1;
            endItem = Math.min(currentPage * pageSize, totalItems);
        }

        List<Integer> visiblePages = calculateVisiblePages(totalPages, currentPage);

        return new PaginationResult(totalItems, pageSize, currentPage, totalPages,
                startItem, endItem, visiblePages);
    }

    /**
     * Builds a list of visible page numbers for the pagination control.
     * The list contains the first page, the last page, and up to two pages before
     * and after the current page. Ellipses (-1) are inserted where page ranges
     * are skipped. Consecutive ellipses are never added.
     *
     * @param totalPages  total number of pages (may be 0)
     * @param currentPage current page number (1‑based, may be 0 if totalPages==0)
     * @return list of page numbers and -1 for ellipses
     */
    private List<Integer> calculateVisiblePages(int totalPages, int currentPage) {
        List<Integer> pages = new ArrayList<>();

        if (totalPages <= 0) {
            return pages; // empty list for no items
        }

        // Determine the range of pages around the current page
        int startRange = Math.max(1, currentPage - 2);
        int endRange = Math.min(totalPages, currentPage + 2);

        // Always include the first page
        pages.add(1);

        // Ellipsis after first page if there is a gap
        if (startRange > 2) {
            pages.add(-1);
        }

        // Add the middle range, skipping duplicates of first/last pages
        for (int i = startRange; i <= endRange; i++) {
            if (i != 1 && i != totalPages) {
                pages.add(i);
            }
        }

        // Ellipsis before last page if there is a gap
        if (endRange < totalPages - 1) {
            pages.add(-1);
        }

        // Always include the last page (unless it's the same as the first)
        if (totalPages != 1) {
            pages.add(totalPages);
        }

        return pages;
    }
}

