import java.util.ArrayList;
import java.util.Collections;

class PatternGenerator {
    public static List<String> generateSandClock(int size, boolean reverse, boolean useLetters) {
        if (size <= 0) {
            throw new IllegalArgumentException("Size must be positive");
        }

        List<String> pattern = new ArrayList<>();

        // Upper half (including the middle line)
        for (int i = 0; i < size; i++) {
            int count = size - i;
            char ch = useLetters ? (char)('A' + i) : '*';
            pattern.add(repeatChar(ch, count));
        }

        // Lower half
        for (int j = 1; j < size; j++) {
            int count = j + 1;
            int lineIndex = size - 1 - j; // to mirror the upper half
            char ch = useLetters ? (char)('A' + lineIndex) : '*';
            pattern.add(repeatChar(ch, count));
        }

        if (reverse) {
            Collections.reverse(pattern);
        }

        return pattern;
    }

    private static String repeatChar(char ch, int times) {
        StringBuilder sb = new StringBuilder(times);
        for (int i = 0; i < times; i++) {
            sb.append(ch);
        }
        return sb.toString();
    }
}

