import java.util.ArrayList;
import java.util.List;

class TaskManager {
    private List<String> tasks;
    private String filename;

    public TaskManager(String filename) {
        this.filename = filename;
        this.tasks = new ArrayList<>();
    }

    /**
     * Adds a new task with automatic numbering.
     *
     * @param taskDescription the description of the task
     * @return true if the task was added; false if the description is null or empty
     */
    public boolean addTask(String taskDescription) {
        if (taskDescription == null || taskDescription.trim().isEmpty()) {
            return false;
        }
        int number = tasks.size() + 1;
        String formattedTask = number + ". " + taskDescription.trim();
        tasks.add(formattedTask);
        return true;
    }

    /**
     * Deletes a task based on the provided position string.
     *
     * @param position the position of the task to delete (1‑based index) or "-1" to clear all tasks
     * @return true if the task was successfully deleted or all tasks cleared; false otherwise
     */
    public boolean deleteTask(String position) {
        if (position == null) {
            return false;
        }
        String trimmed = position.trim();
        if ("-1".equals(trimmed)) {
            tasks.clear();
            return true;
        }

        int index;
        try {
            index = Integer.parseInt(trimmed);
        } catch (NumberFormatException e) {
            return false;
        }

        if (index < 1 || index > tasks.size()) {
            return false;
        }

        tasks.remove(index - 1);
        renumberTasks();
        return true;
    }

    /**
     * Renumbers all tasks so that their indices are contiguous starting from 1.
     * The numbering is updated in the task descriptions themselves.
     */
    private void renumberTasks() {
        for (int i = 0; i < tasks.size(); i++) {
            String task = tasks.get(i);
            int dotIndex = task.indexOf(". ");
            String description = (dotIndex != -1) ? task.substring(dotIndex + 2) : task;
            tasks.set(i, (i + 1) + ". " + description);
        }
    }

    /**
     * Returns a copy of the internal task list to prevent external modification.
     *
     * @return a new list containing the current tasks
     */
    public List<String> getTasks() {
        return new ArrayList<>(tasks);
    }

    /**
     * Returns the current number of tasks.
     *
     * @return the size of the task list
     */
    public int getTaskCount() {
        return tasks.size();
    }
}

