                    for (String value : processedItem.values()) {
                        if (value == null || value.isEmpty()) {
                            hasEmpty = true;
                            break;
                        }
                    }
                    if (hasEmpty) {
                        emptyFieldCount++;
                    }
                }

                // Count special cases based on 'code' prefix
                String codeValue = processedItem.get("code");
                if (codeValue != null && codeValue.startsWith("SPECIAL")) {
                    specialCaseCount++;
                }

                // Merge 'code' and 'name' if requested
                if (mergeFields && processedItem.containsKey("code") && processedItem.containsKey("name")) {
                    String code = processedItem.get("code");
                    String name = processedItem.get("name");
                    String merged = code + separator + name;

                    // Apply maxLength truncation if configured
                    if (maxLength > 0 && merged.length() > maxLength) {
                        merged = merged.substring(0, maxLength) + "...";
                    }

                    processedItem.put("merged", merged);
                    transformedCount++;
                }

                processedItems.add(processedItem);
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("processedItems", processedItems);
        result.put("totalItems", totalItems);
        result.put("emptyFieldCount", emptyFieldCount);
        result.put("transformedCount", transformedCount);
        result.put("specialCaseCount", specialCaseCount);

        return result;
    }
}
