import java.util.*;

public class BracketValidator {

    /**
     * Validates whether the brackets in the input string are balanced.
     *
     * @param input the string to validate
     * @return a map containing a single entry with key "balanced" and a Boolean value
     */
    public static Map<String, Object> validateBrackets(String input) {
        Map<String, Object> result = new HashMap<>();
        if (input == null) {
            result.put("balanced", false);
            return result;
        }

        Deque<Character> stack = new ArrayDeque<>();

        for (char ch : input.toCharArray()) {
            switch (ch) {
                case '(':
                case '[':
                case '{':
                    stack.push(ch);
                    break;
                case ')':
                    if (stack.isEmpty() || stack.pop() != '(') {
                        result.put("balanced", false);
                        return result;
                    }
                    break;
                case ']':
                    if (stack.isEmpty() || stack.pop() != '[') {
                        result.put("balanced", false);
                        return result;
                    }
                    break;
                case '}':
                    if (stack.isEmpty() || stack.pop() != '{') {
                        result.put("balanced", false);
                        return result;
                    }
                    break;
                default:
                    // ignore non-bracket characters
                    break;
            }
        }

        result.put("balanced", stack.isEmpty());
        return result;
    }
}

