class MessageProcessor {
    private final Set<String> processedMessageIds;
    private final Map<String, Function<String, String>> handlers;

    // Routing rules stored in insertion order
    private final List<Rule> routingRules;

    public MessageProcessor() {
        this.processedMessageIds = new HashSet<>();
        this.handlers = new HashMap<>();
        this.routingRules = new ArrayList<>();
    }

    /** Registers a handler for a specific message type. */
    public void addHandler(String messageType, Function<String, String> handler) {
        if (messageType == null || handler == null) {
            throw new IllegalArgumentException("Message type and handler must not be null");
        }
        handlers.put(messageType, handler);
    }

    /** Processes a message with deduplication and type-specific handling. */
    public String processMessage(String messageId, String messageType, String content) {
        if (processedMessageIds.contains(messageId)) {
            return "Message already processed";
        }
        processedMessageIds.add(messageId);

        Function<String, String> handler = handlers.get(messageType);
        if (handler == null) {
            return "No handler found for message type: " + messageType;
        }
        return handler.apply(content);
    }

    /** Adds a routing rule with a pattern and a handler key. */
    public void addRoutingRule(String pattern, String handlerKey) {
        if (pattern == null || handlerKey == null) {
            throw new IllegalArgumentException("Pattern and handler key must not be null");
        }
        routingRules.add(new Rule(pattern, handlerKey));
    }

    /**
     * Finds the handler key for the first routing rule whose pattern matches the given path.
     * @param path the request path to match
     * @return the handler key of the first matching rule, or null if none matches
     */
    public String findHandlerKey(String path) {
        for (Rule rule : routingRules) {
            if (matches(rule.pattern, path)) {
                return rule.handlerKey;
            }
        }
        return null;
    }

    /* ---------- Private helper classes and methods ---------- */

    /** Simple pair to store a routing rule. */
    private static class Rule {
        final String pattern;
        final String handlerKey;

        Rule(String pattern, String handlerKey) {
            this.pattern = pattern;
            this.handlerKey = handlerKey;
        }
    }

    /** Splits a path into non‑empty segments. */
    private static List<String> splitPath(String path) {
        String[] parts = path.split("/");
        List<String> segs = new ArrayList<>();
        for (String part : parts) {
            if (!part.isEmpty()) {
                segs.add(part);
            }
        }
        return segs;
    }

    /** Determines whether a pattern matches a path. */
    private static boolean matches(String pattern, String path) {
        List<String> pSegs = splitPath(pattern);
        List<String> pathSegs = splitPath(path);
        return matchHelper(pSegs, 0, pathSegs, 0);
    }

    /** Recursive helper for pattern matching with '#' wildcard. */
    private static boolean matchHelper(List<String> p, int i, List<String> s, int j) {
        if (i == p.size() && j == s.size()) {
            return true;
        }
        if (i == p.size()) {
            return false;
        }
        String pat = p.get(i);
        if ("#".equals(pat)) {
            // '#' must match at least one segment
            for (int k = j + 1; k <= s.size(); k++) {
                if (matchHelper(p, i + 1, s, k)) {
                    return true;
                }
            }
            return false;
        } else {
            if (j >= s.size()) {
                return false;
            }
            if (!pat.equals(s.get(j))) {
                return false;
            }
            return matchHelper(p, i + 1, s, j + 1);
        }
    }
}

