/**
 * Represents a permission with a URI and an HTTP method.
 */
class PermissionInfo {
    private final String uri;
    private final String method;

    public PermissionInfo(String uri, String method) {
        this.uri = uri;
        this.method = method;
    }

    public String getUri() {
        return uri;
    }

    public String getMethod() {
        return method;
    }

    @Override
    public String toString() {
        return "PermissionInfo{uri='" + uri + "', method='" + method + "'}";
    }
}

/**
 * Validates whether a request matches any of the provided permissions.
 */
class PermissionValidator {
    // Matches a non‑empty alphanumeric segment
    private static final Pattern ALPHANUMERIC_SEGMENT = Pattern.compile("[A-Za-z0-9]+");

    /**
     * Checks if the request URI and method match any permission in the list.
     *
     * @param permissions   list of permissions to validate against (may be null or empty)
     * @param requestUri    the request URI to compare
     * @param requestMethod the request HTTP method to compare (case‑insensitive)
     * @return true if any permission matches both URI and method; false otherwise
     */
    public static boolean hasPermission(List<PermissionInfo> permissions,
                                       String requestUri,
                                       String requestMethod) {
        if (permissions == null || permissions.isEmpty() || requestUri == null || requestMethod == null) {
            return false;
        }

        for (PermissionInfo permission : permissions) {
            if (permission == null) {
                continue;
            }

            // Method must match case‑insensitively
            if (!permission.getMethod().equalsIgnoreCase(requestMethod)) {
                continue;
            }

            String permUri = permission.getUri();

            // Wildcard handling
            if (permUri.contains("{*}")) {
                String[] permSegments = permUri.split("/", -1);
                String[] reqSegments = requestUri.split("/", -1);

                if (permSegments.length != reqSegments.length) {
                    continue;
                }

                boolean match = true;
                for (int i = 0; i < permSegments.length; i++) {
                    String permSeg = permSegments[i];
                    String reqSeg = reqSegments[i];

                    if ("{*}".equals(permSeg)) {
                        if (!ALPHANUMERIC_SEGMENT.matcher(reqSeg).matches()) {
                            match = false;
                            break;
                        }
                    } else {
                        if (!permSeg.equals(reqSeg)) {
                            match = false;
                            break;
                        }
                    }
                }

                if (match) {
                    return true;
                }
            } else {
                // Exact match
                if (permUri.equals(requestUri)) {
                    return true;
                }

                // Prefix match: permission URI is a full prefix followed by '/'
                if (requestUri.startsWith(permUri) &&
                    requestUri.length() > permUri.length() &&
                    requestUri.charAt(permUri.length()) == '/') {
                    return true;
                }
            }
        }

        return false;
    }
}
