            Constructor<?>[] publicConstructors = clazz.getConstructors();
            if (publicConstructors.length == 0) {
                report.append("  None\n");
            } else {
                for (Constructor<?> ctor : publicConstructors) {
                    report.append("  ").append(getConstructorSignature(ctor)).append("\n");
                }
            }
            report.append("\n");

            // Declared constructors
            report.append("Declared Constructors:\n");
            Constructor<?>[] declaredConstructors = clazz.getDeclaredConstructors();
            if (declaredConstructors.length == 0) {
                report.append("  None\n");
            } else {
                for (Constructor<?> ctor : declaredConstructors) {
                    report.append("  ").append(getConstructorSignature(ctor)).append("\n");
                }
            }

        } catch (ClassNotFoundException e) {
            report.append("Error: Class not found - ").append(fullyQualifiedName);
        } catch (Exception e) {
            report.append("Error: Unable to analyze class - ").append(fullyQualifiedName)
                  .append(" (").append(e.getMessage()).append(")");
        }
        return report.toString();
    }

    /**
     * Builds a readable signature for a constructor.
     *
     * @param ctor the constructor to format
     * @return a string representation of the constructor signature
     */
    private static String getConstructorSignature(Constructor<?> ctor) {
        StringBuilder sb = new StringBuilder();

        // Modifiers (public, private, etc.)
        int mod = ctor.getModifiers();
        if (mod != 0) {
            sb.append(Modifier.toString(mod)).append(" ");
        }

        // Constructor name
        sb.append(ctor.getDeclaringClass().getSimpleName()).append("(");

        // Parameter types
        Class<?>[] params = ctor.getParameterTypes();
        for (int i = 0; i < params.length; i++) {
            sb.append(getTypeName(params[i]));
            if (i < params.length - 1) {
