import java.util.ArrayList;
import java.util.List;

/** Node of a singly linked list holding an integer value. */
class LinkedListNode {
    int data;
    LinkedListNode next;

    LinkedListNode(int data) {
        this.data = data;
        this.next = null;
    }
}

/** Utility class that swaps two nodes of a linked list by index. */
class LinkedListSwapper {

    /**
     * Swaps the nodes at positions i and j (0‑based) by adjusting pointers.
     * Assumes i and j are distinct, valid indices and the list has enough nodes.
     *
     * @param head the original head of the list
     * @param i    the first index
     * @param j    the second index
     * @return the new head of the list after swapping
     */
    static LinkedListNode swapNodes(LinkedListNode head, int i, int j) {
        if (i == j) return head;          // nothing to do

        // Ensure i < j for easier handling
        if (i > j) {
            int temp = i;
            i = j;
            j = temp;
        }

        // Find node at position i and its predecessor
        LinkedListNode prevX = null;
        LinkedListNode currX = head;
        int idx = 0;
        while (idx < i) {
            prevX = currX;
            currX = currX.next;
            idx++;
        }

        // Find node at position j and its predecessor
        LinkedListNode prevY = null;
        LinkedListNode currY = head;
        idx = 0;
        while (idx < j) {
            prevY = currY;
            currY = currY.next;
            idx++;
        }

        // If nodes are adjacent, handle specially
        if (currX.next == currY) { // currX before currY
            if (prevX != null) prevX.next = currY;
            else head = currY;

            currX.next = currY.next;
            currY.next = currX;
        } else if (currY.next == currX) { // currY before currX
            if (prevY != null) prevY.next = currX;
            else head = currX;

            currY.next = currX.next;
            currX.next = currY;
        } else { // non‑adjacent nodes
            if (prevX != null) prevX.next = currY;
            else head = currY;

            if (prevY != null) prevY.next = currX;
            else head = currX;

            // Swap next pointers
            LinkedListNode temp = currX.next;
            currX.next = currY.next;
            currY.next = temp;
        }

        return head;
    }

    /**
     * Creates a linked list from a list of integers.
     *
     * @param values the list of integer values
     * @return the head of the created linked list
     */
    static LinkedListNode createLinkedList(List<Integer> values) {
        if (values.isEmpty()) return null;
        LinkedListNode head = new LinkedListNode(values.get(0));
        LinkedListNode current = head;
        for (int i = 1; i < values.size(); i++) {
            current.next = new LinkedListNode(values.get(i));
            current = current.next;
        }
        return head;
    }

    /**
     * Converts a linked list back into a list of integers.
     *
     * @param head the head of the linked list
     * @return a list containing the data from the linked list
     */
    static List<Integer> linkedListToList(LinkedListNode head) {
        List<Integer> result = new ArrayList<>();
        LinkedListNode current = head;
        while (current != null) {
            result.add(current.data);
            current = current.next;
        }
        return result;
    }
}

/** Example usage of the swap utility. */
public class Main {
    public static void main(String[] args) {
        List<Integer> original = List.of(10, 20, 30, 40, 50);
        LinkedListNode head = LinkedListSwapper.createLinkedList(original);

        // Swap nodes at indices 1 and 3 (values 20 and 40)
        head = LinkedListSwapper.swapNodes(head, 1, 3);

        List<Integer> swapped = LinkedListSwapper.linkedListToList(head);
        System.out.println(swapped); // prints [10, 40, 30, 20, 50]
    }
}

