    public static void main(String[] args) {
        List<Integer> original = List.of(10, 20, 30, 40, 50);
        LinkedListNode head = LinkedListSwapper.createLinkedList(original);

        // Swap first and last nodes
        head = LinkedListSwapper.swapNodes(head, 0, 4);
        System.out.println(LinkedListSwapper.linkedListToList(head)); // [50, 20, 30, 40, 10]

        // Swap adjacent nodes
        head = LinkedListSwapper.swapNodes(head, 1, 2);
        System.out.println(LinkedListSwapper.linkedListToList(head)); // [50, 30, 20, 40, 10]

        // Swap nodes where one is head and the other is middle
        head = LinkedListSwapper.swapNodes(head, 0, 3);
        System.out.println(LinkedListSwapper.linkedListToList(head)); // [40, 30, 20, 50, 10]

        // Attempt to swap with out‑of‑bounds index
        head = LinkedListSwapper.swapNodes(head, 0, 10);
        System.out.println(LinkedListSwapper.linkedListToList(head)); // unchanged

        // Swap same indices (no change)
