        if (!nodes.containsKey(startNodeId) || !nodes.containsKey(endNodeId)) {
            throw new IllegalArgumentException(
                    "Node not found: one or both specified nodes do not exist.");
        }
        long id = nextRelationshipId++;
        relationships.put(id, new Relationship(id, startNodeId, endNodeId, type, properties));
        return id;
    }

    /** Returns formatted information about a node and its relationships. */
    public String getNodeInfo(long nodeId) {
        Node node = nodes.get(nodeId);
        if (node == null) {
            throw new IllegalArgumentException("Error: Invalid node information requested.");
        }

        StringBuilder sb = new StringBuilder();
        sb.append("Node ID: ").append(nodeId).append("\n");
        sb.append("Properties: ").append(node.getProperties()).append("\n");
        sb.append("Relationships:\n");

        List<Relationship> related = new ArrayList<>();
        for (Relationship r : relationships.values()) {
            if (r.getStartNodeId() == nodeId || r.getEndNodeId() == nodeId) {
                related.add(r);
            }
        }

        if (related.isEmpty()) {
            sb.append("None");
        } else {
            for (Relationship r : related) {
                sb.append(r.getId())
                  .append(" [").append(r.getType()).append("] ")
                  .append(r.getStartNodeId()).append(" -> ")
                  .append(r.getEndNodeId()).append(" ")
                  .append(r.getProperties()).append("\n");
            }
            sb.setLength(sb.length() - 1); // remove trailing newline
        }

        return sb.toString();
    }

    /** Deletes a node and all relationships connected to it. */
    public void deleteNode(long nodeId) {
        if (!nodes.containsKey(nodeId)) {
            throw new IllegalArgumentException("Node not found: " + nodeId);
        }

        // Remove all relationships involving this node
        List<Long> toRemove = new ArrayList<>();
        for (Map.Entry<Long, Relationship> entry : relationships.entrySet()) {
            Relationship r = entry.getValue();
            if (r.getStartNodeId() == nodeId || r.getEndNodeId() == nodeId) {
                toRemove.add(entry.getKey());
            }
        }
        for (Long relId : toRemove) {
            relationships.remove(relId);
        }

        // Remove the node itself
        nodes.remove(nodeId);
    }

    // Optional helper methods
    public Node getNode(long id) {
        return nodes.get(id);
    }

    public Relationship getRelationship(long id) {
        return relationships.get(id);
    }

    /** Internal representation of a node. */
    private static class Node {
        private final long id;
        private final Map<String, Object> properties;

        public Node(long id, Map<String, Object> properties) {
            this.id = id;
            this.properties = new HashMap<>(properties != null ? properties : new HashMap<>());
        }

        public Map<String, Object> getProperties() {
            return Map.copyOf(properties);
        }
    }

    /** Internal representation of a relationship. */
    private static class Relationship {
        private final long id;
        private final long startNodeId;
        private final long endNodeId;
        private final String type;
        private final Map<String, Object> properties;

        public Relationship(long id, long startNodeId, long endNodeId,
                            String type, Map<String, Object> properties) {
            this.id = id;
            this.startNodeId = startNodeId;
            this.endNodeId = endNodeId;
            this.type = type;
            this.properties = new HashMap<>(properties != null ? properties : new HashMap<>());
        }

        public long getId() {
            return id;
        }

        public long getStartNodeId() {
            return startNodeId;
        }

        public long getEndNodeId() {
            return endNodeId;
        }

        public String getType() {
            return type;
        }

        public Map<String, Object> getProperties() {
            return Map.copyOf(properties);
        }
    }
}
