import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

/**
 * Utility class that executes a {@link Callable} in a separate thread
 * and returns its result within a specified timeout.
 */
public class ThreadExecutor {

    /**
     * Executes the given task in a new thread and returns its result.
     *
     * @param task       the {@link Callable} to execute
     * @param timeoutMs  maximum time to wait for the task to finish (in milliseconds)
     * @param <T>        the type of the result returned by the task
     * @return the result of the task
     * @throws TimeoutException if the task does not finish within the timeout
     * @throws Exception        if the task throws an exception
     */
    public static <T> T executeTaskWithTimeout(Callable<T> task, long timeoutMs)
            throws Exception {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        Future<T> future = executor.submit(task);
        try {
            return future.get(timeoutMs, TimeUnit.MILLISECONDS);
        } catch (TimeoutException e) {
            future.cancel(true); // attempt to stop the task
            throw new TimeoutException(
                    "Task timed out after " + timeoutMs + " ms");
        } finally {
            executor.shutdownNow();
        }
    }
}

/**
 * Sample implementation of a {@link Callable} that sleeps for a given
 * amount of time and then returns a formatted string.
 */
class SampleTask implements Callable<String> {
    private final String name;
    private final long sleepTimeMs;

    public SampleTask(String name, long sleepTimeMs) {
        this.name = name;
        this.sleepTimeMs = sleepTimeMs;
    }

    @Override
    public String call() throws Exception {
        System.out.println("Task " + name + " started.");
        Thread.sleep(sleepTimeMs);
        return "Result from " + name + " after " + sleepTimeMs + "ms";
    }
}

/**
 * Demo class to show how to use ThreadExecutor and SampleTask.
 */
class Main {
    public static void main(String[] args) {
        try {
            String result = ThreadExecutor.executeTaskWithTimeout(
                    new SampleTask("A", 1000), 2000);
            System.out.println(result);
        } catch (TimeoutException e) {
            System.err.println("The task timed out: " + e.getMessage());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

