import java.util.concurrent.TimeoutException;

/**
 * Utility class that executes a {@link Callable} in a separate thread
 * and returns its result within a specified timeout.
 */
public class ThreadExecutor {

    /**
     * Executes the given task in a new thread and returns its result.
     *
     * @param task       the {@link Callable} to execute
     * @param timeoutMs  maximum time to wait for the task to finish (in milliseconds)
     * @param <T>        the type of the result returned by the task
     * @return the result of the task
     * @throws TimeoutException if the task does not finish within the timeout
     * @throws Exception        if the task throws an exception
     */
    public static <T> T executeTaskWithTimeout(Callable<T> task, long timeoutMs)
            throws Exception {
        FutureTask<T> futureTask = new FutureTask<>(task);
        Thread worker = new Thread(futureTask);
        worker.start();

        try {
            worker.join(timeoutMs);
        } catch (InterruptedException e) {
            // If the current thread is interrupted while waiting,
            // propagate the interruption and attempt to stop the worker.
            worker.interrupt();
            throw e;
        }

        if (worker.isAlive()) {
            // Timeout occurred – interrupt the worker thread.
            worker.interrupt();
            // Wait a short moment for the thread to terminate.
            worker.join(100);
            throw new TimeoutException(
                    "The task does not complete within the specified timeout period.");
        }

        // The task finished within the timeout; retrieve its result.
        return futureTask.get(); // may throw ExecutionException
    }
}

