import java.util.HashMap;
import java.util.Map;

public class AuthenticationService {

    /**
     * Authenticates a user based on email/password or Google token.
     *
     * @param email       the user's email address
     * @param password    the user's password
     * @param googleToken the Google authentication token (currently unused)
     * @return a map containing authentication results
     */
    public Map<String, Object> authenticateUser(String email, String password, String googleToken) {
        Map<String, Object> result = new HashMap<>();

        // Only email/password authentication is implemented for now
        if (isNonEmpty(email) && isNonEmpty(password)) {
            result.put("success", true);
            result.put("userEmail", email);
            result.put("authMethod", "email");
        } else {
            result.put("success", false);
            result.put("message", "Invalid email or password");
        }

        return result;
    }

    /**
     * Utility method to check if a string is non-null and not empty after trimming.
     *
     * @param s the string to check
     * @return true if s is non-null and contains non-whitespace characters
     */
    private boolean isNonEmpty(String s) {
        return s != null && !s.trim().isEmpty();
    }

    // Example usage
    public static void main(String[] args) {
        AuthenticationService authService = new AuthenticationService();

        Map<String, Object> successResult = authService.authenticateUser("user@example.com", "password123", null);
        System.out.println(successResult);

        Map<String, Object> failureResult = authService.authenticateUser("", "password123", null);
        System.out.println(failureResult);
