import java.util.HashMap;
import java.util.Map;

public class AuthenticationService {

    /**
     * Authenticates a user using either email/password or a Google token.
     *
     * @param email       the user's email address (may be null)
     * @param password    the user's password (may be null)
     * @param googleToken the Google authentication token (may be null)
     * @return a map containing authentication results
     */
    public Map<String, Object> authenticateUser(String email, String password, String googleToken) {
        Map<String, Object> result = new HashMap<>();

        // 1. No credentials provided
        if (email == null && password == null && googleToken == null) {
            result.put("success", false);
            result.put("message", "Authentication failed: No credentials provided");
            return result;
        }

        // 2. Email/Password authentication (preferred if both are non‑null)
        if (email != null && password != null) {
            if (isNonEmpty(email) && isNonEmpty(password) && email.contains("@") && password.length() >= 6) {
                result.put("success", true);
                result.put("userEmail", email);
                result.put("authMethod", "email");
            } else {
                result.put("success", false);
                result.put("message", "Invalid email or password");
            }
            return result;
        }

        // 3. Google token authentication (only if email & password are null)
        if (googleToken != null && googleToken.startsWith("google_")) {
            String localPart = googleToken.substring("google_".length());
            result.put("success", true);
            result.put("userEmail", localPart + "@gmail.com");
            result.put("authMethod", "google");
        } else {
            result.put("success", false);
            result.put("message", "Google authentication failed");
        }

        return result;
    }

    /**
     * Utility method to check if a string is non‑null and not empty after trimming.
     *
     * @param s the string to check
     * @return true if s is non‑null and contains non‑whitespace characters
     */
    private boolean isNonEmpty(String s) {
        return s != null && !s.trim().isEmpty();
    }

    // Example usage
    public static void main(String[] args) {
        AuthenticationService authService = new AuthenticationService();

        // Successful email/password authentication
        Map<String, Object> emailSuccess = authService.authenticateUser(
                "user@example.com", "securePass", null);
        System.out.println(emailSuccess); // {success=true, userEmail=user@example.com, authMethod=email}

        // Successful Google token authentication
        Map<String, Object> googleSuccess = authService.authenticateUser(
                null, null, "google_johndoe");
        System.out.println(googleSuccess); // {success=true, userEmail=johndoe@gmail.com, authMethod=google}

        // Prefer email/password over Google token
        Map<String, Object> preferEmail = authService.authenticateUser(
                "user@example.com", "securePass", "google_invalid");
        System.out.println(preferEmail); // {success=true, userEmail=user@example.com, authMethod=email}

        // Invalid email/password
        Map<String, Object> invalidEmail = authService.authenticateUser(
                "invalidemail", "short", null);
        System.out.println(invalidEmail); // {success=false, message=Invalid email or password}

        // Invalid Google token
        Map<String, Object> invalidGoogle = authService.authenticateUser(
                null, null, "invalidtoken");
        System.out.println(invalidGoogle); // {success=false, message=Google authentication failed}

        // No credentials provided
        Map<String, Object> noCreds = authService.authenticateUser(
                null, null, null);
        System.out.println(noCreds); // {success=false, message=Authentication failed: No credentials provided}
    }
}

