import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

class ThreadSynchronizer {
    private final ReentrantLock lock;
    private final Condition condition;
    private boolean isSignalled;

    public ThreadSynchronizer() {
        this.lock = new ReentrantLock();
        this.condition = lock.newCondition();
        this.isSignalled = false;
    }

    /**
     * Waits for up to {@code waitSeconds} seconds for a signal.
     * Returns {@code true} if a signal was received before the timeout,
     * otherwise returns {@code false}.
     *
     * @param waitSeconds maximum number of seconds to wait
     * @return {@code true} if signalled, {@code false} if timed out
     */
    public boolean waitWithDeadline(int waitSeconds) {
        lock.lock();
        try {
            // If already signalled, consume the signal and return immediately
            if (isSignalled) {
                isSignalled = false;
                return true;
            }

            // Wait until signalled or timeout
            while (!isSignalled) {
                boolean timedOut = !condition.await(waitSeconds, TimeUnit.SECONDS);
                if (timedOut) {
                    return false; // timeout occurred
                }
            }

            // Signal received
            isSignalled = false;
            return true;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Preserve interrupt status
            return false;
        } finally {
            lock.unlock();
        }
    }

    /**
     * Signals all waiting threads.
     */
    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
}

