import java.util.concurrent.locks.ReentrantLock;

class ThreadSynchronizer {
    private final ReentrantLock lock;
    private final Condition condition;
    private boolean isSignalled;

    public ThreadSynchronizer() {
        this.lock = new ReentrantLock();
        this.condition = lock.newCondition();
        this.isSignalled = false;
    }

    /**
     * Waits for up to {@code waitSeconds} seconds for a signal.
     * Returns {@code true} if a signal was received before the timeout,
     * otherwise returns {@code false}. The method respects spurious
     * wake‑ups by checking {@code isSignalled} in a loop and uses
     * {@link Condition#awaitUntil(Date)} for accurate timeout handling.
     *
     * @param waitSeconds maximum number of seconds to wait
     * @return {@code true} if signalled, {@code false} if timed out or interrupted
     */
    public boolean waitWithDeadline(int waitSeconds) {
        // Compute an absolute deadline once
        final Date deadline = new Date(System.currentTimeMillis() + waitSeconds * 1000L);

        lock.lock();
        try {
            // If already signalled, consume the signal immediately
            if (isSignalled) {
                return true;
            }

            // Wait until signalled or timeout
            while (!isSignalled) {
                boolean signalled = condition.awaitUntil(deadline);
                if (!signalled) { // timeout reached
                    return false;
                }
                // If signalled is true but isSignalled is still false,
                // loop again to handle spurious wake‑ups.
            }
            return true; // signalled
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // restore interrupt status
            return false;
        } finally {
            // Reset the flag regardless of the outcome
            isSignalled = false;
            lock.unlock();
        }
    }

    /**
     * Signals all waiting threads. The {@code isSignalled} flag is set to
     * {@code true} before notifying to ensure that waiting threads can
     * consume the signal.
     */
    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
}

