import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Generic pagination service that supports optional case‑insensitive filtering.
 *
 * @param <T> the type of items to paginate
 */
public class PaginationService<T> {

    /**
     * Returns a paginated result for the given list of items.
     *
     * @param items      the original list of items
     * @param page       the 1‑based page number
     * @param rowsPerPage the number of items per page
     * @param key        optional filter key (case‑insensitive); if null or empty, no filtering is applied
     * @return a PaginatedResult containing the sliced items and the total count after filtering
     */
    public PaginatedResult<T> paginate(List<T> items, int page, int rowsPerPage, String key) {
        if (items == null) {
            items = Collections.emptyList();
        }

        List<T> filtered = items;
        if (key != null && !key.isEmpty()) {
            filtered = filterItems(items, key);
        }

        int total = filtered.size();
        int startIndex = Math.max(0, (page - 1) * rowsPerPage);
        if (startIndex >= total) {
            return new PaginatedResult<>(Collections.emptyList(), total);
        }

        int endIndex = Math.min(startIndex + rowsPerPage, total);
        List<T> pageItems = new ArrayList<>(filtered.subList(startIndex, endIndex));

        return new PaginatedResult<>(pageItems, total);
    }

    /**
     * Filters the given list of items by checking if the string representation of each item
     * contains the specified key (case‑insensitive).
     *
     * @param items the list of items to filter
     * @param key   the filter key
     * @return a new list containing only items that match the filter
     */
    private List<T> filterItems(List<T> items, String key) {
        List<T> result = new ArrayList<>();
        String lowerKey = key.toLowerCase();
        for (T item : items) {
            if (item != null && item.toString().toLowerCase().contains(lowerKey)) {
                result.add(item);
            }
        }
        return result;
    }

    /**
     * Encapsulates the result of a pagination operation.
     *
     * @param <T> the type of items in the result
     */
    public static class PaginatedResult<T> {
        private final List<T> items;
        private final int total;

        public PaginatedResult(List<T> items, int total) {
            this.items = items;
            this.total = total;
        }

        /**
         * @return the list of items on the current page
         */
        public List<T> getItems() {
            return items;
        }

        /**
         * @return the total number of items after filtering (before pagination)
         */
        public int getTotal() {
            return total;
        }
    }
}

