 *
 * @param <T> the type of items to paginate
 */
public class PaginationService<T> {

    /**
     * Returns a paginated result for the given list of items.
     *
     * @param items       the original list of items
     * @param page        the 1‑based page number
     * @param rowsPerPage the number of items per page
     * @param key         optional filter key (case‑insensitive); if null or empty, no filtering is applied
     * @param sortBy      optional sort specification. Format: "field" or "field:asc"/"field:desc".
     *                    If the field does not exist or is inaccessible, the list remains unsorted.
     * @return a PaginatedResult containing the sliced items and the total count after filtering
     */
    public PaginatedResult<T> paginate(List<T> items, int page, int rowsPerPage, String key, String sortBy) {
        if (items == null) {
            items = Collections.emptyList();
        }

        // Defensive copy to avoid modifying the original list
        List<T> processed = new ArrayList<>(items);

        // Filtering
        if (key != null && !key.isEmpty()) {
            processed = filterItems(processed, key);
        }

        // Sorting
        if (sortBy != null && !sortBy.isEmpty()) {
            processed = sortItems(processed, sortBy);
        }

        int total = processed.size();
        int startIndex = Math.max(0, (page - 1) * rowsPerPage);
        if (startIndex >= total) {
            return new PaginatedResult<>(Collections.emptyList(), total);
        }

        int endIndex = Math.min(startIndex + rowsPerPage, total);
        List<T> pageItems = new ArrayList<>(processed.subList(startIndex, endIndex));

        return new PaginatedResult<>(pageItems, total);
    }

    /**
     * Filters the given list of items by checking if the string representation of each item
     * contains the specified key (case‑insensitive).
     *
     * @param items the list of items to filter
     * @param key   the filter key
     * @return a new list containing only items that match the filter
     */
    private List<T> filterItems(List<T> items, String key) {
        List<T> result = new ArrayList<>();
        String lowerKey = key.toLowerCase();
        for (T item : items) {
            if (item != null && item.toString().toLowerCase().contains(lowerKey)) {
                result.add(item);
            }
        }
        return result;
    }

    /**
     * Sorts the given list of items by the field specified in sortBy.
     * The sortBy string may contain a field name optionally followed by ":asc" or ":desc".
     * If the field does not exist or is inaccessible, the original list is returned unchanged.
     *
     * @param items  the list of items to sort
     * @param sortBy the sort specification
     * @return a new list sorted according to the specification
     */
    private List<T> sortItems(List<T> items, String sortBy) {
        if (items.isEmpty()) {
            return items;
        }

        String fieldName = sortBy;
        boolean ascending = true;

        if (sortBy.contains(":")) {
            String[] parts = sortBy.split(":", 2);
            fieldName = parts[0].trim();
            String dir = parts[1].trim().toLowerCase();
            ascending = !dir.equals("desc");
        }

        try {
            Field field = null;
            Class<?> clazz = items.get(0).getClass();

            // Search for the field in the class hierarchy
            while (clazz != null) {
                try {
                    field = clazz.getDeclaredField(fieldName);
                    field.setAccessible(true);
                    break;
                } catch (NoSuchFieldException e) {
                    clazz = clazz.getSuperclass();
                }
            }

            if (field == null) {
                return items; // field not found
            }

            Comparator<T> comparator = (o1, o2) -> {
                try {
                    Object v1 = field.get(o1);
                    Object v2 = field.get(o2);

                    if (v1 == v2) return 0;
                    if (v1 == null) return -1;
                    if (v2 == null) return 1;

                    if (v1 instanceof Comparable && v2 instanceof Comparable) {
                        @SuppressWarnings("unchecked")
                        Comparable<Object> c1 = (Comparable<Object>) v1;
                        return c1.compareTo(v2);
                    }
                    return 0;
                } catch (IllegalAccessException e) {
                    return 0;
                }
            };

            if (!ascending) {
                comparator = comparator.reversed();
            }

            List<T> sorted = new ArrayList<>(items);
            sorted.sort(comparator);
            return sorted;

        } catch (Exception e) {
            // Any unexpected exception results in returning the unsorted list
            return items;
        }
    }

    /**
     * Encapsulates the result of a pagination operation.
     *
     * @param <T> the type of items in the result
     */
    public static class PaginatedResult<T> {
        private final List<T> items;
        private final int total;

        public PaginatedResult(List<T> items, int total) {
            this.items = items;
            this.total = total;
        }

        /**
         * @return the list of items on the current page
         */
        public List<T> getItems() {
