import java.util.ArrayList;
import java.util.List;

public class CelestialSimulator {

    // Gravitational constant (arbitrary units)
    private static final double G = 1.0;

    /**
     * 2D vector class.
     */
    public static class Vector {
        public double x;
        public double y;

        public Vector(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public Vector add(Vector v) {
            return new Vector(this.x + v.x, this.y + v.y);
        }

        public Vector subtract(Vector v) {
            return new Vector(this.x - v.x, this.y - v.y);
        }

        public Vector multiply(double scalar) {
            return new Vector(this.x * scalar, this.y * scalar);
        }

        public double magnitude() {
            return Math.sqrt(x * x + y * y);
        }

        public Vector normalize() {
            double mag = magnitude();
            if (mag == 0) {
                return new Vector(0, 0);
            }
            return new Vector(x / mag, y / mag);
        }
    }

    /**
     * Celestial body class.
     */
    public static class Celestial {
        public String name;
        public double mass;
        public Vector position;
        public Vector velocity;
        public Vector acceleration;

        public Celestial(String name, double mass, Vector position, Vector velocity, Vector acceleration) {
            this.name = name;
            this.mass = mass;
            this.position = position;
            this.velocity = velocity;
            this.acceleration = acceleration;
        }

        // Copy constructor
        public Celestial(Celestial other) {
            this.name = other.name;
            this.mass = other.mass;
            this.position = new Vector(other.position.x, other.position.y);
            this.velocity = new Vector(other.velocity.x, other.velocity.y);
            this.acceleration = new Vector(other.acceleration.x, other.acceleration.y);
        }
    }

    /**
     * Simulate the motion of celestial bodies.
     *
     * @param bodies List of celestial bodies (will be updated in place)
     * @param dt     Time step
     * @param steps  Number of simulation steps
     * @return History of the simulation: a list of snapshots, each snapshot is a list of Celestial objects
     */
    public static List<List<Celestial>> simulate(List<Celestial> bodies, double dt, int steps) {
        List<List<Celestial>> history = new ArrayList<>();

        for (int step = 0; step < steps; step++) {
            // Compute accelerations
            for (Celestial body : bodies) {
                Vector totalAcc = new Vector(0, 0);
                for (Celestial other : bodies) {
                    if (body == other) continue;
                    Vector r = other.position.subtract(body.position);
                    double dist = r.magnitude();
                    if (dist == 0) continue; // avoid division by zero
                    double forceMag = G * body.mass * other.mass / (dist * dist);
                    Vector acc = r.normalize().multiply(forceMag / body.mass);
                    totalAcc = totalAcc.add(acc);
                }
                body.acceleration = totalAcc;
            }

            // Update velocities and positions
            for (Celestial body : bodies) {
                body.velocity = body.velocity.add(body.acceleration.multiply(dt));
                body.position = body.position.add(body.velocity.multiply(dt));
            }

            // Record snapshot
            List<Celestial> snapshot = new ArrayList<>();
            for (Celestial body : bodies) {
                snapshot.add(new Celestial(body));
            }
            history.add(snapshot);
        }

        return history;
    }
}

