            history.add(copyState(bodies));
        }

        return history;
    }

    /**
     * Create a deep copy of the list of celestial bodies.
     *
     * @param bodies the original list of bodies
     * @return a new list containing copies of all bodies and their vectors
     */
    private static List<Celestial> copyState(List<Celestial> bodies) {
        List<Celestial> snapshot = new ArrayList<>();
        for (Celestial b : bodies) {
            Celestial copy = new Celestial(
                    b.name,
                    b.mass,
                    new Vector(b.position.x, b.position.y),
                    new Vector(b.velocity.x, b.velocity.y),
                    new Vector(b.acceleration.x, b.acceleration.y)
            );
            snapshot.add(copy);
        }
        return snapshot;
    }

    /**
     * Create a simple solar system with the Sun, Earth, and Mars.
     *
     * @return a list of celestial bodies representing the solar system
     */
    public static List<Celestial> createSolarSystem() {
        List<Celestial> system = new ArrayList<>();

        // Constants
        double AU = 1.496e11; // meters
        double sunMass = 1.9885e30;   // kg
        double earthMass = 5.972e24;  // kg
        double marsMass = 6.417e23;   // kg

        // Sun at origin, stationary
        Celestial sun = new Celestial(
                "Sun",
                sunMass,
                new Vector(0, 0),
                new Vector(0, 0),
                new Vector(0, 0)
        );

        // Earth at 1 AU, velocity for circular orbit
        double earthDistance = AU;
        double earthSpeed = Math.sqrt(G * sunMass / earthDistance);
        Celestial earth = new Celestial(
                "Earth",
                earthMass,
                new Vector(earthDistance, 0),
                new Vector(0, earthSpeed),
                new Vector(0, 0)
        );

        // Mars at 1.524 AU, velocity for circular orbit
        double marsDistance = 1.524 * AU;
        double marsSpeed = Math.sqrt(G * sunMass / marsDistance);
        Celestial mars = new Celestial(
                "Mars",
                marsMass,
                new Vector(marsDistance, 0),
                new Vector(0, marsSpeed),
                new Vector(0, 0)
        );

        system.add(sun);
        system.add(earth);
        system.add(mars);

        return system;
    }
}
