public class Venue {
    private final int rows;
    private final int columns;
    private final boolean[][] seats; // true = reserved, false = available

    /**
     * Creates a venue with the specified number of rows and columns.
     * All seats are initially available.
     *
     * @param rows    number of rows (must be > 0)
     * @param columns number of columns (must be > 0)
     * @throws IllegalArgumentException if rows or columns are not positive
     */
    public Venue(int rows, int columns) {
        if (rows <= 0 || columns <= 0) {
            throw new IllegalArgumentException("Rows and columns must be positive integers.");
        }
        this.rows = rows;
        this.columns = columns;
        this.seats = new boolean[rows][columns]; // all false by default
    }

    /**
     * Returns the total number of seats in the venue.
     *
     * @return rows × columns
     */
    public int getNumberOfSeats() {
        return rows * columns;
    }

    /**
     * Checks if a specific seat is available.
     *
     * @param row    1‑based row number
     * @param column 1‑based column number
     * @return true if the seat is available, false if reserved
     * @throws IndexOutOfBoundsException if the seat position is invalid
     */
    public boolean isSeatAvailable(int row, int column) {
        validateSeatPosition(row, column);
        return !seats[row - 1][column - 1];
    }

    /**
     * Reserves a specific seat if it is available.
     *
     * @param row    1‑based row number
     * @param column 1‑based column number
     * @return true if the reservation succeeded, false if the seat was already reserved
     * @throws IndexOutOfBoundsException if the seat position is invalid
     */
    public boolean reserveSeat(int row, int column) {
        validateSeatPosition(row, column);
        if (seats[row - 1][column - 1]) {
            return false; // already reserved
        }
        seats[row - 1][column - 1] = true;
        return true;
    }

    /**
     * Cancels a reservation for a specific seat.
     *
     * @param row    1‑based row number
     * @param column 1‑based column number
     * @throws IndexOutOfBoundsException if the seat position is invalid
     */
    public void cancelReservation(int row, int column) {
        validateSeatPosition(row, column);
        seats[row - 1][column - 1] = false;
    }

    /**
     * Validates that the given seat coordinates are within bounds.
     *
     * @param row    1‑based row number
     * @param column 1‑based column number
     * @throws IndexOutOfBoundsException if the seat position is invalid
     */
    private void validateSeatPosition(int row, int column) {
        if (row < 1 || row > rows || column < 1 || column > columns) {
            throw new IndexOutOfBoundsException(
                "Seat position out of bounds: row=" + row + ", column=" + column);
        }
    }
}

