import java.util.*;
import java.util.concurrent.atomic.AtomicLong;

public class CategoryManager {
    private final Map<String, List<Note>> categories = new HashMap<>();

    public CategoryManager() {
        // Initialize default category named "生活"
        categories.put("生活", new ArrayList<>());
    }

    /**
     * Adds a new note to the specified category. If the category does not exist,
     * it will be created automatically.
     *
     * @param category the category name
     * @param title    the note title
     * @param content  the note content
     */
    public void addNote(String category, String title, String content) {
        categories.computeIfAbsent(category, k -> new ArrayList<>()).add(new Note(title, content));
    }

    /**
     * Retrieves all notes belonging to the specified category.
     *
     * @param category the category name
     * @return a list of notes; empty list if the category does not exist
     */
    public List<Note> getNotes(String category) {
        return categories.getOrDefault(category, Collections.emptyList());
    }

    /**
     * Nested Note class representing an individual note.
     */
    public static class Note {
        private static final AtomicLong ID_GENERATOR = new AtomicLong(0);

        private final long id;
        private final String title;
        private final String content;

        public Note(String title, String content) {
            this.id = ID_GENERATOR.incrementAndGet();
            this.title = title;
            this.content = content;
        }

        public long getId() {
            return id;
        }

        public String getTitle() {
            return title;
        }

        public String getContent() {
            return content;
        }
    }
}

