import java.util.Arrays;
import java.util.Comparator;

class EnhancedMergeSort {

    public Integer[] sortIntegers(Integer[] array) {
        if (array == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        // For 0 or 1 element, the array is already sorted
        if (array.length <= 1) {
            return array;
        }
        return mergeSort(array);
    }

    // Recursive merge sort implementation
    private Integer[] mergeSort(Integer[] array) {
        int n = array.length;
        if (n <= 1) {
            return array;
        }

        int mid = n / 2;
        Integer[] left = Arrays.copyOfRange(array, 0, mid);
        Integer[] right = Arrays.copyOfRange(array, mid, n);

        left = mergeSort(left);
        right = mergeSort(right);

        return merge(left, right);
    }

    // Merge two sorted arrays into one sorted array
    private Integer[] merge(Integer[] left, Integer[] right) {
        int i = 0, j = 0, k = 0;
        Integer[] result = new Integer[left.length + right.length];

        while (i < left.length && j < right.length) {
            if (left[i].compareTo(right[j]) <= 0) {
                result[k++] = left[i++];
            } else {
                result[k++] = right[j++];
            }
        }

        while (i < left.length) {
            result[k++] = left[i++];
        }

        while (j < right.length) {
            result[k++] = right[j++];
        }

        return result;
    }
}

