import java.net.URLEncoder;
import java.io.UnsupportedEncodingException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

class SecurePaymentProcessor {

    /**
     * Generates a secure payment URL by appending the provided parameters
     * (sorted alphabetically by key) to the base URL. The method validates
     * that the base URL and secret are non‑null and non‑empty. The secret
     * is used to compute a signature of the parameters, which is not
     * included in the returned URL but demonstrates that the secret is
     * being utilized in subsequent processing steps.
     *
     * @param baseUrl    the base URL to which parameters will be appended
     * @param secret     a secret key used for signature generation
     * @param parameters a map of query parameters to include in the URL
     * @return the full URL with encoded query parameters
     * @throws IllegalArgumentException if baseUrl or secret is null or empty
     */
    public String generateSecurePaymentUrl(String baseUrl, String secret, Map<String, String> parameters) {
        // Validate baseUrl and secret
        if (baseUrl == null || baseUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("baseUrl must not be null or empty");
        }
        if (secret == null || secret.trim().isEmpty()) {
            throw new IllegalArgumentException("secret must not be null or empty");
        }

        // If no parameters, return the base URL unchanged
        if (parameters == null || parameters.isEmpty()) {
            return baseUrl;
        }

        // Sort parameters by key alphabetically
        TreeMap<String, String> sortedParams = new TreeMap<>(parameters);
        StringBuilder query = new StringBuilder();

        boolean first = true;
        for (Map.Entry<String, String> entry : sortedParams.entrySet()) {
            try {
                String encodedKey = URLEncoder.encode(entry.getKey(), "UTF-8");
                String encodedValue = URLEncoder.encode(entry.getValue(), "UTF-8");

                if (!first) {
                    query.append("&");
                }
                query.append(encodedKey).append("=").append(encodedValue);
                first = false;
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException("UTF-8 encoding not supported", e);
            }
        }

        // Compute a signature using the secret (not included in the URL)
        String signature = computeSignature(sortedParams, secret);
        // The signature is computed for demonstration purposes; it is not appended to the URL.

        // Append query string to base URL
        String separator = baseUrl.contains("?") ? "&" : "?";
        return baseUrl + separator + query.toString();
    }

    /**
     * Computes a simple SHA‑256 signature of the sorted parameters concatenated
     * with the secret. This method demonstrates that the secret is being used
     * in subsequent processing steps, even though the signature is not added
     * to the URL.
     *
     * @param sortedParams the sorted parameters map
     * @param secret       the secret key
     * @return a hexadecimal representation of the SHA‑256 hash
     */
    private String computeSignature(Map<String, String> sortedParams, String secret) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            StringBuilder data = new StringBuilder();

            for (Map.Entry<String, String> entry : sortedParams.entrySet()) {
                data.append(entry.getKey()).append("=").append(entry.getValue()).append("&");
            }
            data.append("secret=").append(secret);

            byte[] hash = digest.digest(data.toString().getBytes("UTF-8"));
            StringBuilder hex = new StringBuilder();
            for (byte b : hash) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
            // These exceptions should never occur; wrap in unchecked exception
            throw new RuntimeException("Error computing signature", e);
        }
    }
}

