import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;

/**
 * A simple configuration manager that can register beans, load properties,
 * and retrieve both beans and property values.
 */
public class ConfigManager {

    /* ---------- Bean management ---------- */

    /** Stores beans by name. */
    private final Map<String, Object> beans = new ConcurrentHashMap<>();

    /**
     * Registers a bean under the given name. The bean is created by the supplied
     * {@link Supplier}. If a bean with the same name already exists, it will be
     * overwritten.
     *
     * @param name     the name under which the bean will be stored
     * @param supplier a supplier that provides the bean instance
     * @param <T>      the type of the bean
     */
    public <T> void registerBean(String name, Supplier<T> supplier) {
        beans.put(name, supplier.get());
    }

    /**
     * Retrieves a bean by its name.
     *
     * @param name the name of the bean to retrieve
     * @return the bean instance, or {@code null} if no bean with that name exists
     */
    public Object getBean(String name) {
        return beans.get(name);
    }

    /**
     * Retrieves a bean by its name and casts it to the requested type.
     *
     * @param name  the name of the bean to retrieve
     * @param clazz the expected class of the bean
     * @param <T>   the type of the bean
     * @return the bean instance cast to {@code T}, or {@code null} if no bean
     *         with that name exists
     * @throws ClassCastException if the bean cannot be cast to {@code T}
     */
    @SuppressWarnings("unchecked")
    public <T> T getBean(String name, Class<T> clazz) {
        Object bean = beans.get(name);
        if (bean == null) {
            return null;
        }
        return clazz.cast(bean);
    }

    /* ---------- Property management ---------- */

    /** List of configuration file paths that have been loaded. */
    private final List<String> configFiles = new ArrayList<>();

    /** Internal properties store. */
    private final Properties properties = new Properties();

    /**
     * Simulates loading a properties file. The file path is stored in the
     * {@link #configFiles} list. If the path contains the substring
     * {@code "config.properties"}, dummy properties are added:
     * <ul>
     *   <li>url = http://example.com</li>
     *   <li>timeout = 30</li>
     * </ul>
     *
     * @param path the path of the properties file to load
     */
    public void loadProperties(String path) {
        // Store the path
        configFiles.add(path);

        // Simulate loading properties for a specific file
        if (path.contains("config.properties")) {
            properties.setProperty("url", "http://example.com");
            properties.setProperty("timeout", "30");
        }
        // For other files, no properties are added in this simulation
    }

    /**
     * Retrieves the value of a property by its key.
     *
     * @param key the property key
     * @return the property value, or {@code null} if the key is not present
     */
    public String getProperty(String key) {
        return properties.getProperty(key);
    }

    /**
     * Returns an unmodifiable view of the loaded configuration file paths.
     *
     * @return list of configuration file paths
     */
    public List<String> getConfigFiles() {
        return Collections.unmodifiableList(configFiles);
    }
}

