        if (root == null) {
            return new ArrayList<>();
        }
        dfs(root);
        return bestPath;
    }

    /**
     * Depth‑first search that computes heights and paths, and updates the global best path.
     *
     * @param node current node being visited
     * @return Result containing height and path from this node to its deepest leaf
