        downPath.add(node);
        if (!path1.isEmpty()) {
            downPath.addAll(path1);
        }
        int currentHeight = 1 + maxHeight1; // height of subtree rooted at this node

        // Candidate path that passes through this node (using two deepest children)
        if (!path1.isEmpty() && !path2.isEmpty()) {
