     * @param root the root node of the tree
     * @return a list of nodes representing the longest path; empty if root is null
     */
    public List<Node> findLongestPath(Node root) {
        bestPath.clear();          // reset for each call
        if (root == null) {
            return new ArrayList<>();   // handle null input
        }
        dfs(root);                 // start DFS
        return bestPath;           // best path found during traversal
    }

    /**
     * Depth‑first search that computes heights and paths, and updates the global best path.
     *
     * @param node current node being visited
     * @return Result containing height and path from this node to its deepest leaf
     */
    private Result dfs(Node node) {
        // Track the two deepest child paths
        int maxHeight1 = 0, maxHeight2 = 0;
        List<Node> path1 = new ArrayList<>();
        List<Node> path2 = new ArrayList<>();

        for (Node child : node.children) {
            Result childRes = dfs(child);
            if (childRes.height > maxHeight1) {
                // shift current max to second
                maxHeight2 = maxHeight1;
                path2 = path1;

                // update max
                maxHeight1 = childRes.height;
                path1 = childRes.path;
            } else if (childRes.height > maxHeight2) {
                maxHeight2 = childRes.height;
                path2 = childRes.path;
            }
        }

        // Path from this node down to deepest leaf
        List<Node> downPath = new ArrayList<>();
        downPath.add(node);
        if (!path1.isEmpty()) {
            downPath.addAll(path1);
        }
        int currentHeight = 1 + maxHeight1; // height of subtree rooted at this node

        // Candidate path that passes through this node (using two deepest children)
        if (!path1.isEmpty() && !path2.isEmpty()) {
            List<Node> throughPath = new ArrayList<>();
            throughPath.addAll(path1);
            throughPath.add(node);
            throughPath.addAll(path2);
            if (throughPath.size() > bestPath.size()) {
                bestPath = throughPath;
            }
        }

        // Also consider the path that goes only downwards from this node
        if (downPath.size() > bestPath.size()) {
            bestPath = downPath;
        }

        return new Result(currentHeight, downPath);
    }

