import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Objects;

class PollingQueue<T> {
    private final Queue<T> queue;
    private final AtomicInteger pollingCount;
    private final int maxPollingAttempts;

    public PollingQueue(int maxPollingAttempts) {
        this.queue = new LinkedList<>();
        this.pollingCount = new AtomicInteger(0);
        this.maxPollingAttempts = maxPollingAttempts;
    }

    /** Adds an element to the queue and notifies waiting threads. */
    public synchronized void enqueue(T element) {
        queue.add(element);
        notifyAll();                     // wake up threads waiting for an element
    }

    /** Polls an element, enforcing the maximum polling attempts. */
    public synchronized T poll() {
        int attempts = pollingCount.incrementAndGet();
        if (attempts > maxPollingAttempts) {
            throw new IllegalStateException(
                "Exceeded maximum polling attempts: " + maxPollingAttempts);
        }
        return queue.poll(); // may return null if the queue is empty
    }

    /**
     * Waits up to {@code timeoutMillis} for an element to become available.
     * Returns the element if it appears within the timeout, otherwise returns {@code null}.
     */
    public synchronized T waitForElement(long timeoutMillis) {
        if (timeoutMillis <= 0) {
            return queue.poll(); // immediate return
        }

        long deadline = System.currentTimeMillis() + timeoutMillis;
        while (queue.isEmpty()) {
            long remaining = deadline - System.currentTimeMillis();
            if (remaining <= 0) {
                return null; // timeout elapsed
            }
            try {
                wait(remaining);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); // restore interrupt status
                return null;
            }
        }
        return queue.poll(); // element is available
    }

    /** Returns the current number of polling attempts. */
    public int getPollingCount() {
        return pollingCount.get();
    }

    /** Resets the polling attempt counter to zero. */
    public void resetPollingCount() {
        pollingCount.set(0);
    }

    public int getMaxPollingAttempts() {
        return maxPollingAttempts;
    }

    /** Two PollingQueue instances are equal if their queue contents,
     *  maxPollingAttempts, and current polling count are equal. */
    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof PollingQueue<?>)) return false;
        PollingQueue<?> other = (PollingQueue<?>) obj;
        return this.maxPollingAttempts == other.maxPollingAttempts &&
               this.pollingCount.get() == other.pollingCount.get() &&
               Objects.equals(this.queue, other.queue);
    }

    /** Hash code based on queue contents, maxPollingAttempts, and polling count. */
    @Override
    public int hashCode() {
        return Objects.hash(queue, maxPollingAttempts, pollingCount.get());
    }
}

public class Main {
    public static void main(String[] args) {
        // Create two identical queues
        PollingQueue<String> q1 = new PollingQueue<>(5);
        PollingQueue<String> q2 = new PollingQueue<>(5);

        q1.enqueue("alpha");
        q1.enqueue("beta");

        q2.enqueue("alpha");
        q2.enqueue("beta");

        System.out.println("q1 equals q2? " + q1.equals(q2));          // true
