        q1.enqueue("beta");

        q2.enqueue("alpha");
        q2.enqueue("beta");

        System.out.println("q1 equals q2? " + q1.equals(q2));          // true
        System.out.println("q1 hashCode == q2 hashCode? " +
                           (q1.hashCode() == q2.hashCode()));          // true

        // Poll from q1 to change its state
        q1.poll(); // pollingCount becomes 1

        System.out.println("\nAfter polling q1 once:");
        System.out.println("q1 equals q2? " + q1.equals(q2));          // false
        System.out.println("q1 hashCode == q2 hashCode? " +
                           (q1.hashCode() == q2.hashCode()));          // false

        // Reset q1's polling count
        q1.resetPollingCount();

        System.out.println("\nAfter resetting q1's polling count:");
        System.out.println("q1 equals q2? " + q1.equals(q2));          // true
        System.out.println("q1 hashCode == q2 hashCode? " +
                           (q1.hashCode() == q2.hashCode()));          // true

        // Demonstrate waitForElement
        new Thread(() -> {
            try {
                Thread.sleep(300); // simulate delay
                q1.enqueue("gamma");
                System.out.println("\nProducer: enqueued 'gamma'");
            } catch (InterruptedException ignored) {}
        }).start();

        System.out.println("\nConsumer: waiting for element (timeout 1000 ms)");
        String element = q1.waitForElement(1000);
