        CompletableFuture<T> taskFuture = CompletableFuture.supplyAsync(taskSupplier);

        // Create a future that completes with the fallback value after the timeout
        CompletableFuture<T> timeoutFuture = CompletableFuture.supplyAsync(
                () -> fallbackValue,
                CompletableFuture.delayedExecutor(timeout, timeUnit)
        );

        // Return a future that completes with whichever of the two futures finishes first
        return taskFuture.applyToEither(timeoutFuture, Function.identity());
    }
}

