import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.CompletionException;
import java.util.function.Supplier;
import java.util.function.Function;

class AsyncOperationManager {

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {
        return attemptWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, maxRetries);
    }

    private <T> CompletableFuture<T> attemptWithRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int remainingRetries) {

        CompletableFuture<Attempt<T>> attemptFuture = attempt(taskSupplier, timeout, timeUnit, fallbackValue);

        return attemptFuture.thenCompose(attempt -> {
            if (attempt.success) {
                // Successful execution
                return CompletableFuture.completedFuture(attempt.value);
            } else if (attempt.timedOut) {
                // Timeout occurred
                if (remainingRetries <= 0) {
                    // All attempts exhausted – return fallback
                    return CompletableFuture.completedFuture(fallbackValue);
                } else {
                    // Retry after delay
                    return delayThenRetry(taskSupplier, timeout, timeUnit, fallbackValue, remainingRetries - 1);
                }
            } else {
                // Exception occurred
                if (remainingRetries <= 0) {
                    // All attempts exhausted – propagate last exception
                    CompletableFuture<T> failed = new CompletableFuture<>();
                    failed.completeExceptionally(attempt.exception);
                    return failed;
                } else {
                    // Retry after delay
                    return delayThenRetry(taskSupplier, timeout, timeUnit, fallbackValue, remainingRetries - 1);
                }
            }
        });
    }

    private <T> CompletableFuture<T> delayThenRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int remainingRetries) {

        CompletableFuture<Void> delayFuture = CompletableFuture.runAsync(() -> {
            try {
                Thread.sleep(500);
            } catch (InterruptedException e) {
                throw new CompletionException(e);
            }
        });

        return delayFuture.thenCompose(v ->
                attemptWithRetry(taskSupplier, timeout, timeUnit, fallbackValue, remainingRetries));
    }

    private <T> CompletableFuture<Attempt<T>> attempt(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue) {

        CompletableFuture<T> taskFuture = CompletableFuture.supplyAsync(taskSupplier);

        CompletableFuture<T> timeoutFuture = CompletableFuture.supplyAsync(() -> {
            throw new TimeoutException();
        }, CompletableFuture.delayedExecutor(timeout, timeUnit));

        CompletableFuture<T> resultFuture = taskFuture.applyToEither(timeoutFuture, Function.identity());

        return resultFuture.handle((res, ex) -> {
            if (ex == null) {
                return new Attempt<>(true, res, null, false);
            } else {
                Throwable cause = ex instanceof CompletionException ? ex.getCause() : ex;
                if (cause instanceof TimeoutException) {
                    return new Attempt<>(false, null, null, true);
                } else {
                    return new Attempt<>(false, null, cause, false);
                }
            }
        });
    }

    private static class Attempt<T> {
        final boolean success;
        final T value;
        final Throwable exception;
        final boolean timedOut;

        Attempt(boolean success, T value, Throwable exception, boolean timedOut) {
            this.success = success;
            this.value = value;
            this.exception = exception;
            this.timedOut = timedOut;
        }
    }
}

