import java.util.HashMap;
import java.util.Map;

/**
 * A simplified simulator for a web fragment that demonstrates URL manipulation,
 * fragment visibility handling, network checks, and intent‑extra management.
 */
class WebFragmentSimulator {
    private String currentUrl;
    private boolean isFragmentVisible;
    private Map<String, String> intentExtras;
    private boolean networkAvailable;

    public WebFragmentSimulator() {
        // Initialize fields with default values
        this.currentUrl = null;
        this.isFragmentVisible = false;
        this.intentExtras = new HashMap<>();
        this.networkAvailable = false;
    }

    /**
     * Appends the required parameters to the given URL.
     *
     * @param url The original URL.
     * @return The URL with "app_version=1.0&os=android" appended.
     */
    public String appendUrlParameters(String url) {
        if (url == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder(url);
        if (url.contains("?")) {
            sb.append("&");
        } else {
            sb.append("?");
        }
        sb.append("app_version=1.0&os=android");
        return sb.toString();
    }

    /**
     * Loads web content for the given URL while performing visibility,
     * network, and URL validity checks. If the URL contains the substring
     * "ziroomupin", a modified URL with appended parameters is added to
     * the result map.
     *
     * @param url                The URL to load.
     * @param isFragmentVisible  Visibility flag for the fragment.
     * @param networkAvailable   Network availability flag.
     * @return A map containing the status of the load operation and
     *         relevant data (url, modifiedUrl, message).
     */
    public Map<String, Object> loadWebContent(String url, boolean isFragmentVisible, boolean networkAvailable) {
        // Update internal state
        this.currentUrl = url;
        this.isFragmentVisible = isFragmentVisible;
        this.networkAvailable = networkAvailable;

        Map<String, Object> result = new HashMap<>();

        // 1. Check fragment visibility
        if (!isFragmentVisible) {
            result.put("status", "pending");
            result.put("message", "Fragment not visible - loading deferred");
            return result;
        }

        // 2. Check network availability
