import java.util.ArrayList;
import java.util.List;

class TicTacToeGame {
    private final char[][] board;
    private char currentPlayer;
    private boolean gameOver;
    private char winner; // '-' means no winner yet

    public TicTacToeGame(int size) {
        this.board = new char[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                board[i][j] = '-';
            }
        }
        this.currentPlayer = 'X';
        this.gameOver = false;
        this.winner = '-';
    }

    /**
     * Attempts to place the current player's mark at the specified position.
     *
     * @param row the row index (0‑based)
     * @param col the column index (0‑based)
     * @return true if the move was successful; false if the move is out of bounds,
     *         the cell is already occupied, or the game is over.
     */
    public boolean makeMove(int row, int col) {
        if (gameOver) {
            return false;
        }

        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length) {
            return false;
        }

        if (board[row][col] != '-') {
            return false;
        }

        // Place the mark
        board[row][col] = currentPlayer;

        // Check for win on the row and column of the move
        if (isRowComplete(row, currentPlayer) || isColumnComplete(col, currentPlayer)) {
            gameOver = true;
            winner = currentPlayer;
        }

        // Switch player only if the game is not over
        if (!gameOver) {
            currentPlayer = (currentPlayer == 'X') ? 'O' : 'X';
        }

        return true;
    }

    private boolean isRowComplete(int row, char player) {
        for (int col = 0; col < board[row].length; col++) {
            if (board[row][col] != player) {
                return false;
            }
        }
        return true;
    }

    private boolean isColumnComplete(int col, char player) {
        for (int row = 0; row < board.length; row++) {
            if (board[row][col] != player) {
                return false;
            }
        }
        return true;
    }

    /**
     * Returns a snapshot of the current board state as a list of strings.
     * Each string represents a row of the board.
