import java.util.Map;
import java.util.HashMap;

class HttpRequestSimulator {
    public Map<String, Object> simulateHttpRequest(String url, String method,
                                                   Map<String, String> params,
                                                   Map<String, String> headers) {
        Map<String, Object> response = new HashMap<>();

        // Simulate a processing delay between 50 and 200 milliseconds
        long startTime = System.nanoTime();
        try {
            long delay = 50 + (long) (Math.random() * 150); // 50-200 ms
            Thread.sleep(delay);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        long endTime = System.nanoTime();
        long requestTimeMs = (endTime - startTime) / 1_000_000; // convert to ms

        // Build a sample body message
        StringBuilder bodyBuilder = new StringBuilder();
        bodyBuilder.append("Simulated response for ")
                   .append(method != null ? method : "GET")
                   .append(" request to ")
                   .append(url != null ? url : "unknown URL")
                   .append(".");
        if (params != null && !params.isEmpty()) {
            bodyBuilder.append(" Parameters: ").append(params.toString());
        }
        if (headers != null && !headers.isEmpty()) {
            bodyBuilder.append(" Headers: ").append(headers.toString());
        }

        // Populate the response map
        response.put("status", 200);
        response.put("body", bodyBuilder.toString());
        response.put("requestTime", requestTimeMs);

        return response;
    }
}

