class CargoOptimizer {

    /**
     * Calculates the maximum number of trips a cargo vehicle can make.
     *
     * <p>A trip can be made in two ways:</p>
     * <ul>
     *   <li><b>Single item</b>: its weight is less than or equal to the vehicle capacity.</li>
     *   <li><b>Group of items</b>: the heaviest item in the group multiplied by the group size
     *       is greater than or equal to the vehicle capacity.</li>
     * </ul>
     *
     * <p>After processing items that can travel alone, the remaining items are grouped
     * greedily to maximize the number of trips. The original {@code weights} list is
     * never modified.</p>
     *
     * @param weights   List of item weights. May be {@code null} or empty.
     * @param capacity  Vehicle capacity. If {@code capacity <= 0} the method returns 0.
     * @return The maximum number of trips, or 0 for invalid input.
     */
    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        // Handle null or empty input and non‑positive capacity
        if (weights == null || weights.isEmpty() || capacity <= 0) {
            return 0;
        }

        // Work on a copy to guarantee the original list is not modified
        ArrayList<Integer> copy = new ArrayList<>(weights);

        int aloneTrips = 0;
        ArrayList<Integer> remaining = new ArrayList<>();

        // Separate items that can travel alone
        for (int w : copy) {
            if (w <= capacity) {
                aloneTrips++;
            } else {
                remaining.add(w);
            }
        }

        // No remaining items – return alone trips
        if (remaining.isEmpty()) {
            return aloneTrips;
        }

        // Sort remaining items ascending to facilitate greedy grouping
        Collections.sort(remaining);

        int trips = 0;
        int idx = remaining.size() - 1; // start from the heaviest item

        while (idx >= 0) {
            int maxWeight = remaining.get(idx);
            // Minimum group size needed to satisfy maxWeight * size >= capacity
            int needed = (capacity + maxWeight - 1) / maxWeight; // ceil division

            // Check if enough items are left to form this group
            if (needed <= idx + 1) {
                trips++;
                idx -= needed; // remove the used items
            } else {
                // Not enough items left to form a valid group
                break;
            }
        }

        return aloneTrips + trips;
    }
}

