import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class EnhancedApiError {

    /* ---------- Severity ---------- */
    public enum ErrorSeverity {
        LOW,
        MEDIUM,
        HIGH,
        CRITICAL
    }

    /* ---------- Error Code ---------- */
    public enum ErrorCode {
        NON_KEY_ACCOUNT_BALANCE_ERROR(ErrorSeverity.HIGH, "Non-key account balance error"),
        INVALID_CREDENTIALS(ErrorSeverity.CRITICAL, "Invalid credentials"),
        SESSION_EXPIRED(ErrorSeverity.MEDIUM, "Session expired"),
        RATE_LIMIT_EXCEEDED(ErrorSeverity.MEDIUM, "Rate limit exceeded");

        private final ErrorSeverity severity;
        private final String defaultMessage;

        ErrorCode(ErrorSeverity severity, String defaultMessage) {
            this.severity = severity;
            this.defaultMessage = defaultMessage;
        }

        public ErrorSeverity getSeverity() {
            return severity;
        }

        public String getDefaultMessage() {
            return defaultMessage;
        }
    }

    /* ---------- Error Response ---------- */
    public static final class ErrorResponse {
        private final int statusCode;
        private final String rawResponse;

        public ErrorResponse(int statusCode, String rawResponse) {
            this.statusCode = statusCode;
            this.rawResponse = rawResponse;
        }

        public int getStatusCode() {
            return statusCode;
        }

        public String getRawResponse() {
            return rawResponse;
        }

        @Override
        public String toString() {
            return "ErrorResponse{statusCode=" + statusCode +
                   ", rawResponse='" + rawResponse + "'}";
        }
    }

    /* ---------- Error Message Resolver ---------- */
    public static class ErrorMessageResolver {
        public static String resolve(ErrorCode code) {
            return code.getDefaultMessage();
        }
    }

    /* ---------- EnhancedApiError fields ---------- */
    private final ErrorCode errorCode;
    private final ErrorResponse originalResponse;
    private final Map<String, Object> additionalDetails;

    /**
     * Constructs an EnhancedApiError.
     *
     * @param errorCode          the error code
     * @param originalResponse   the original HTTP response (may be null)
     * @param additionalDetails  a map of additional details (may be null)
     */
    public EnhancedApiError(ErrorCode errorCode,
                            ErrorResponse originalResponse,
                            Map<String, Object> additionalDetails) {
        this.errorCode = errorCode;
        this.originalResponse = originalResponse;
        if (additionalDetails != null) {
            // Defensive copy
            this.additionalDetails = new HashMap<>(additionalDetails);
        } else {
            this.additionalDetails = Collections.emptyMap();
        }
    }

    /* ---------- Getters ---------- */
    public ErrorCode getErrorCode() {
        return errorCode;
    }

    public ErrorResponse getOriginalResponse() {
        return originalResponse;
    }

    /**
     * Returns a defensive copy of the additional details map.
     *
     * @return a copy of the additional details map
     */
    public Map<String, Object> getAdditionalDetails() {
        return new HashMap<>(additionalDetails);
    }

    @Override
    public String toString() {
        return "EnhancedApiError{errorCode=" + errorCode +
               ", severity=" + errorCode.getSeverity() +
               ", message='" + errorCode.getDefaultMessage() + '\'' +
               ", originalResponse=" + originalResponse +
               ", additionalDetails=" + additionalDetails + '}';
    }
}

