import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

class UrlRouter {
    private Map<String, String> routeMap;
    private String defaultRoute;

    public UrlRouter(Map<String, String> routes, String defaultRoute) {
        this.routeMap = new HashMap<>(routes);
        this.defaultRoute = defaultRoute;
    }

    /**
     * Checks whether a route contains a parameter placeholder
     * in the form {paramName}.
     */
    private boolean isParameterizedRoute(String route) {
        return route.contains("{") && route.contains("}");
    }

    /**
     * Resolves the given path to a route.
     * Static routes are matched first.
     * If no static match is found, dynamic routes with
     * parameter placeholders are attempted.
     * If still no match, the default route is returned.
     */
    public String resolveRoute(String path) {
        // 1. Check for an exact static match
        if (routeMap.containsKey(path)) {
            return routeMap.get(path);
        }

        // 2. Attempt to match dynamic routes
        for (Map.Entry<String, String> entry : routeMap.entrySet()) {
            String route = entry.getKey();
            if (isParameterizedRoute(route)) {
                // Convert the route pattern to a regex
                // Replace each {param} with a capturing group that matches a path segment
                String regex = route.replaceAll("\\{[^}]+\\}", "([^/]+)");
                regex = "^" + regex + "$";
                Pattern pattern = Pattern.compile(regex);
                Matcher matcher = pattern.matcher(path);
                if (matcher.matches()) {
                    return entry.getValue();
                }
            }
        }

        // 3. No match found – return the default route
        return defaultRoute;
    }
}

