import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

class UrlRouter {
    private Map<String, String> routeMap;
    private String defaultRoute;

    public UrlRouter(Map<String, String> routes, String defaultRoute) {
        this.routeMap = new HashMap<>(routes);
        this.defaultRoute = defaultRoute;
    }

    /**
     * Checks whether a route contains a parameter placeholder
     * in the form {paramName}.
     */
    private boolean isParameterizedRoute(String route) {
        return route.contains("{") && route.contains("}");
    }

    /**
     * Determines if the given path matches the structure of a
     * parameterized route pattern. The number of path segments
     * must be identical, and non‑parameter segments must match
     * exactly. Parameter segments (enclosed in { }) can match
     * any value in the corresponding path segment.
     *
     * @param routePattern the route pattern, e.g. "/users/{id}"
     * @param path the actual request path, e.g. "/users/42"
     * @return true if the path matches the pattern, false otherwise
     */
    private boolean matchesParameterizedRoute(String routePattern, String path) {
        // Normalize by removing leading/trailing slashes
        String normalizedPattern = routePattern.replaceAll("^/+", "").replaceAll("/+$", "");
        String normalizedPath = path.replaceAll("^/+", "").replaceAll("/+$", "");

        String[] patternSegments = normalizedPattern.split("/");
        String[] pathSegments = normalizedPath.split("/");

        if (patternSegments.length != pathSegments.length) {
            return false;
        }

        for (int i = 0; i < patternSegments.length; i++) {
            String patternSeg = patternSegments[i];
            String pathSeg = pathSegments[i];

            if (patternSeg.startsWith("{") && patternSeg.endsWith("}")) {
                // Parameter segment: accept any value
                continue;
            }

            if (!patternSeg.equals(pathSeg)) {
                return false;
            }
        }

        return true;
    }

    /**
     * Resolves the given path to a route.
     * Static routes are matched first.
     * If no static match is found, dynamic routes with
     * parameter placeholders are attempted.
     * If still no match, the default route is returned.
     */
    public String resolveRoute(String path) {
        // 1. Check for an exact static match
        if (routeMap.containsKey(path)) {
            return routeMap.get(path);
