    public ConfigurationManager(Set<String> requiredKeys, Map<String, List<Validator>> validators) {
        this.configMap = new HashMap<>();
        this.requiredKeys = new HashSet<>(requiredKeys);
        this.validatorsMap = validators != null ? new HashMap<>(validators) : new HashMap<>();
    }

    /**
     * Loads configuration from the given properties map.
     *
     * @param properties the map of configuration properties
     * @throws ConfigurationException if any required key is missing or validation fails
     */
    public void loadConfiguration(Map<String, String> properties) {
        List<String> missing = new ArrayList<>();
        for (String key : requiredKeys) {
            if (!properties.containsKey(key)) {
                missing.add(key);
            }
        }
        if (!missing.isEmpty()) {
            throw new ConfigurationException("Missing required keys: " + String.join(", ", missing));
        }

        // Load all properties into the internal map
        for (Map.Entry<String, String> entry : properties.entrySet()) {
            configMap.put(entry.getKey(), entry.getValue());
        }

        // Validate the loaded configuration
        validateConfiguration();
    }

    /**
     * Validates the current configuration using the provided validators.
     *
     * @throws ConfigurationException if any validator fails
     */
    private void validateConfiguration() {
        for (Map.Entry<String, Object> entry : configMap.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();
            List<Validator> validators = validatorsMap.get(key);
            if (validators != null) {
                for (Validator validator : validators) {
                    if (!validator.validate(value)) {
                        throw new ConfigurationException(
                            "Validation failed for key '" + key + "': " + validator.getErrorMessage()
                        );
                    }
                }
            }
        }
    }

    /**
     * Retrieves the configuration value for the specified key, cast to the requested type.
     * Supports automatic conversion for Integer, Long, Double, Boolean, String, and TimeUnit.
     *
     * @param key  the configuration key
     * @param type the Class object of the desired type
     * @param <T>  the type to cast the value to
     * @return the configuration value cast to type T, or null if the key is not present
     * @throws ConfigurationException if type conversion fails
     */
    @SuppressWarnings("unchecked")
    public <T> T getConfigValue(String key, Class<T> type) {
        Object value = configMap.get(key);
        if (value == null) {
            return null;
        }

        // If the value is already of the requested type, return it directly
        if (type.isInstance(value)) {
            return (T) value;
        }

        try {
            if (type == Integer.class) {
                if (value instanceof Number) {
                    return (T) Integer.valueOf(((Number) value).intValue());
                } else if (value instanceof String) {
                    return (T) Integer.valueOf(Integer.parseInt((String) value));
                }
            } else if (type == Long.class) {
                if (value instanceof Number) {
                    return (T) Long.valueOf(((Number) value).longValue());
                } else if (value instanceof String) {
                    return (T) Long.valueOf(Long.parseLong((String) value));
                }
            } else if (type == Double.class) {
                if (value instanceof Number) {
                    return (T) Double.valueOf(((Number) value).doubleValue());
                } else if (value instanceof String) {
                    return (T) Double.valueOf(Double.parseDouble((String) value));
                }
            } else if (type == Boolean.class) {
                if (value instanceof Boolean) {
                    return (T) value;
                } else if (value instanceof String) {
                    String s = ((String) value).trim().toLowerCase();
                    if ("true".equals(s)) {
                        return (T) Boolean.TRUE;
                    } else if ("false".equals(s)) {
                        return (T) Boolean.FALSE;
                    } else {
                        throw new IllegalArgumentException("Invalid boolean value: " + value);
                    }
                }
            } else if (type == String.class) {
                return (T) value.toString();
            } else if (type == TimeUnit.class) {
                if (value instanceof TimeUnit) {
                    return (T) value;
                } else if (value instanceof String) {
                    return (T) TimeUnit.valueOf(((String) value).trim().toUpperCase());
                }
            }

            // Fallback: attempt direct cast
            return (T) value;
        } catch (Exception e) {
            throw new ConfigurationException(
                "Failed to convert key '" + key + "' to type " + type.getSimpleName() + ": " + e.getMessage()
            );
        }
    }

    /**
     * Sets a configuration key-value pair manually.
     *
     * @param key   the configuration key
     * @param value the configuration value
     */
    public void setConfig(String key, Object value) {
        configMap.put(key, value);
    }
}

