    /** Public entry point – uses unlimited recursion depth. */
    public static Map<String, Object> inspectObject(Object obj) {
        return inspectObject(obj, Integer.MAX_VALUE);
    }

    /** Core inspection logic with a maximum recursion depth. */
    public static Map<String, Object> inspectObject(Object obj, int maxDepth) {
        Map<String, Object> result = new HashMap<>();

        if (obj == null) {
            result.put("value", null);
            return result;
        }

        if (maxDepth <= 0) {
            result.put("type", obj.getClass().getSimpleName());
            result.put("value", obj);
            return result;
        }

        if (isSimpleType(obj)) {
            result.put("type", obj.getClass().getSimpleName());
            result.put("value", obj);
            return result;
        }

        Class<?> clazz = obj.getClass();

        /* Handle arrays */
        if (clazz.isArray()) {
            Class<?> componentType = clazz.getComponentType();
            result.put("type", componentType.getSimpleName() + "[]");
            int length = Array.getLength(obj);
            List<Object> list = new ArrayList<>(length);
            for (int i = 0; i < length; i++) {
                Object element = Array.get(obj, i);
                list.add(inspectObject(element, maxDepth - 1));
            }
            result.put("value", list);
            return result;
        }

        /* Handle complex objects */
        result.put("type", clazz.getSimpleName());
        result.put("value", obj);

        Map<String, Object> fieldsMap = new HashMap<>();
        for (Field field : getAllFields(clazz)) {
            field.setAccessible(true);
            try {
                Object fieldValue = field.get(obj);
                Map<String, Object> simpleMap = createSimpleFieldMap(fieldValue);
                if (simpleMap != null) {
                    fieldsMap.put(field.getName(), simpleMap);
                } else {
                    fieldsMap.put(field.getName(), inspectObject(fieldValue, maxDepth - 1));
                }
            } catch (IllegalAccessException e) {
                fieldsMap.put(field.getName(), "ACCESS_DENIED");
            }
        }
        result.put("fields", fieldsMap);
        return result;
    }

    /** Collects all declared non‑static fields from a class and its superclasses. */
    private static List<Field> getAllFields(Class<?> clazz) {
        List<Field> fields = new ArrayList<>();
        Class<?> current = clazz;
        while (current != null && current != Object.class) {
            for (Field f : current.getDeclaredFields()) {
                if (!Modifier.isStatic(f.getModifiers())) {
                    fields.add(f);
                }
            }
            current = current.getSuperclass();
        }
        return fields;
    }

    /** Creates a map with 'type' and 'value' for simple field values. */
    private static Map<String, Object> createSimpleFieldMap(Object value) {
        if (value == null) {
            Map<String, Object> map = new HashMap<>();
            map.put("value", null);
            return map;
        }
        if (value instanceof String || value instanceof Number ||
            value instanceof Boolean || value instanceof Character) {
            Map<String, Object> map = new HashMap<>();
            map.put("type", value.getClass().getSimpleName());
            map.put("value", value);
            return map;
        }
        return null; // not a simple type
    }

    /** Helper to detect simple types. */
    private static boolean isSimpleType(Object obj) {
        return obj instanceof String || obj instanceof Number ||
               obj instanceof Boolean || obj instanceof Character;
    }
}

