                ", lastName='" + lastName + '\'' +
                ", email='" + email + '\'' +
                ", phone='" + phone + '\'' +
                '}';
    }
}

/**
 * Manager responsible for creating, updating, deleting, and retrieving clients.
 */
class ClientManager {
    private final Map<Long, ClientTO> clients = new HashMap<>();
    private final AtomicLong idGenerator = new AtomicLong(1);

    /* ---------- Creation ---------- */

    /**
     * Creates a new client, assigns a unique ID, stores it, and returns the client.
     *
     * @param client the client data (without ID)
     * @return the client with the assigned unique ID
     * @throws IllegalArgumentException if client is null, has a non-zero ID,
     *                                  or if firstName, lastName, or email are null/empty,
     *                                  or if email does not contain '@'.
     */
    public ClientTO createClient(ClientTO client) {
        validateClientForCreate(client);
        long id = idGenerator.getAndIncrement();
        client.setId(id);
        clients.put(id, client);
        return client;
    }

    /* ---------- Update ---------- */

    /**
     * Updates an existing client.
     *
     * @param client the client data with an existing ID
     * @return the updated client
     * @throws IllegalArgumentException if client is null, id is null, client does not exist,
     *                                  or if firstName, lastName, or email are null/empty,
     *                                  or if email does not contain '@'.
     */
    public ClientTO updateClient(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null.");
        }
        long id = client.getId();
        if (id == 0) {
            throw new IllegalArgumentException("Client ID must be set for update.");
        }
        ClientTO existing = clients.get(id);
        if (existing == null) {
            throw new IllegalArgumentException("Client with ID " + id + " does not exist.");
        }
        validateClientForUpdate(client);
        // Update fields
        existing.setFirstName(client.getFirstName());
        existing.setLastName(client.getLastName());
        existing.setEmail(client.getEmail());
        existing.setPhone(client.getPhone());
        return existing;
    }

    /* ---------- Deletion ---------- */

    /**
     * Deletes a client by ID.
     *
     * @param id the client ID
     * @return true if the client was found and deleted, false otherwise
     * @throws IllegalArgumentException if id is null
     */
    public boolean deleteClient(Long id) {
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null.");
        }
        return clients.remove(id) != null;
    }

    /* ---------- Retrieval ---------- */

    /**
     * Finds a client by its ID.
     *
     * @param id the client ID
     * @return the client if found, otherwise null
     * @throws IllegalArgumentException if id is null
     */
    public ClientTO findClient(Long id) {
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null.");
        }
        return clients.get(id);
    }

    /**
     * Returns all stored clients.
     *
     * @return a collection of all clients
     */
    public Collection<ClientTO> getAllClients() {
        return clients.values();
    }

    /* ---------- Validation Helpers ---------- */

    private void validateClientForCreate(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null.");
        }
        if (client.getId() != 0) {
            throw new IllegalArgumentException("Client ID must be zero before creation.");
        }
        validateClientFields(client);
    }

    private void validateClientForUpdate(ClientTO client) {
        validateClientFields(client);
    }

    private void validateClientFields(ClientTO client) {
        if (isNullOrEmpty(client.getFirstName())) {
            throw new IllegalArgumentException("First name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getLastName())) {
            throw new IllegalArgumentException("Last name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getEmail())) {
            throw new IllegalArgumentException("Email cannot be null or empty.");
        }
        if (!client.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'.");
        }
    }

    private boolean isNullOrEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }
}

/**
 * Demonstrates the usage of ClientManager and ClientTO.
 */
public class Main {
    public static void main(String[] args) {
        ClientManager manager = new ClientManager();

        // Create clients
        ClientTO client1 = new ClientTO("Alice", "Smith", "alice@example.com", "555-0101");
        ClientTO client2 = new ClientTO("Bob", "Johnson", "bob@example.com", "555-0202");
        ClientTO created1 = manager.createClient(client1);
        ClientTO created2 = manager.createClient(client2);

        System.out.println("Created clients:");
        System.out.println(created1);
        System.out.println(created2);

        // Update client1
        ClientTO updateInfo = new ClientTO("Alice", "Brown", "alice.brown@example.com", "555-0303");
        updateInfo.setId(created1.getId()); // set existing ID
        ClientTO updated = manager.updateClient(updateInfo);
        System.out.println("\nUpdated client:");
        System.out.println(updated);

        // Delete client2
        boolean deleted = manager.deleteClient(created2.getId());
        System.out.println("\nDeleted client2: " + deleted);

        // Attempt to delete non-existent client
        boolean deletedNonExistent = manager.deleteClient(999L);
        System.out.println("Deleted non-existent client: " + deletedNonExistent);

        // List all clients
        System.out.println("\nAll stored clients:");
        for (ClientTO client : manager.getAllClients()) {
            System.out.println(client);
        }
    }
}

