/**
 * Manager responsible for creating, updating, deleting, and retrieving clients.
 */
class ClientManager {
    private final Map<Long, ClientTO> clients = new HashMap<>();
    private final AtomicLong idGenerator = new AtomicLong(1);

    /* ---------- Creation ---------- */

    public ClientTO createClient(ClientTO client) {
        validateClientForCreate(client);
        long id = idGenerator.getAndIncrement();
        client.setId(id);
        clients.put(id, client);
        return client;
    }

    /* ---------- Update ---------- */

    public ClientTO updateClient(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null.");
        }
        long id = client.getId();
        if (id == 0) {
            throw new IllegalArgumentException("Client ID must be set for update.");
        }
        ClientTO existing = clients.get(id);
        if (existing == null) {
            throw new IllegalArgumentException("Client with ID " + id + " does not exist.");
        }
        validateClientFields(client);
        existing.setFirstName(client.getFirstName());
        existing.setLastName(client.getLastName());
        existing.setEmail(client.getEmail());
        existing.setPhone(client.getPhone());
        return existing;
    }

    /* ---------- Deletion ---------- */

    public boolean deleteClient(Long id, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to delete a client.");
        }
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null.");
        }
        return clients.remove(id) != null;
    }

    /* ---------- Retrieval ---------- */

    public ClientTO findClient(Long id, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to find a client.");
        }
        if (id == null) {
            throw new IllegalArgumentException("ID cannot be null.");
        }
        return clients.get(id);
    }

    /**
     * Returns all clients if filter is null/empty, otherwise returns clients whose
     * first name, last name, or email contain the filter string (case‑insensitive).
     */
    public Collection<ClientTO> findAllClients(String filter, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to list all clients.");
        }
        if (filter == null || filter.trim().isEmpty()) {
            return clients.values();
        }
        String lower = filter.toLowerCase();
        List<ClientTO> result = new ArrayList<>();
        for (ClientTO c : clients.values()) {
            if (containsIgnoreCase(c.getFirstName(), lower) ||
                containsIgnoreCase(c.getLastName(), lower) ||
                containsIgnoreCase(c.getEmail(), lower)) {
                result.add(c);
            }
        }
        return result;
    }

    /**
     * Searches clients by first or last name (case‑insensitive).
     * @throws IllegalArgumentException if name is null or empty.
     */
    public Collection<ClientTO> findClientsByName(String name, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to search clients by name.");
        }
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty.");
        }
        String lower = name.toLowerCase();
        List<ClientTO> result = new ArrayList<>();
        for (ClientTO c : clients.values()) {
            if (containsIgnoreCase(c.getFirstName(), lower) ||
                containsIgnoreCase(c.getLastName(), lower)) {
                result.add(c);
            }
        }
        return result;
    }

    /* ---------- Validation Helpers ---------- */

    private void validateClientForCreate(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null.");
        }
        if (client.getId() != 0) {
            throw new IllegalArgumentException("Client ID must be zero before creation.");
        }
        validateClientFields(client);
    }

    private void validateClientFields(ClientTO client) {
        if (isNullOrEmpty(client.getFirstName())) {
            throw new IllegalArgumentException("First name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getLastName())) {
            throw new IllegalArgumentException("Last name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getEmail())) {
            throw new IllegalArgumentException("Email cannot be null or empty.");
        }
        if (!client.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'.");
        }
    }

    private boolean isNullOrEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }

    private boolean containsIgnoreCase(String source, String search) {
        return source != null && source.toLowerCase().contains(search);
    }

    /* ---------- Admin Privilege Check ---------- */

    private boolean hasAdminPrivileges() {
        // For this implementation, no user has admin privileges.
        return false;
    }
}

/**
