        defaultResult.put("totalCartItems", 0);
        defaultResult.put("categoryNames", new ArrayList<String>());
        defaultResult.put("hasEmptyCategories", false);
        defaultResult.put("categoryNameLengths", new ArrayList<Integer>());

        // Treat null or empty input strings as no data
        if (categoriesJson == null || categoriesJson.trim().isEmpty()
                || cartJson == null || cartJson.trim().isEmpty()) {
            return defaultResult;
        }

        // Pattern to extract the success field
        Pattern successPattern = Pattern.compile("\"success\"\\s*:\\s*(\\d+)");
        Matcher catSuccessMatcher = successPattern.matcher(categoriesJson);
        Matcher cartSuccessMatcher = successPattern.matcher(cartJson);

