            catSuccess = "1".equals(catSuccessMatcher.group(1));
        }
        if (cartSuccessMatcher.find()) {
            cartSuccess = "1".equals(cartSuccessMatcher.group(1));
        }

        // If either success flag is not 1, return default result
        if (!catSuccess || !cartSuccess) {
            return defaultResult;
        }

        // Patterns for extracting arrays and objects
        Pattern arrayPattern = Pattern.compile("\"categories\"\\s*:\\s*\\[(.*?)\\]|\"products\"\\s*:\\s*\\[(.*?)\\]",
                Pattern.DOTALL);
        Pattern objectPattern = Pattern.compile("\\{[^}]*\\}");

        // Patterns for extracting fields
