        if (catArrayMatcher.find()) {
            String catArrayContent = catArrayMatcher.group(1);
            Matcher catObjMatcher = objectPattern.matcher(catArrayContent);
            while (catObjMatcher.find()) {
                String obj = catObjMatcher.group();
                Matcher nameMatcher = namePattern.matcher(obj);
                String name = "";
                if (nameMatcher.find()) {
                    if (!"null".equals(nameMatcher.group(1))) {
                        name = nameMatcher.group(2);
                    }
                }
                // If name field is missing, name remains empty string
                categoryNames.add(name);
            }
