import java.util.List;

class MinesweeperSolver {
    private char[][] map;          // board with numbers and mines
    private boolean[][] visited;   // cells that have been revealed
    private final int[] dirR = {-1, -1, -1, 0, 0, 1, 1, 1};
    private final int[] dirC = {-1, 0, 1, -1, 1, -1, 0, 1};

    /**
     * Builds the board, places mines, calculates adjacent mine counts,
     * and returns the minimum number of clicks required to reveal all
     * safe cells using the automatic zero‑cell expansion rule.
     *
     * @param boardSize     size of the board (boardSize × boardSize)
     * @param minePositions list of mine coordinates in the form "row,col"
     * @return minimum number of clicks needed
     */
    public int solveMinesweeper(int boardSize, List<String> minePositions) {
        // Create a padded board to avoid bounds checks
        map = new char[boardSize + 2][boardSize + 2];
        visited = new boolean[boardSize + 2][boardSize + 2];

        // Fill board with safe cells
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                map[i][j] = '.';
            }
        }

        // Place mines
        for (String pos : minePositions) {
            String[] parts = pos.split(",");
            int r = Integer.parseInt(parts[0].trim());
            int c = Integer.parseInt(parts[1].trim());
            map[r][c] = '*';
        }

        // Update each non‑mine cell with the count of adjacent mines
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] == '*') continue;
                int count = 0;
                for (int k = 0; k < 8; k++) {
                    int nr = i + dirR[k];
                    int nc = j + dirC[k];
                    if (map[nr][nc] == '*') count++;
                }
                map[i][j] = (char) ('0' + count);
            }
        }

        int clicks = 0;

        // Reveal all connected zero‑cell components
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] == '0' && !visited[i][j]) {
                    dfsReveal(i, j);
                    clicks++;          // one click for this component
                }
            }
        }

        // Any remaining unrevealed safe cells (numbered cells not adjacent to a zero)
        for (int i = 1; i <= boardSize; i++) {
            for (int j = 1; j <= boardSize; j++) {
                if (map[i][j] != '*' && !visited[i][j]) {
                    clicks++;          // each requires an individual click
                }
            }
        }

        return clicks;
    }

    /**
     * Depth‑first search that reveals a zero cell and all reachable
     * cells (zero cells and their adjacent numbered cells).
     *
     * @param r row index (1‑based, inside padded board)
     * @param c column index
     */
    private void dfsReveal(int r, int c) {
        visited[r][c] = true;
        // Explore all 8 neighbors
        for (int k = 0; k < 8; k++) {
            int nr = r + dirR[k];
            int nc = c + dirC[k];
            if (map[nr][nc] == '*') continue;          // skip mines
            if (visited[nr][nc]) continue;            // already revealed
            if (map[nr][nc] == '0') {
                dfsReveal(nr, nc);                    // recurse on zero cells
            } else {
                visited[nr][nc] = true;               // reveal numbered cell
            }
        }
    }
}

