                    '}';
        }
    }

    /**
     * Processes a list of PhoneContact objects in batches of 200, removes duplicate
     * phone numbers (only the first occurrence is kept), skips contacts with empty
     * phone numbers while counting them as failures, and returns a map containing:
     * <ul>
     *   <li>"success"          – List of successfully processed UserInfo objects</li>
     *   <li>"batchesProcessed" – Total number of batches processed</li>
     *   <li>"duplicateContacts" – Number of duplicate phone numbers encountered</li>
     *   <li>"failedProcesses"   – Number of contacts skipped due to empty phone numbers</li>
     * </ul>
     *
     * @param contacts List of PhoneContact objects to process.
     * @return Map with keys "success", "batchesProcessed", "duplicateContacts", and "failedProcesses".
     */
    public Map<String, Object> processContacts(List<PhoneContact> contacts) {
        List<UserInfo> processed = new ArrayList<>();
        Set<String> seenPhones = new HashSet<>();
        int duplicateCount = 0;
        int failureCount = 0;

        int totalContacts = (contacts == null) ? 0 : contacts.size();
        int batchesProcessed = (totalContacts + 199) / 200; // ceil division

