                    // Empty phone number – count as failure and skip
                    failureCount++;
                    continue;
                }

                // Basic validation: phone number must contain only digits
                if (!phone.matches("\\d+")) {
                    continue; // skip invalid format
                }

                if (!seenPhones.add(phone)) {
