import java.math.BigDecimal;
import java.math.RoundingMode;

class TaxPriceCalculator {

    public static BigDecimal[] calculatePriceAndTax(BigDecimal totalAmount, BigDecimal taxRate, boolean isTaxIncluded) {
        BigDecimal price;
        BigDecimal tax;

        if (isTaxIncluded) {
            // When the total amount already includes tax:
            // price = totalAmount / (1 + taxRate/100)
            BigDecimal divisor = BigDecimal.ONE
                    .add(taxRate.divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP));
            price = totalAmount.divide(divisor, 10, RoundingMode.HALF_UP);
            tax = totalAmount.subtract(price);
        } else {
            // When the total amount does NOT include tax:
            price = totalAmount;
            tax = totalAmount.multiply(taxRate)
                    .divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);
        }

        return new BigDecimal[]{price, tax};
    }
}

