                                                    boolean isTaxIncluded) {
        // Input validation
        if (totalAmount == null || taxRate == null) {
            throw new IllegalArgumentException("totalAmount and taxRate must not be null");
        }
        if (totalAmount.signum() < 0) {
            throw new IllegalArgumentException("totalAmount must not be negative");
        }
        if (taxRate.signum() < 0) {
            throw new IllegalArgumentException("taxRate must not be negative");
