            throw new IllegalArgumentException("totalAmount must not be negative");
        }
        if (taxRate.signum() < 0) {
            throw new IllegalArgumentException("taxRate must not be negative");
        }

        BigDecimal price;
        BigDecimal tax;

        if (isTaxIncluded) {
            // totalAmount already includes tax
            // price = totalAmount / (1 + taxRate/100)
            BigDecimal divisor = BigDecimal.ONE
                    .add(taxRate.divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP));
            price = totalAmount.divide(divisor, 10, RoundingMode.HALF_UP);
            tax = totalAmount.subtract(price);
        } else {
            // totalAmount does NOT include tax
            price = totalAmount;
            tax = totalAmount.multiply(taxRate)
                    .divide(BigDecimal.valueOf(100), 10, RoundingMode.HALF_UP);
        }

        // Round final results to 2 decimal places
        BigDecimal roundedPrice = price.setScale(2, RoundingMode.HALF_UP);
        BigDecimal roundedTax   = tax.setScale(2, RoundingMode.HALF_UP);

        return new BigDecimal[]{roundedPrice, roundedTax};
    }
}
