import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Manages texture packs for regions and handles player movement between them,
 * including support for excluding players from automatic texture changes
 * and detecting when no texture change is needed.
 */
class RegionTextureManager {
    private final Map<String, TexturePack> regionPacks = new HashMap<>();
    private final Set<String> excludedPlayers = new HashSet<>();
    private final Map<String, String> playerPreviousRegion = new HashMap<>();
    private TexturePack defaultPack;

    public RegionTextureManager(TexturePack defaultPack) {
        this.defaultPack = defaultPack;
    }

    /** Associates a texture pack with a region. */
    public void addRegionPack(String regionId, TexturePack pack) {
        regionPacks.put(regionId, pack);
    }

    /** Retrieves the texture pack for a region, falling back to the default pack if none is set. */
    public TexturePack getPackForRegion(String regionId) {
        if (regionId == null) {
            return defaultPack;
        }
        return regionPacks.getOrDefault(regionId, defaultPack);
    }

    /** Handles a player's movement into a region. */
    public String handlePlayerMovement(String playerId, String regionId) {
        // Exclusion check
        if (isExcluded(playerId)) {
            return String.format("Player %s is excluded from automatic texture changes", playerId);
        }

        // Resolve previous and new texture packs
        String prevRegion = playerPreviousRegion.get(playerId); // may be null
        TexturePack prevPack = getPackForRegion(prevRegion);
        TexturePack newPack = getPackForRegion(regionId);

        // Detect no change
        if (prevPack == newPack) {
            // Update previous region for future moves
            playerPreviousRegion.put(playerId, regionId);
            return "No texture change needed - same pack in both regions";
        }

        // Apply new pack
        String result;
        if (regionId == null) {
            result = String.format("Applied default texture pack to player %s", playerId);
        } else {
            result = String.format("Applied texture pack %s to player %s", newPack.getName(), playerId);
        }

        // Update previous region for future moves
        playerPreviousRegion.put(playerId, regionId);
        return result;
    }

    /** Excludes or includes a player from automatic texture changes. */
    public void setPlayerExcluded(String playerId, boolean excluded) {
        if (excluded) {
            excludedPlayers.add(playerId);
        } else {
            excludedPlayers.remove(playerId);
        }
    }

    /** Checks whether a player is excluded. */
    private boolean isExcluded(String playerId) {
        return excludedPlayers.contains(playerId);
    }

    /** Removes the texture pack association for a region. */
    public void removeRegionPack(String regionId) {
        regionPacks.remove(regionId);
    }

    /** Returns an unmodifiable set of all region IDs that have a custom pack. */
    public Set<String> getAllRegionIds() {
        return Collections.unmodifiableSet(regionPacks.keySet());
    }

    /** Returns an unmodifiable view of all region-to-pack mappings. */
    public Map<String, TexturePack> getAllRegionPacks() {
        return Collections.unmodifiableMap(regionPacks);
    }

    /** Sets a new default texture pack. */
    public void setDefaultPack(TexturePack pack) {
        this.defaultPack = pack;
