class AdvancedTreeLoader<T extends Comparable<T>> {
    /**
     * Loads data into the given BinaryTree. If {@code shouldSort} is true,
     * the data is sorted and inserted in a balanced manner using a recursive
     * helper {@code loadBalanced}. Otherwise, data is inserted in the order
     * provided.
     *
     * @param tree       the BinaryTree to load data into
     * @param data       the list of data elements
     * @param shouldSort whether to sort and balance the tree
     */
    public void load(BinaryTree<T> tree, List<T> data, boolean shouldSort) {
        if (data == null || data.isEmpty()) {
            return;
        }
        if (shouldSort) {
            List<T> sorted = new ArrayList<>(data);
            Collections.sort(sorted);
            loadBalanced(tree, sorted, 0, sorted.size() - 1);
        } else {
            for (T element : data) {
                tree.insert(element);
            }
        }
    }

    /**
     * Recursively inserts elements from a sorted list into the tree in a
     * balanced order. The middle element of the current sublist is inserted
     * first, then the left and right halves are processed recursively.
