import java.util.HashMap;
import java.util.Map;

/**
 * Definition for a binary tree node.
 */
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode(int val) {
        this.val = val;
    }
}

/**
 * TreeAnalyzer provides analysis utilities for binary trees.
 */
public class TreeAnalyzer {

    /**
     * Analyzes the given binary tree and returns a map containing the total node count
     * and the maximum ancestor difference.
     *
     * @param root the root of the binary tree (may be null)
     * @return a map with two entries:
     *         - key "nodeCount" -> total number of nodes
     *         - key "maxDiff"   -> maximum absolute difference between any ancestor and descendant
     */
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();

        int nodeCount = countNodes(root);
        result.put("nodeCount", nodeCount);

        int maxDiff = 0;
        if (root != null) {
            int[] maxDiffHolder = new int[]{0};
            traverse(root, root.val, root.val, maxDiffHolder);
            maxDiff = maxDiffHolder[0];
        }
        result.put("maxDiff", maxDiff);

        return result;
    }

    /**
     * Recursively counts the number of nodes in the binary tree.
     *
     * @param node the current node
     * @return the number of nodes in the subtree rooted at node
     */
    private int countNodes(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + countNodes(node.left) + countNodes(node.right);
    }

    /**
     * Traverses the tree to compute the maximum ancestor difference.
     *
     * @param node          the current node
     * @param currentMin    the minimum value along the path from the root to this node
     * @param currentMax    the maximum value along the path from the root to this node
     * @param maxDiffHolder an array holding the maximum difference found so far
     */
    private void traverse(TreeNode node, int currentMin, int currentMax, int[] maxDiffHolder) {
        if (node == null) {
            return;
        }

        // Update max difference using current node's value
        int diffWithMin = Math.abs(node.val - currentMin);
        int diffWithMax = Math.abs(node.val - currentMax);
        int localMaxDiff = Math.max(diffWithMin, diffWithMax);
        if (localMaxDiff > maxDiffHolder[0]) {
            maxDiffHolder[0] = localMaxDiff;
        }

        // Update min and max for the path to children
        int newMin = Math.min(currentMin, node.val);
        int newMax = Math.max(currentMax, node.val);

        traverse(node.left, newMin, newMax, maxDiffHolder);
        traverse(node.right, newMin, newMax, maxDiffHolder);
    }
}

