import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Definition for a binary tree node.
 */
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode(int val) {
        this.val = val;
    }
}

/**
 * TreeAnalyzer provides analysis utilities for binary trees.
 */
public class TreeAnalyzer {

    // Global accumulators used during a single traversal
    private int nodeCount;
    private int maxDiff;
    private int minDiff;
    private long sumDiff;

    /**
     * Analyzes the given binary tree and returns a map containing the total node count,
     * the maximum ancestor difference, the minimum ancestor difference, and the average
     * ancestor difference (floor of sum of all differences divided by node count).
     *
     * @param root the root of the binary tree (may be null)
     * @return a map with four entries:
     *         - key "nodeCount" -> total number of nodes
     *         - key "maxDiff"   -> maximum absolute difference between any ancestor and descendant
     *         - key "minDiff"   -> minimum absolute difference between any ancestor and descendant
     *         - key "avgDiff"   -> floor of (sum of all ancestor differences / total node count)
     */
    public Map<String, Integer> analyzeTree(TreeNode root) {
        // Reset accumulators
        nodeCount = 0;
        maxDiff = 0;
        minDiff = Integer.MAX_VALUE;
        sumDiff = 0L;

        if (root != null) {
            List<Integer> ancestors = new ArrayList<>();
            traverse(root, ancestors);
        }

        // Handle cases with no ancestor pairs
        if (nodeCount == 0) {
            minDiff = 0;
            maxDiff = 0;
        } else if (minDiff == Integer.MAX_VALUE) {
            minDiff = 0;
        }

        int avgDiff = nodeCount == 0 ? 0 : (int) (sumDiff / nodeCount);

        Map<String, Integer> result = new HashMap<>();
        result.put("nodeCount", nodeCount);
        result.put("maxDiff", maxDiff);
        result.put("minDiff", minDiff);
        result.put("avgDiff", avgDiff);
        return result;
    }

    /**
     * Recursively traverses the tree, updating global accumulators.
     *
     * @param node      the current node
     * @param ancestors list of ancestor values along the current path
     */
    private void traverse(TreeNode node, List<Integer> ancestors) {
        if (node == null) {
            return;
        }

        // Count the current node
        nodeCount++;

        // Compute differences with all ancestors
        for (int ancVal : ancestors) {
            int diff = Math.abs(node.val - ancVal);
            sumDiff += diff;
            if (diff > maxDiff) {
                maxDiff = diff;
            }
            if (diff < minDiff) {
                minDiff = diff;
            }
        }

        // Add current node to the ancestor list
        ancestors.add(node.val);

        // Recurse on children
        traverse(node.left, ancestors);
        traverse(node.right, ancestors);

        // Backtrack: remove current node from ancestor list
        ancestors.remove(ancestors.size() - 1);
    }
}

