import java.util.ArrayList;
import java.util.List;

/**
 * Holds statistics about thread execution.
 */
class ThreadStatistics {
    private final int totalThreadCount;
    private final int completedTasks;
    private final int interruptedTasks;

    public ThreadStatistics(int totalThreadCount, int completedTasks, int interruptedTasks) {
        this.totalThreadCount = totalThreadCount;
        this.completedTasks = completedTasks;
        this.interruptedTasks = interruptedTasks;
    }

    public int getTotalThreadCount() {
        return totalThreadCount;
    }

    public int getCompletedTasks() {
        return completedTasks;
    }

    public int getInterruptedTasks() {
        return interruptedTasks;
    }

    @Override
    public String toString() {
        return "ThreadStatistics{" +
                "totalThreadCount=" + totalThreadCount +
                ", completedTasks=" + completedTasks +
                ", interruptedTasks=" + interruptedTasks +
                '}';
    }
}

/**
 * Manages the creation and execution of worker threads.
 */
public class ThreadManager {

    /**
     * Creates {@code threadCount} worker threads that print their name when starting,
     * sleep for {@code workDurationMs} milliseconds, and then exit.
     * After all threads are created, waits for them to finish and returns a
     * {@link ThreadStatistics} object containing the total thread count and zeros
     * for completed and interrupted tasks.
     *
     * @param threadCount      number of worker threads to create
     * @param workDurationMs   duration each thread sleeps for (in milliseconds)
     * @param interruptAfterMs duration after which all threads are interrupted (in milliseconds)
     * @return ThreadStatistics object with total thread count and zeros for completed/interrupted tasks
     */
    public ThreadStatistics manageThreads(int threadCount, long workDurationMs, long interruptAfterMs) {
        List<Thread> threads = new ArrayList<>(threadCount);

        // Create and start worker threads
        for (int i = 0; i < threadCount; i++) {
            Thread worker = new Thread(() -> {
                System.out.println(Thread.currentThread().getName() + " starting");
                try {
                    Thread.sleep(workDurationMs);
                } catch (InterruptedException e) {
                    // Thread was interrupted; ignore for statistics
                }
            }, "Worker-" + i);
            threads.add(worker);
            worker.start();
        }

        // Optional: interrupt all threads after a specified delay
        if (interruptAfterMs > 0) {
            try {
                Thread.sleep(interruptAfterMs);
            } catch (InterruptedException e) {
                // Main thread was interrupted; ignore
            }
            for (Thread t : threads) {
                t.interrupt();
            }
        }

        // Wait for all threads to finish
        for (Thread t : threads) {
            try {
                t.join();
            } catch (InterruptedException e) {
                // Main thread was interrupted; ignore
            }
        }

        // Return statistics with zeros for completed and interrupted tasks
        return new ThreadStatistics(threadCount, 0, 0);
    }

    // Example usage (optional)
    public static void main(String[] args) {
        ThreadManager manager = new ThreadManager();
        ThreadStatistics stats = manager.manageThreads(5, 2000, 1000);
        System.out.println(stats);
    }
}

