public class RedditFeedAnalyzer {
    public String analyzeAndFormatFeed(List<RedditFeedItem> items, int minScore) {
        if (items == null || items.isEmpty()) {
            return "No feed items to analyze";
        }

        // Filter items with score >= minScore
        List<RedditFeedItem> filtered = items.stream()
                .filter(item -> item.getScore() >= minScore)
                .collect(Collectors.toList());

        long totalItems = filtered.size();

        // Compute sums for average calculation
        long sumScore = 0;
        long sumComments = 0;
        for (RedditFeedItem item : filtered) {
            // In this implementation score and numComments are ints,
            // so they are always parseable. If they were strings,
            // we would need to try-catch parsing here.
            sumScore += item.getScore();
            sumComments += item.getNumComments();
        }

        double avgScore = totalItems > 0 ? (double) sumScore / totalItems : 0.0;
        double avgComments = totalItems > 0 ? (double) sumComments / totalItems : 0.0;

        StringBuilder sb = new StringBuilder();
        sb.append("Feed Analysis Summary:\n");
        sb.append("Total items: ").append(totalItems).append("\n");
        sb.append("Average score: ").append(String.format("%.2f", avgScore)).append("\n");
        sb.append("Average comments: ").append(String.format("%.2f", avgComments));

        return sb.toString();
    }
}

