import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;

class TimeDifferenceCalculator {
    private static final String DEFAULT_DATETIME_PATTERN = "yyyy-MM-dd HH:mm:ss";

    public static Map<String, Object> calculateDetailedTimeDifference(String earlierTime, String laterTime)
            throws ParseException {
        // Parse the input strings into Date objects
        SimpleDateFormat sdf = new SimpleDateFormat(DEFAULT_DATETIME_PATTERN);
        Date earlierDate = sdf.parse(earlierTime);
        Date laterDate = sdf.parse(laterTime);

        // Calculate the difference in milliseconds
        long diffMillis = laterDate.getTime() - earlierDate.getTime();

        // Convert milliseconds to larger units
        long diffSeconds = diffMillis / 1000;
        long diffMinutes = diffSeconds / 60;
        long diffHours = diffMinutes / 60;
        long diffDays = diffHours / 24;
        long diffWeeks = diffDays / 7;

        // Build human‑readable string
        long weeks = diffWeeks;
        long days = diffDays % 7;
        long hours = diffHours % 24;
        long minutes = diffMinutes % 60;
        long seconds = diffSeconds % 60;

        StringBuilder humanReadable = new StringBuilder();
        if (weeks > 0) humanReadable.append(weeks).append(" week").append(weeks == 1 ? "" : "s").append(", ");
        if (days > 0) humanReadable.append(days).append(" day").append(days == 1 ? "" : "s").append(", ");
        if (hours > 0) humanReadable.append(hours).append(" hour").append(hours == 1 ? "" : "s").append(", ");
        if (minutes > 0) humanReadable.append(minutes).append(" minute").append(minutes == 1 ? "" : "s").append(", ");
        humanReadable.append(seconds).append(" second").append(seconds == 1 ? "" : "s");

        // Prepare the result map
        Map<String, Object> result = new HashMap<>();
        result.put("seconds", diffSeconds);
        result.put("minutes", diffMinutes);
        result.put("hours", diffHours);
        result.put("days", diffDays);
        result.put("weeks", diffWeeks);
        result.put("humanReadable", humanReadable.toString());

        return result;
    }
}

