class EggDropSolver {

    /** Result container holding both DP and mathematical solutions
     *  together with their computation times (nanoseconds). */
    public static class Result {
        public final int dpResult;   // minimal attempts by DP
        public final long dpTime;    // time taken by DP (nanoseconds)
        public final int mathResult; // minimal attempts by math
        public final long mathTime;  // time taken by math (nanoseconds)

        public Result(int dpResult, long dpTime, int mathResult, long mathTime) {
            this.dpResult = dpResult;
            this.dpTime = dpTime;
            this.mathResult = mathResult;
            this.mathTime = mathTime;
        }
    }

    /**
     * Computes the minimum number of attempts needed to find the critical floor
     * using both a dynamic‑programming approach and a mathematical approach
     * based on binomial coefficients.  The method returns both results and
     * the time taken by each approach.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return Result object containing both solutions and their times
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static Result solveEggDrop(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }

        long startDP = System.nanoTime();
        int dpResult = solveDP(k, n);
        long endDP = System.nanoTime();

        long startMath = System.nanoTime();
        int mathResult = solveMath(k, n);
        long endMath = System.nanoTime();

        return new Result(dpResult, endDP - startDP, mathResult, endMath - startMath);
    }

    /* ---------- Dynamic‑Programming solution ---------- */
    private static int solveDP(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        long[] dp = new long[k + 1]; // dp[i] = max floors testable with i eggs and current moves
        int moves = 0;

        while (dp[k] < n) {
            moves++;
            for (int i = k; i >= 1; i--) {
                dp[i] = dp[i] + dp[i - 1] + 1;
            }
        }
        return moves;
    }

    /* ---------- Mathematical (binomial‑coefficient) solution ---------- */
    private static int solveMath(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        int moves = 0;
        java.math.BigInteger target = java.math.BigInteger.valueOf(n);

        while (true) {
            moves++;
            java.math.BigInteger sum = java.math.BigInteger.ZERO;
            java.math.BigInteger binom = java.math.BigInteger.ONE; // C(moves, 0)

            for (int i = 1; i <= k; i++) {
                // Compute C(moves, i) from C(moves, i-1)
                binom = binom.multiply(java.math.BigInteger.valueOf(moves - i + 1))
                             .divide(java.math.BigInteger.valueOf(i));
                sum = sum.add(binom);
                if (sum.compareTo(target) >= 0) {
                    break;
                }
            }
            if (sum.compareTo(target) >= 0) {
                break;
            }
        }
        return moves;
    }
}

