class EggDropSolver {

    /** Result container holding the three solutions and their computation times (nanoseconds). */
    public static class Result {
        public final int dpResult;      // DP solution
        public final long dpTime;       // time taken by DP
        public final int mathResult;    // Mathematical (binomial) solution
        public final long mathTime;     // time taken by math
        public final int bsResult;      // Binary‑search solution
        public final long bsTime;       // time taken by binary search

        public Result(int dpResult, long dpTime,
                      int mathResult, long mathTime,
                      int bsResult, long bsTime) {
            this.dpResult = dpResult;
            this.dpTime = dpTime;
            this.mathResult = mathResult;
            this.mathTime = mathTime;
            this.bsResult = bsResult;
            this.bsTime = bsTime;
        }
    }

    /**
     * Computes the minimum number of attempts needed to find the critical floor
     * using three different approaches: dynamic programming, mathematical
     * binomial‑coefficient, and binary search with memoization.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return Result object containing all three solutions and their times
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static Result solveEggDrop(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }

        long startDP = System.nanoTime();
        int dpResult = solveDP(k, n);
        long endDP = System.nanoTime();

        long startMath = System.nanoTime();
        int mathResult = solveMath(k, n);
        long endMath = System.nanoTime();

        long startBS = System.nanoTime();
        int bsResult = solveBinarySearch(k, n);
        long endBS = System.nanoTime();

        return new Result(dpResult, endDP - startDP,
                          mathResult, endMath - startMath,
                          bsResult, endBS - startBS);
    }

    /* ---------- Dynamic‑Programming solution ---------- */
    private static int solveDP(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        long[] dp = new long[k + 1]; // dp[i] = max floors testable with i eggs and current moves
        int moves = 0;

        while (dp[k] < n) {
            moves++;
            for (int i = k; i >= 1; i--) {
                dp[i] = dp[i] + dp[i - 1] + 1;
                if (dp[i] > n) dp[i] = n + 1; // cap to avoid overflow
            }
        }
        return moves;
    }

    /* ---------- Mathematical (binomial‑coefficient) solution ---------- */
    private static int solveMath(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        int moves = 0;
        java.math.BigInteger target = java.math.BigInteger.valueOf(n);

        while (true) {
            moves++;
            java.math.BigInteger sum = java.math.BigInteger.ZERO;
            java.math.BigInteger binom = java.math.BigInteger.ONE; // C(moves, 0)

            for (int i = 1; i <= k; i++) {
                // Compute C(moves, i) from C(moves, i-1)
                binom = binom.multiply(java.math.BigInteger.valueOf(moves - i + 1))
                             .divide(java.math.BigInteger.valueOf(i));
                sum = sum.add(binom);
                if (sum.compareTo(target) >= 0) {
                    break;
                }
            }
            if (sum.compareTo(target) >= 0) {
                break;
            }
        }
        return moves;
    }

    /* ---------- Binary‑search solution with memoization ---------- */
    private static int solveBinarySearch(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        int low = 1;
        int high = n; // worst case: one egg per floor

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canCover(mid, k, n)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    /**
     * Checks whether with {@code attempts} attempts and {@code eggs} eggs
     * we can test at least {@code floors} floors.
     * Uses the DP recurrence: dp[i][j] = dp[i-1][j-1] + dp[i-1][j] + 1.
     */
    private static boolean canCover(int attempts, int eggs, int floors) {
        long[] dp = new long[eggs + 1];
        for (int i = 1; i <= attempts; i++) {
            for (int j = eggs; j >= 1; j--) {
                dp[j] = dp[j] + dp[j - 1] + 1;
                if (dp[j] > floors) dp[j] = floors + 1; // cap to avoid overflow
            }
        }
        return dp[eggs] >= floors;
    }
}

