                binom = binom.multiply(java.math.BigInteger.valueOf(moves - i + 1))
                             .divide(java.math.BigInteger.valueOf(i));
                sum = sum.add(binom);
                if (sum.compareTo(target) >= 0) {
                    break;
                }
            }
            if (sum.compareTo(target) >= 0) {
                break;
            }
        }
        return moves;
    }

    /* ---------- Binary‑search solution with memoization ---------- */
    private static int solveBinarySearch(int k, int n) {
        if (n == 1) return 1;
        if (k == 1) return n;

        int low = 1;
        int high = n; // worst case: one egg per floor

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canCover(mid, k, n)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    /**
     * Checks whether with {@code attempts} attempts and {@code eggs} eggs
     * we can test at least {@code floors} floors.
     * Uses the DP recurrence: dp[i][j] = dp[i-1][j-1] + dp[i-1][j] + 1.
     */
    private static boolean canCover(int attempts, int eggs, int floors) {
        long[] dp = new long[eggs + 1];
        for (int i = 1; i <= attempts; i++) {
            for (int j = eggs; j >= 1; j--) {
                dp[j] = dp[j] + dp[j - 1] + 1;
                if (dp[j] > floors) dp[j] = floors + 1; // cap to avoid overflow
            }
        }
        return dp[eggs] >= floors;
    }
}
