import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;

/**
 * Holds the results of the egg‑drop solver and formats them for display.
 * The output string shows each solution value and its computation time
 * in nanoseconds, with comma separators for thousands (pattern "#,##0").
 */
public class EggDropResult {
    private final int dpResult;
    private final long dpTime;
    private final int mathResult;
    private final long mathTime;
    private final int bsResult;
    private final long bsTime;

    public EggDropResult(int dpResult, long dpTime,
                         int mathResult, long mathTime,
                         int bsResult, long bsTime) {
        this.dpResult = dpResult;
        this.dpTime = dpTime;
        this.mathResult = mathResult;
        this.mathTime = mathTime;
        this.bsResult = bsResult;
        this.bsTime = bsTime;
    }

    /**
     * Formats the result as a single string.
     * Example:
     *   DP: 14 (time: 1,234,567 ns)
     *   Math: 14 (time: 1,234,567 ns)
     *   BinarySearch: 14 (time: 1,234,567 ns)
     *
     * @return formatted result string
     */
    @Override
    public String toString() {
        DecimalFormat df = new DecimalFormat("#,##0");
        // Ensure the grouping separator is a comma regardless of locale
        DecimalFormatSymbols symbols = new DecimalFormatSymbols();
        symbols.setGroupingSeparator(',');
        df.setDecimalFormatSymbols(symbols);

        StringBuilder sb = new StringBuilder();
        sb.append("DP: ")
          .append(df.format(dpResult))
          .append(" (time: ")
          .append(df.format(dpTime))
          .append(" ns)");

        sb.append("\nMath: ")
          .append(df.format(mathResult))
          .append(" (time: ")
          .append(df.format(mathTime))
          .append(" ns)");

        sb.append("\nBinarySearch: ")
          .append(df.format(bsResult))
          .append(" (time: ")
          .append(df.format(bsTime))
          .append(" ns)");

        return sb.toString();
    }
}

