public class EnhancedBinaryHeap<T extends Comparable<T>> {
    private static final int DEFAULT_CAPACITY = 10;
    private T[] heap;
    private int size;

    @SuppressWarnings("unchecked")
    public EnhancedBinaryHeap() {
        heap = (T[]) new Comparable[DEFAULT_CAPACITY];
        size = 0;
    }

    @SuppressWarnings("unchecked")
    public EnhancedBinaryHeap(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        heap = (T[]) new Comparable[capacity];
        size = 0;
    }

    /** Returns true if the heap contains no elements. */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Returns the number of elements in the heap. */
    public int size() {
        return size;
    }

    /** Removes all elements from the heap. */
    public void makeEmpty() {
        size = 0;
    }

    /** Returns the minimum element without removing it. */
    public T peekRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return heap[0];
    }

    /** Inserts a new element into the heap. */
    public void insert(T value) {
        if (value == null) {
            throw new IllegalArgumentException("Null values not allowed");
        }
        if (size == heap.length) {
            resize();
        }
        heap[size] = value;
        siftUp(size);
        size++;
    }

    /** Removes and returns the minimum element from the heap. */
    public T deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        T root = heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            siftDown(0);
        }
        heap[size] = null; // avoid loitering
        return root;
    }

    /* Helper methods */

    private void siftUp(int idx) {
        T value = heap[idx];
        while (idx > 0) {
            int parentIdx = (idx - 1) / 2;
            T parent = heap[parentIdx];
            if (value.compareTo(parent) >= 0) {
                break;
            }
            heap[idx] = parent;
            idx = parentIdx;
        }
        heap[idx] = value;
    }

    private void siftDown(int idx) {
        T value = heap[idx];
        int half = size / 2; // nodes with children
        while (idx < half) {
            int left = 2 * idx + 1;
            int right = left + 1;
            int smallest = left;
            if (right < size && heap[right].compareTo(heap[left]) < 0) {
                smallest = right;
            }
            if (heap[smallest].compareTo(value) >= 0) {
                break;
            }
            heap[idx] = heap[smallest];
            idx = smallest;
        }
        heap[idx] = value;
    }

    @SuppressWarnings("unchecked")
    private void resize() {
        int newCapacity = heap.length * 2;
        T[] newHeap = (T[]) new Comparable[newCapacity];
        System.arraycopy(heap, 0, newHeap, 0, heap.length);
        heap = newHeap;
    }
}

