        this.heap = (T[]) new Comparable[size];
        this.vertex1 = new int[size];
        this.vertex2 = new int[size];
        System.arraycopy(items, 0, heap, 0, size);
        // No vertex information for bulk build – set to 0
        for (int i = 0; i < size; i++) {
            vertex1[i] = 0;
            vertex2[i] = 0;
        }
        buildHeap();
    }

    /* --------------------- Public API --------------------- */

    /** Returns true if the heap contains no elements. */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Returns the number of elements in the heap. */
