        vertex1[size] = v1;
        vertex2[size] = v2;
        siftUp(size);
        size++;
    }

    /** Removes and returns the root element from the heap. */
    public T deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
