        T root = heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            vertex1[0] = vertex1[size];
            vertex2[0] = vertex2[size];
            siftDown(0);
        }
        heap[size] = null; // avoid loitering
        vertex1[size] = 0;
        vertex2[size] = 0;
        return root;
