    private void siftDown(int idx) {
        T value = heap[idx];
        int v1 = vertex1[idx];
        int v2 = vertex2[idx];
        int half = size / 2; // nodes with at least one child
        while (idx < half) {
            int left = 2 * idx + 1;
            int right = left + 1;
            int betterChild = left;

            if (right < size && compare(heap[right], heap[left]) < 0) {
                betterChild = right;
            }

            if (compare(heap[betterChild], value) >= 0) {
                break;
            }

            heap[idx] = heap[betterChild];
            vertex1[idx] = vertex1[betterChild];
            vertex2[idx] = vertex2[betterChild];
            idx = betterChild;
        }
        heap[idx] = value;
        vertex1[idx] = v1;
        vertex2[idx] = v2;
    }

    /** Resizes the internal arrays to double their current capacity. */
    @SuppressWarnings("unchecked")
    private void resize() {
        int newCapacity = heap.length * 2;
