        System.arraycopy(vertex1, 0, newV1, 0, vertex1.length);
        System.arraycopy(vertex2, 0, newV2, 0, vertex2.length);
        heap = newHeap;
        vertex1 = newV1;
        vertex2 = newV2;
    }

    /** Builds the heap in O(n) time. */
    private void buildHeap() {
        for (int i = (size / 2) - 1; i >= 0; i--) {
            siftDown(i);
        }
    }

