public class EnhancedTrie {

    /** Nested TrieNode class */
    private static class TrieNode {
        char value;                     // character stored in this node
        boolean isEndOfWord;            // true if this node terminates a word
        TrieNode[] children;            // children for each letter a-z

        TrieNode(char value) {
            this.value = value;
            this.isEndOfWord = false;
            this.children = new TrieNode[26]; // assuming lowercase English letters
        }
    }

    private final TrieNode root;

    public EnhancedTrie() {
        root = new TrieNode('\0'); // root does not hold a character
    }

    /**
     * Inserts a word into the trie.
     *
     * @param word the word to add
     */
    public void add(String word) {
        if (word == null || word.isEmpty()) {
            return;
        }
        TrieNode current = root;
        for (char ch : word.toCharArray()) {
            int idx = ch - 'a';
            if (idx < 0 || idx >= 26) {
                throw new IllegalArgumentException("Only lowercase a-z letters are allowed");
            }
            if (current.children[idx] == null) {
                current.children[idx] = new TrieNode(ch);
            }
            current = current.children[idx];
        }
        current.isEndOfWord = true;
    }

    /**
     * Checks whether a word exists in the trie.
     *
     * @param word the word to search for
     * @return true if the word is present, false otherwise
     */
    public boolean contains(String word) {
        if (word == null || word.isEmpty()) {
            return false;
        }
        TrieNode current = root;
        for (char ch : word.toCharArray()) {
            int idx = ch - 'a';
            if (idx < 0 || idx >= 26) {
                return false; // invalid character for this trie
            }
            if (current.children[idx] == null) {
                return false;
            }
            current = current.children[idx];
        }
        return current.isEndOfWord;
    }
}

