public class EnhancedTrie {

    /** Nested TrieNode class */
    private static class TrieNode {
        char value;                     // character stored in this node
        boolean isEndOfWord;            // true if this node terminates a word
        TrieNode[] children;            // sorted array of child nodes

        TrieNode(char value) {
            this.value = value;
            this.isEndOfWord = false;
            this.children = new TrieNode[0]; // initially empty
        }

        /** Insert a child node into the sorted children array */
        void addChild(TrieNode child) {
            this.children = insert(this.children, child);
        }

        /** Retrieve a child node with the given character, or null if absent */
        TrieNode getChild(char ch) {
            int left = 0, right = children.length - 1;
            while (left <= right) {
                int mid = (left + right) >>> 1;
                char midVal = children[mid].value;
                if (midVal < ch) {
                    left = mid + 1;
                } else if (midVal > ch) {
                    right = mid - 1;
                } else {
                    return children[mid];
                }
            }
            return null;
        }

        /**
         * Helper method to insert a new child node into a sorted array.
         * If a node with the same character already exists, it is replaced.
         *
         * @param array   the current sorted array of children
         * @param element the new child node to insert
         * @return a new array containing all children in sorted order
         */
        static TrieNode[] insert(TrieNode[] array, TrieNode element) {
            // Check if a node with the same character already exists
            for (int i = 0; i < array.length; i++) {
                if (array[i].value == element.value) {
                    array[i] = element; // replace existing node
