import java.io.IOException;
import java.nio.file.*;
import java.util.List;

public class FileHandler {

    /**
     * Handles file operations such as uploading files to a target directory.
     *
     * @param operationType the type of operation (currently only "upload" is supported)
     * @param files         the list of files to be processed
     * @param targetDir     the directory where files should be uploaded
     * @return a message indicating the result of the operation
     */
    public static String handleFileOperation(String operationType,
                                             List<Path> files,
                                             Path targetDir) {
        if (!"upload".equalsIgnoreCase(operationType)) {
            // Unsupported operation
            return null;
        }

        if (files == null || files.isEmpty() || targetDir == null) {
            return "No files to upload or target directory not specified.";
        }

        int uploadedCount = 0;
        try {
            // Create target directory if it does not exist
            if (!Files.exists(targetDir)) {
                Files.createDirectories(targetDir);
            }

            for (Path source : files) {
                if (Files.exists(source) && Files.isRegularFile(source)) {
                    Path destination = targetDir.resolve(source.getFileName());
                    Files.copy(source, destination, StandardCopyOption.REPLACE_EXISTING);
                    uploadedCount++;
                }
            }
        } catch (IOException e) {
            // In a real application you might want to log this exception
            return "Error during upload: " + e.getMessage();
        }

        return "Uploaded " + uploadedCount + " file" + (uploadedCount == 1 ? "" : "s");
    }
}

