public class FileHandler {

    /**
     * Handles file operations such as uploading and downloading files.
     *
     * @param operationType the type of operation ("upload" or "download")
     * @param files         the list of files to be processed (used only for upload)
     * @param targetDir     the directory where files should be uploaded or from which they should be downloaded
     * @param fileName      the name of the file to download (ignored for upload)
     * @return a String message for upload or a byte[] containing the file contents for download
     */
    public static Object handleFileOperation(String operationType,
                                             List<Path> files,
                                             Path targetDir,
                                             String fileName) {
        if ("upload".equalsIgnoreCase(operationType)) {
            return handleUpload(files, targetDir);
        } else if ("download".equalsIgnoreCase(operationType)) {
            return handleDownload(targetDir, fileName);
        } else {
            // Unsupported operation
            return null;
        }
    }

    private static String handleUpload(List<Path> files, Path targetDir) {
        if (files == null || files.isEmpty() || targetDir == null) {
            return "No files to upload or target directory not specified.";
        }

        int uploadedCount = 0;
        try {
            // Create target directory if it does not exist
            if (!Files.exists(targetDir)) {
                Files.createDirectories(targetDir);
            }

            for (Path source : files) {
                if (Files.exists(source) && Files.isRegularFile(source)) {
                    Path destination = targetDir.resolve(source.getFileName());
                    Files.copy(source, destination, StandardCopyOption.REPLACE_EXISTING);
                    uploadedCount++;
                }
            }
        } catch (IOException e) {
            return "Error during upload: " + e.getMessage();
        }

        return "Uploaded " + uploadedCount + " file" + (uploadedCount == 1 ? "" : "s");
    }

    private static byte[] handleDownload(Path targetDir, String fileName) {
        if (targetDir == null || fileName == null || fileName.isEmpty()) {
            throw new IllegalArgumentException("Target directory and file name must be provided for download.");
        }

        Path filePath = targetDir.resolve(fileName);
        try {
            return Files.readAllBytes(filePath);
        } catch (IOException e) {
            throw new RuntimeException("Error reading file: " + e.getMessage(), e);
        }
    }
}

