import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/**
 * Utility class for handling file operations such as upload, download, and zip.
 */
public class FileHandler {

    /**
     * Handles file operations.
     *
     * @param operationType the type of operation ("upload", "download", or "zip")
     * @param files         the list of files to be processed (used for upload and zip)
     * @param targetDir     the directory where files should be uploaded or from which they should be downloaded
     * @param fileName      the name of the file to download (ignored for upload and zip)
     * @return a String message for upload, a byte[] containing the file contents for download,
     *         or a byte[] containing the zip archive for zip.
     */
    public static Object handleFileOperation(String operationType,
                                             List<Path> files,
                                             Path targetDir,
                                             String fileName) {
        if ("upload".equalsIgnoreCase(operationType)) {
            return handleUpload(files, targetDir);
        } else if ("download".equalsIgnoreCase(operationType)) {
            return handleDownload(targetDir, fileName);
        } else if ("zip".equalsIgnoreCase(operationType)) {
            return handleZip(files);
        } else {
            // Unsupported operation
            return null;
        }
    }

    /* --------------------- Upload --------------------- */

    private static String handleUpload(List<Path> files, Path targetDir) {
        if (files == null || files.isEmpty() || targetDir == null) {
            return "No files to upload or target directory not specified.";
        }

        int uploadedCount = 0;
        try {
            // Create target directory if it does not exist
            if (!Files.exists(targetDir)) {
                Files.createDirectories(targetDir);
            }

            for (Path source : files) {
                if (Files.exists(source) && Files.isRegularFile(source)) {
                    Path destination = targetDir.resolve(source.getFileName());
                    Files.copy(source, destination, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
                    uploadedCount++;
                }
            }
        } catch (IOException e) {
            return "Error during upload: " + e.getMessage();
        }

        return "Uploaded " + uploadedCount + " file" + (uploadedCount == 1 ? "" : "s");
    }

    /* --------------------- Download --------------------- */

    private static byte[] handleDownload(Path targetDir, String fileName) {
        if (targetDir == null || fileName == null || fileName.isEmpty()) {
            throw new IllegalArgumentException("Target directory and file name must be provided for download.");
        }

        Path filePath = targetDir.resolve(fileName);
        try {
            return Files.readAllBytes(filePath);
        } catch (IOException e) {
            throw new RuntimeException("Error reading file: " + e.getMessage(), e);
        }
    }

    /* --------------------- Zip --------------------- */

    private static byte[] handleZip(List<Path> files) {
        if (files == null || files.isEmpty()) {
            throw new IllegalArgumentException("No files provided for zipping.");
        }

        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ZipOutputStream zos = new ZipOutputStream(baos)) {

            for (Path file : files) {
                if (Files.exists(file) && Files.isRegularFile(file)) {
                    ZipEntry entry = new ZipEntry(file.getFileName().toString());
                    zos.putNextEntry(entry);
                    Files.copy(file, zos);
                    zos.closeEntry();
                }
            }
            zos.finish();
            return baos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException("Error creating zip archive: " + e.getMessage(), e);
        }
    }
}

