import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;

/**
 * A minimal implementation of an enhanced WebSocket client.
 * It demonstrates asynchronous connection handling, message sending,
 * message handling, and graceful closure.
 */
public class EnhancedWebSocketClient {

    private final String uri;
    private WebSocketConnection connection;
    private Consumer<String> messageHandler;

    /**
     * Constructs a client for the specified WebSocket URI.
     *
     * @param uri the WebSocket endpoint to connect to
     */
    public EnhancedWebSocketClient(String uri) {
        this.uri = uri;
    }

    /**
     * Asynchronously connects to the WebSocket endpoint.
     *
     * @return a CompletableFuture that completes when the connection is established
     */
    public CompletableFuture<Void> connectAsync() {
        return WebSocketConnection.createAsync(uri)
                .thenAccept(conn -> {
                    this.connection = conn;
                    // If a message handler was set before connection, register it now
                    if (messageHandler != null) {
                        conn.setMessageHandler(messageHandler);
                    }
                });
    }

    /**
     * Sends a message over the WebSocket connection if it is open.
     *
     * @param message the message to send
     * @return a CompletableFuture that completes when the message has been sent
     */
    public CompletableFuture<Void> sendMessageAsync(String message) {
        if (connection != null && connection.isConnected()) {
            return connection.writeAsync(message);
        } else {
            return CompletableFuture.failedFuture(
                    new IllegalStateException("WebSocket is not connected."));
        }
    }

    /**
     * Registers a handler to process incoming messages.
     *
     * @param handler a Consumer that accepts incoming message strings
     */
    public void setMessageHandler(Consumer<String> handler) {
        this.messageHandler = handler;
        if (connection != null) {
            connection.setMessageHandler(handler);
        }
    }

    /**
     * Asynchronously closes the WebSocket connection.
     *
     * @return a CompletableFuture that completes when the connection is closed
     */
    public CompletableFuture<Void> closeAsync() {
        if (connection != null) {
            return connection.closeAsync();
        } else {
            return CompletableFuture.completedFuture(null);
        }
    }

    /**
     * Inner class representing a simplified WebSocket connection.
     */
    private static class WebSocketConnection {

        private final String uri;
        private boolean connected = true;
        private Consumer<String> messageHandler;

        private WebSocketConnection(String uri) {
            this.uri = uri;
        }

        /**
         * Creates a new WebSocketConnection asynchronously.
         *
         * @param uri the WebSocket endpoint
         * @return a CompletableFuture containing the new connection
         */
        public static CompletableFuture<WebSocketConnection> createAsync(String uri) {
            // In a real implementation, connection establishment would be asynchronous.
            // Here we simply return a completed future.
            return CompletableFuture.completedFuture(new WebSocketConnection(uri));
        }

        /**
         * Sends a message over the WebSocket connection.
         *
         * @param message the message to send
         * @return a CompletableFuture that completes when the message is sent
         */
        public CompletableFuture<Void> writeAsync(String message) {
            if (!connected) {
                return CompletableFuture.failedFuture(
                        new IllegalStateException("Connection is closed."));
            }
            // In a real implementation, the message would be transmitted over the network.
            // Here we simulate immediate success.
            return CompletableFuture.completedFuture(null);
        }

        /**
         * Registers a handler for incoming messages.
