import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;

/**
 * Thread‑safe alerting service.
 * <p>
 *   • Uses {@link ConcurrentHashMap} for all internal maps.  
 *   • Alert counts are stored as {@link AtomicInteger} to allow atomic increments.  
 *   • Listeners are registered with a composite key {@code listenerId|level}.  
 *   • All public methods are safe for concurrent use.
 * </p>
 */
public class AlertingService {

    /** Count of alerts per severity level. */
    private final ConcurrentHashMap<String, AtomicInteger> alertCounts = new ConcurrentHashMap<>();

    /** Most recent alert message per severity level. */
    private final ConcurrentHashMap<String, String> lastAlertMessages = new ConcurrentHashMap<>();

    /** Registered listeners. Key format: {@code listenerId|level}. */
    private final ConcurrentHashMap<String, Consumer<String>> listeners = new ConcurrentHashMap<>();

    /**
     * Triggers an alert for the given severity level.
     *
     * @param level   the severity level (e.g., "INFO", "WARN", "ERROR")
     * @param message the alert message
     */
    public void triggerAlert(String level, String message) {
        if (level == null || message == null) {
            throw new IllegalArgumentException("Level and message must not be null");
        }

        // Increment the count atomically
        alertCounts.computeIfAbsent(level, k -> new AtomicInteger(0)).incrementAndGet();

        // Store the most recent message
        lastAlertMessages.put(level, message);

        // Notify listeners registered for this level
        String levelKey = "|" + level;
        listeners.forEach((key, callback) -> {
            if (key.endsWith(levelKey)) {
                try {
                    callback.accept(message);
                } catch (Exception e) {
                    // Listener exceptions should not affect the service
                    System.err.println("Listener threw an exception: " + e.getMessage());
