class TLSExtensionProcessor {

    public Map<String, Object> processExtension(String extensionType,
                                                Map<String, Object> extensionData,
                                                Map<String, Object> context) {
        // Validate extension type
        if (extensionType == null || extensionType.trim().isEmpty()) {
            throw new IllegalArgumentException("Extension type cannot be null or empty");
        }

        // Prepare the result map
        Map<String, Object> result = new HashMap<>();
        result.put("extensionType", extensionType);
        result.put("originalData", extensionData);

        // Handle null extension data
        if (extensionData == null) {
            result.put("status", "error");
            result.put("message", "Extension data cannot be null");
            return result;
        }

        // Support for EARLY_DATA extension type
        if ("EARLY_DATA".equalsIgnoreCase(extensionType)) {
            // Validate maxEarlyDataSize if present
            Object maxSizeObj = extensionData.get("maxEarlyDataSize");
            if (maxSizeObj != null) {
                if (!(maxSizeObj instanceof Number)) {
                    result.put("status", "error");
                    result.put("message", "maxEarlyDataSize must be a non-negative integer");
                    return result;
                }
                long maxSize = ((Number) maxSizeObj).longValue();
                if (maxSize < 0) {
                    result.put("status", "error");
                    result.put("message", "maxEarlyDataSize must be a non-negative integer");
                    return result;
                }
                // Include validated value in result
                result.put("maxEarlyDataSize", maxSize);
            }

            // Validate connectionEnd (default to CLIENT)
            Object connEndObj = extensionData.get("connectionEnd");
            String connectionEnd = "CLIENT"; // default
            if (connEndObj != null) {
                if (!(connEndObj instanceof String)) {
                    result.put("status", "error");
                    result.put("message", "connectionEnd must be either CLIENT or SERVER");
                    return result;
                }
                String connEndStr = ((String) connEndObj).trim().toUpperCase();
                if ("CLIENT".equals(connEndStr) || "SERVER".equals(connEndStr)) {
                    connectionEnd = connEndStr;
                } else {
                    result.put("status", "error");
                    result.put("message", "connectionEnd must be either CLIENT or SERVER");
                    return result;
                }
            }
            // Include validated value in result
            result.put("connectionEnd", connectionEnd);

            // Success
            result.put("status", "success");
            return result;
        }

        // For all other extension types: unsupported
        result.put("status", "warning");
        result.put("message", "Unsupported extension type");
        return result;
    }
}

