            typeCounts.computeIfPresent(oldClass, (cls, count) -> {
                int newVal = count.decrementAndGet();
                return newVal <= 0 ? null : count;
            });
        }

        // Increment count for the new value's type, if not null
        if (value != null) {
            Class<?> newClass = value.getClass();
            typeCounts.computeIfAbsent(newClass, k -> new AtomicInteger(0)).incrementAndGet();
        }
