import java.util.UUID;

class UserManager {
    private Map<String, User> userDatabase;
    private Map<String, String> activeSessions; // username -> sessionId

    public UserManager() {
        this.userDatabase = new HashMap<>();
        this.activeSessions = new HashMap<>();
    }

    /**
     * Registers a new user.
     *
     * @param username Desired username (must be unique)
     * @param password User's password
     * @param email    User's email address
     * @return true if registration succeeded, false if username already exists
     */
    public boolean registerUser(String username, String password, String email) {
        if (userDatabase.containsKey(username)) {
            return false; // username already taken
        }
        User newUser = new User(username, password, email);
        userDatabase.put(username, newUser);
        return true;
    }

    /**
     * Logs in a user.
     *
     * @param username Username
     * @param password Password
     * @return session ID if login successful, null otherwise
     */
    public String loginUser(String username, String password) {
        User user = userDatabase.get(username);
        if (user == null) {
            return null; // user not found
        }
        if (!user.getPassword().equals(password)) {
            return null; // incorrect password
        }
        // Generate a new session ID
        String sessionId = UUID.randomUUID().toString();
        activeSessions.put(username, sessionId);
        return sessionId;
    }

    /**
     * Logs out a user.
     *
     * @param username Username to log out
     * @return true if logout succeeded, false if user was not logged in
     */
    public boolean logoutUser(String username) {
        if (activeSessions.containsKey(username)) {
            activeSessions.remove(username);
            return true;
        }
        return false; // user not logged in
    }

    /**
     * Checks if a user is currently logged in.
     *
     * @param username Username to check
     * @return true if user has an active session, false otherwise
     */
    public boolean isLoggedIn(String username) {
        return activeSessions.containsKey(username);
    }

    /**
     * Retrieves a user by username.
     *
     * @param username Username
     * @return User object or null if not found
     */
    public User getUser(String username) {
        return userDatabase.get(username);
    }
}

class User {
    private String username;
    private String password;
    private String email;

    public User(String username, String password, String email) {
        this.username = username;
        this.password = password;
        this.email = email;
    }

    // Getters (no setters to keep immutability)
    public String getUsername() {
        return username;
    }

    public String getPassword() {
        return password;
    }

    public String getEmail() {
        return email;
    }
}

