import java.util.HashMap;
import java.util.Map;
import java.util.UUID;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

class UserManager {
    private Map<String, User> userDatabase;          // username -> User
    private Map<String, String> activeSessions;     // username -> sessionToken

    public UserManager() {
        this.userDatabase = new HashMap<>();
        this.activeSessions = new HashMap<>();
    }

    /**
     * Registers a new user.
     *
     * @param username Desired username (must be unique)
     * @param password User's password (must be at least 8 characters)
     * @param email    User's email address
     * @return Map containing 'success' (Boolean) and 'message' (String)
     */
    public Map<String, Object> registerUser(String username, String password, String email) {
        Map<String, Object> result = new HashMap<>();

        // Validation: username uniqueness
        if (userDatabase.containsKey(username)) {
            result.put("success", false);
            result.put("message", "Username already taken.");
            return result;
        }

        // Validation: password length
        if (password == null || password.length() < 8) {
            result.put("success", false);
            result.put("message", "Password must be at least 8 characters long.");
            return result;
        }

        // Validation: email format
        if (!isValidEmail(email)) {
            result.put("success", false);
            result.put("message", "Invalid email format.");
            return result;
        }

        // Store user with hashed password
        int hashedPassword = password.hashCode();
        User newUser = new User(username, hashedPassword, email);
        userDatabase.put(username, newUser);

        result.put("success", true);
        result.put("message", "User registered successfully.");
        return result;
    }

    /**
     * Logs in a user.
     *
     * @param username Username
     * @param password Password
     * @return Map containing 'success', 'sessionToken', 'user' on success,
     *         or 'success' and 'message' on failure.
     */
    public Map<String, Object> loginUser(String username, String password) {
        Map<String, Object> response = new HashMap<>();

        User user = userDatabase.get(username);
        if (user == null) {
            response.put("success", false);
            response.put("message", "User not found.");
            return response;
        }

        if (user.getHashedPassword() != password.hashCode()) {
            response.put("success", false);
            response.put("message", "Incorrect password.");
            return response;
        }

        // Generate a new session token
        String sessionToken = UUID.randomUUID().toString();
        activeSessions.put(username, sessionToken);

        response.put("success", true);
        response.put("sessionToken", sessionToken);
        response.put("user", user);
        return response;
    }

    /**
     * Logs out a user by session token.
     *
     * @param sessionToken The session token to invalidate
     * @return Map containing 'success' and 'message'
     */
    public Map<String, Object> logoutUser(String sessionToken) {
        Map<String, Object> response = new HashMap<>();

        String usernameToRemove = null;
        for (Map.Entry<String, String> entry : activeSessions.entrySet()) {
            if (entry.getValue().equals(sessionToken)) {
                usernameToRemove = entry.getKey();
                break;
            }
        }

        if (usernameToRemove != null) {
            activeSessions.remove(usernameToRemove);
            response.put("success", true);
            response.put("message", "Logout successful.");
        } else {
            response.put("success", false);
            response.put("message", "Invalid session token.");
        }

        return response;
    }

    /**
     * Checks if a user is currently logged in.
     *
     * @param username Username to check
     * @return true if user has an active session, false otherwise
     */
    public boolean isLoggedIn(String username) {
        return activeSessions.containsKey(username);
    }

    /**
     * Retrieves a user by username.
     *
     * @param username Username
     * @return User object or null if not found
     */
    public User getUser(String username) {
        return userDatabase.get(username);
    }

    /**
     * Validates an email address against a regex pattern.
     *
     * @param email Email string to validate
     * @return true if email matches the pattern, false otherwise
     */
    private boolean isValidEmail(String email) {
        String regex = "^[a-zA-Z0-9_+&*-]+(?:\\.[a-zA-Z0-9_+&*-]+)*@(?:[a-zA-Z0-9-]+\\.)+[a-zA-Z]{2,7}$";
        Pattern pattern = Pattern.compile(regex);
        Matcher matcher = pattern.matcher(email);
        return matcher.matches();
    }
}

class User {
    private String username;
    private int hashedPassword;
    private String email;

    public User(String username, int hashedPassword, String email) {
        this.username = username;
        this.hashedPassword = hashedPassword;
        this.email = email;
    }

    // Getters (no setters to keep immutability)
    public String getUsername() {
        return username;
    }

    public int getHashedPassword() {
        return hashedPassword;
    }

    public String getEmail() {
        return email;
    }
}

