public class AdvancedTileCalculator {

    /**
     * Calculates the tile configuration based on the presence of neighboring tiles,
     * including diagonal neighbors.
     *
     * @param up       true if there is a tile above
     * @param down     true if there is a tile below
     * @param left     true if there is a tile to the left
     * @param right    true if there is a tile to the right
     * @param upLeft   true if there is a tile diagonally up‑left
     * @param upRight  true if there is a tile diagonally up‑right
     * @param downLeft true if there is a tile diagonally down‑left
     * @param downRight true if there is a tile diagonally down‑right
     * @return a TileConfiguration instance with the appropriate coordinates
     */
    public TileConfiguration calculateAdvancedTile(
            boolean up, boolean down, boolean left, boolean right,
            boolean upLeft, boolean upRight, boolean downLeft, boolean downRight) {

        int neighborCount = (up ? 1 : 0) + (down ? 1 : 0) + (left ? 1 : 0) + (right ? 1 : 0)
                + (upLeft ? 1 : 0) + (upRight ? 1 : 0) + (downLeft ? 1 : 0) + (downRight ? 1 : 0);

        // No neighbors
        if (neighborCount == 0) {
            return new TileConfiguration(0, 0);
        }

        /* Corner cases with diagonal dependencies – must match exactly the three
           required neighbors and no others. */
        if (up && left && upLeft && !down && !right && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(3, 0);
        }
        if (up && right && upRight && !down && !left && !upLeft && !downLeft && !downRight) {
            return new TileConfiguration(2, 0);
        }
        if (down && left && downLeft && !up && !right && !upLeft && !upRight && !downRight) {
            return new TileConfiguration(3, 1);
        }
        if (down && right && downRight && !up && !left && !upLeft && !upRight && !downLeft) {
            return new TileConfiguration(2, 1);
        }

        /* Dead ends – exactly one orthogonal neighbor */
        if (neighborCount == 1) {
            if (up)   return new TileConfiguration(1, 0);
            if (down) return new TileConfiguration(0, 2);
            if (left) return new TileConfiguration(5, 1);
            if (right)return new TileConfiguration(5, 0);
            /* Diagonal-only dead ends are not specified; they fall through to default. */
        }

        /* Exactly two opposing orthogonal neighbors – vertical or horizontal passage */
        if (neighborCount == 2) {
            if (up && down && !left && !right && !upLeft && !upRight && !downLeft && !downRight) {
                return new TileConfiguration(5, 2);
            }
            if (left && right && !up && !down && !upLeft && !upRight && !downLeft && !downRight) {
                return new TileConfiguration(1, 2);
            }
        }

        /* All other configurations */
        return new TileConfiguration(1, 1);
    }

    /**
     * Nested class representing a tile configuration with x and y coordinates.
     */
    public static class TileConfiguration {
        private final int x;
        private final int y;

        public TileConfiguration(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() {
            return x;
        }

        public int getY() {
            return y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    /* Optional main method for quick demonstration */
    public static void main(String[] args) {
        AdvancedTileCalculator calculator = new AdvancedTileCalculator();

        // No neighbors
        System.out.println("Isolated: " + calculator.calculateAdvancedTile(false, false, false, false,
                false, false, false, false)); // (0, 0)

        // Vertical passage
        System.out.println("Vertical: " + calculator.calculateAdvancedTile(true, true, false, false,
                false, false, false, false)); // (5, 2)

        // Horizontal passage
        System.out.println("Horizontal: " + calculator.calculateAdvancedTile(false, false, true, true,
                false, false, false, false)); // (1, 2)

        // Dead ends
        System.out.println("Dead end UP: " + calculator.calculateAdvancedTile(true, false, false, false,
                false, false, false, false)); // (1, 0)
        System.out.println("Dead end DOWN: " + calculator.calculateAdvancedTile(false, true, false, false,
                false, false, false, false)); // (0, 2)
        System.out.println("Dead end LEFT: " + calculator.calculateAdvancedTile(false, false, true, false,
                false, false, false, false)); // (5, 1)
        System.out.println("Dead end RIGHT: " + calculator.calculateAdvancedTile(false, false, false, true,
                false, false, false, false)); // (5, 0)

        // Corner cases with diagonal dependencies
        System.out.println("Corner UP+LEFT+UP_LEFT: " + calculator.calculateAdvancedTile(true, false, true, false,
                true, false, false, false)); // (3, 0)
        System.out.println("Corner UP+RIGHT+UP_RIGHT: " + calculator.calculateAdvancedTile(true, false, false, true,
                false, true, false, false)); // (2, 0)
        System.out.println("Corner DOWN+LEFT+DOWN_LEFT: " + calculator.calculateAdvancedTile(false, true, true, false,
                false, false, true, false)); // (3, 1)
        System.out.println("Corner DOWN+RIGHT+DOWN_RIGHT: " + calculator.calculateAdvancedTile(false, true, false, true,
                false, false, false, true)); // (2, 1)

        // Mixed neighbors (not matching any special case)
        System.out.println("Mixed: " + calculator.calculateAdvancedTile(true, false, true, false,
                false, false, false, false)); // (1, 1)
    }
}

