public class AdvancedTileCalculator {

    /**
     * Calculates the tile configuration based on the presence of neighboring tiles,
     * including diagonal neighbors.
     *
     * @param up       true if there is a tile above
     * @param down     true if there is a tile below
     * @param left     true if there is a tile to the left
     * @param right    true if there is a tile to the right
     * @param upLeft   true if there is a tile diagonally up‑left
     * @param upRight  true if there is a tile diagonally up‑right
     * @param downLeft true if there is a tile diagonally down‑left
     * @param downRight true if there is a tile diagonally down‑right
     * @return a TileConfiguration instance with the appropriate coordinates
     */
    public TileConfiguration calculateAdvancedTile(
            boolean up, boolean down, boolean left, boolean right,
            boolean upLeft, boolean upRight, boolean downLeft, boolean downRight) {

        int orthCount = (up ? 1 : 0) + (down ? 1 : 0) + (left ? 1 : 0) + (right ? 1 : 0);
        int diagCount = (upLeft ? 1 : 0) + (upRight ? 1 : 0) + (downLeft ? 1 : 0) + (downRight ? 1 : 0);
        int totalCount = orthCount + diagCount;

        /* 1. No neighbors */
        if (totalCount == 0) {
            return new TileConfiguration(0, 0);
        }

        /* 2. Fully surrounded tile (all 8 neighbors) */
        if (orthCount == 4 && diagCount == 4) {
            return new TileConfiguration(4, 2);
        }

        /* 3. Full cross (all 4 orthogonal neighbors) */
        if (orthCount == 4) {
            // If all diagonals are present, treat as fully surrounded
            if (diagCount == 4) {
                return new TileConfiguration(4, 2);
            } else {
                return new TileConfiguration(6, 0);
            }
        }

        /* 4. T‑junctions (exactly three orthogonal neighbors) */
        if (orthCount == 3) {
            // Missing one orthogonal neighbor
            if (!up && down && left && right) return new TileConfiguration(2, 2);
            if (up && !down && left && right) return new TileConfiguration(2, 2);
            if (up && down && !left && right) return new TileConfiguration(2, 2);
            if (up && down && left && !right) return new TileConfiguration(2, 2);
            // Any other combination with 3 orthogonal neighbors is still a T‑junction
            return new TileConfiguration(2, 2);
        }

        /* 5. Corner cases with diagonal dependencies */
        if (up && left && upLeft && !down && !right && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(3, 0);
        }
        if (up && right && upRight && !down && !left && !upLeft && !downLeft && !downRight) {
            return new TileConfiguration(2, 0);
        }
        if (down && left && downLeft && !up && !right && !upLeft && !upRight && !downRight) {
            return new TileConfiguration(3, 1);
        }
        if (down && right && downRight && !up && !left && !upLeft && !upRight && !downLeft) {
            return new TileConfiguration(2, 1);
        }

        /* 6. Dead ends (exactly one orthogonal neighbor) */
        if (orthCount == 1) {
            if (up)   return new TileConfiguration(1, 0);
            if (down) return new TileConfiguration(0, 2);
            if (left) return new TileConfiguration(5, 1);
            if (right)return new TileConfiguration(5, 0);
        }

        /* 7. Exactly two opposing orthogonal neighbors (vertical or horizontal passage) */
        if (orthCount == 2) {
            if (up && down && !left && !right && diagCount == 0) {
                return new TileConfiguration(5, 2);
            }
            if (left && right && !up && !down && diagCount == 0) {
                return new TileConfiguration(1, 2);
            }
        }

