import java.util.*;

public class ScenarioAnalyzer {

    /** Simple tree node with optional sync flag and server name. */
    public static class Node {
        String name;
        boolean isSync;
        String serverName;
        List<Node> children = new ArrayList<>();

        public Node(String name) {
            this(name, false, null);
        }

        public Node(String name, boolean isSync, String serverName) {
            this.name = name;
            this.isSync = isSync;
            this.serverName = serverName;
        }

        public void addChild(Node child) {
            children.add(child);
        }
    }

    /**
     * Analyzes the scenario tree.
     *
     * @param root the root node of the tree
     * @return a map containing:
     *   - "nodeIndices": Map<String,Integer> mapping node names to breadth‑first indices
     *   - "syncPairs":   Map<Integer,Integer> mapping request node index to response node index
     */
    public static Map<String, Object> analyzeScenario(Node root) {
        Map<String, Integer> nodeIndices = new HashMap<>();
        Map<Node, String> parentServerName = new HashMap<>();
        List<Node> nodesByIndex = new ArrayList<>();

        // Breadth‑first traversal to assign indices and record parent server names
        Queue<Node> queue = new LinkedList<>();
        if (root != null) {
            queue.add(root);
            parentServerName.put(root, null); // root has no parent
        }

        int idx = 0;
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            nodeIndices.put(current.name, idx);
            nodesByIndex.add(current);
            idx++;

            for (Node child : current.children) {
                queue.add(child);
                parentServerName.put(child, current.serverName);
            }
        }

        // Detect synchronous request‑response pairs
        Map<Integer, Integer> syncPairs = new HashMap<>();
        for (Node node : nodesByIndex) {
            if (!node.isSync) continue;

            String parentSrv = parentServerName.get(node);
            if (parentSrv == null) continue; // no parent to match against

            int requestIdx = nodeIndices.get(node.name);
            for (Node child : node.children) {
                if (child.serverName != null && child.serverName.equals(parentSrv)) {
                    int responseIdx = nodeIndices.get(child.name);
                    syncPairs.put(requestIdx, responseIdx);
                }
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("nodeIndices", nodeIndices);
        result.put("syncPairs", syncPairs);
        return result;
    }

    // Example usage
    public static void main(String[] args) {
        Node root = new Node("root", false, "srvRoot");

        Node req1 = new Node("Req1", true, "srvA");
        Node resp1 = new Node("Resp1", false, "srvRoot"); // matches parent of Req1

        Node req2 = new Node("Req2", true, "srvB");
        Node resp2 = new Node("Resp2", false, "srvX"); // does not match

        root.addChild(req1);
        root.addChild(req2);
        req1.addChild(resp1);
        req2.addChild(resp2);

        Map<String, Object> analysis = analyzeScenario(root);
        System.out.println("Node Indices: " + analysis.get("nodeIndices"));
        System.out.println("Sync Pairs: " + analysis.get("syncPairs"));
    }
}

