import java.util.*;

public class EnhancedTariffManager {
    private final Map<Integer, Tariff> tariffs = new HashMap<>();
    private final Map<Integer, List<Contract>> tariffContracts = new HashMap<>();

    /** Adds a new tariff to the system. */
    public void addTariff(Tariff tariff) {
        if (tariff == null) throw new IllegalArgumentException("Tariff cannot be null");
        tariffs.put(tariff.getId(), tariff);
        tariffContracts.putIfAbsent(tariff.getId(), new ArrayList<>());
    }

    /** Subscribes a contract to an existing tariff. */
    public void subscribeContractToTariff(int tariffId, Contract contract) {
        if (!tariffs.containsKey(tariffId))
            throw new IllegalArgumentException("Tariff with ID " + tariffId + " does not exist");
        if (contract == null) throw new IllegalArgumentException("Contract cannot be null");
        tariffContracts.get(tariffId).add(contract);
    }

    /** Retrieves a tariff by its ID. */
    public Tariff getTariff(int id) {
        return tariffs.get(id);
    }

    /** Retrieves all contracts subscribed to a specific tariff. */
    public List<Contract> getContractsForTariff(int tariffId) {
        return tariffContracts.getOrDefault(tariffId, Collections.emptyList());
    }

    /** Simple demonstration of usage. */
    public static void main(String[] args) {
        EnhancedTariffManager manager = new EnhancedTariffManager();

        Tariff basic = new Tariff(1, "Basic Plan", 29.99);
        Tariff premium = new Tariff(2, "Premium Plan", 59.99);

        manager.addTariff(basic);
        manager.addTariff(premium);

        Contract alice = new Contract(101, "Alice Smith");
        Contract bob = new Contract(102, "Bob Johnson");

        manager.subscribeContractToTariff(1, alice);
        manager.subscribeContractToTariff(2, bob);
        manager.subscribeContractToTariff(2, alice); // Alice also subscribes to Premium

        System.out.println("Tariff 1: " + manager.getTariff(1));
        System.out.println("Contracts for Tariff 1: " + manager.getContractsForTariff(1));

        System.out.println("Tariff 2: " + manager.getTariff(2));
        System.out.println("Contracts for Tariff 2: " + manager.getContractsForTariff(2));
    }
}

