import java.util.*;

/**
 * A simple factory simulation that supports four different factory versions.
 * Each version has a different number of workshops arranged in series.
 *
 * Usage:
 *   java FactorySimulation [version] [totalItems] [itemsToProcess]
 *
 *   - version: 1 to 4 (default 1)
 *   - totalItems: number of items initially in the input stock (default 10)
 *   - itemsToProcess: number of items the factory should process (default 6)
 */
public class FactorySimulation {

    /** Represents a workshop that moves items from its input queue to its output queue. */
    private static class Workshop {
        final String name;
        final Queue<Integer> inputQueue;
        final Queue<Integer> outputQueue;

        Workshop(String name, Queue<Integer> inputQueue, Queue<Integer> outputQueue) {
            this.name = name;
            this.inputQueue = inputQueue;
            this.outputQueue = outputQueue;
        }

        /** Process one item if available. */
        void processOne() {
            Integer item = inputQueue.poll();
            if (item != null) {
                outputQueue.offer(item);
                System.out.printf("  %s processed item %d%n", name, item);
            }
        }
    }

    /** Factory configuration based on version. */
    private static class Factory {
        final int version;
        final List<Workshop> workshops = new ArrayList<>();
        final Queue<Integer> inputStock = new LinkedList<>();
        final Queue<Integer> outputStock = new LinkedList<>();

        Factory(int version, int totalItems) {
            this.version = version;
            // Initialize input stock
            for (int i = 1; i <= totalItems; i++) {
                inputStock.offer(i);
            }
            // Create workshops according to version
            Queue<Integer> prevQueue = inputStock;
            for (int i = 1; i <= version; i++) {
                Queue<Integer> nextQueue = new LinkedList<>();
                workshops.add(new Workshop("Workshop-" + i, prevQueue, nextQueue));
                prevQueue = nextQueue;
            }
            // The last workshop's output queue is the factory's output stock
            outputStock = prevQueue;
        }

        /** Simulate processing until the desired number of items is processed or no more items. */
        int simulate(int itemsToProcess) {
            int processedCount = 0;
            while (processedCount < itemsToProcess && !inputStock.isEmpty()) {
                System.out.printf("=== Step %d ===%n", processedCount + 1);
                // Process each workshop in order
                for (Workshop w : workshops) {
                    w.processOne();
                }
                // Count items that have reached the output stock
                processedCount = outputStock.size();
                System.out.printf("Processed so far: %d%n", processedCount);
                System.out.printf("Remaining in input stock: %d%n", inputStock.size());
                System.out.println();
            }
            return processedCount;
        }

        /** Display final state of the factory. */
        void displayResult(int processedCount) {
            System.out.println("=== Final State ===");
            System.out.printf("Factory version: %d%n", version);
            System.out.printf("Total items processed: %d%n", processedCount);
            System.out.printf("Remaining items in input stock: %d%n", inputStock.size());
            System.out.printf("Output stock contents: %s%n", outputStock);
        }
    }

    public static void main(String[] args) {
        int version = 1;
        int totalItems = 10;
        int itemsToProcess = 6;

        // Parse command line arguments if provided
        try {
            if (args.length > 0) version = Integer.parseInt(args[0]);
            if (args.length > 1) totalItems = Integer.parseInt(args[1]);
            if (args.length > 2) itemsToProcess = Integer.parseInt(args[2]);
        } catch (NumberFormatException e) {
            System.err.println("Invalid arguments. Using default values.");
        }

        if (version < 1 || version > 4) {
            System.err.println("Version must be between 1 and 4. Using default version 1.");
            version = 1;
        }

        Factory factory = new Factory(version, totalItems);
        int processedCount = factory.simulate(itemsToProcess);
        factory.displayResult(processedCount);
    }
}

