import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Factory simulation with performance tracking.
 *
 * <p>Features:
 * <ul>
 *   <li>Thread‑safe stock operations.</li>
 *   <li>Each workshop runs in its own thread.</li>
 *   <li>Tracks total execution time, processed items, errors, and final stock levels.</li>
 * </ul>
 *
 * <p>Usage:
 *   java FactorySimulation [version] [totalItems] [itemsToProcess]
 *
 *   - version: 1 to 4 (default 1)
 *   - totalItems: number of items initially in the input stock (default 10)
 *   - itemsToProcess: number of items the factory should process (default 6)
 */
public class FactorySimulation {

    /* ---------- Thread‑safe stock ---------- */
    static class Stock {
        private final Queue<Integer> queue = new LinkedList<>();

        public synchronized void add(Integer item) {
            queue.offer(item);
        }

        public synchronized Integer poll() {
            return queue.poll();
        }

        public synchronized int size() {
            return queue.size();
        }

        public synchronized boolean isEmpty() {
            return queue.isEmpty();
        }

        @Override
        public synchronized String toString() {
            return queue.toString();
        }
    }

    /* ---------- Counter to limit processed items ---------- */
    static class Counter {
        private int count = 0;
        private final int target;

        public Counter(int target) {
            this.target = target;
        }

        public synchronized boolean incrementIfBelowTarget() {
            if (count >= target) {
                return false;
            }
            count++;
            return true;
        }

        public synchronized int getCount() {
            return count;
        }
    }

    /* ---------- Workshop thread ---------- */
    static class Workshop extends Thread {
        private final String name;
        private final Stock input;
        private final Stock output;
        private final Counter counter;
        private final AtomicInteger errorCounter;

        public Workshop(String name, Stock input, Stock output, Counter counter, AtomicInteger errorCounter) {
            this.name = name;
            this.input = input;
            this.output = output;
            this.counter = counter;
            this.errorCounter = errorCounter;
        }

        @Override
        public void run() {
            try {
                while (true) {
                    Integer item = input.poll();
                    if (item == null) {
                        break; // no more items in this workshop's input
                    }
                    boolean ok = counter.incrementIfBelowTarget();
                    if (!ok) {
                        // target reached, stop processing
                        break;
                    }
                    // Simulate a possible error (e.g., item divisible by 13)
                    if (item % 13 == 0) {
                        throw new RuntimeException("Simulated processing error for item " + item);
                    }
                    output.add(item);
                    System.out.printf("%s processed item %d%n", name, item);
                }
            } catch (Exception e) {
                System.err.printf("%s encountered an error: %s%n", name, e.getMessage());
                errorCounter.incrementAndGet();
            } finally {
                System.out.printf("%s finished%n", name);
            }
        }
    }

    /* ---------- Factory configuration ---------- */
    static class Factory {
        private final int version;
        private final Stock inputStock = new Stock();
        private Stock outputStock;
        private final List<Stock> intermediateStocks = new ArrayList<>();
        private final List<Workshop> workshops = new ArrayList<>();
        private final Counter counter;
        private final AtomicInteger errorCounter = new AtomicInteger(0);

        public Factory(int version, int totalItems, int itemsToProcess) {
            this.version = version;
            this.counter = new Counter(itemsToProcess);

            // Initialize input stock
            for (int i = 1; i <= totalItems; i++) {
                inputStock.add(i);
            }

            // Create workshops in series
            Stock prev = inputStock;
            for (int i = 1; i <= version; i++) {
                Stock next = new Stock();
                intermediateStocks.add(next);
                Workshop w = new Workshop("Workshop-" + i, prev, next, counter, errorCounter);
                workshops.add(w);
                prev = next;
            }
            // The last workshop's output is the factory's output stock
            outputStock = prev;
        }

        public void runSimulation() {
            long startTime = System.nanoTime();

            // Start all workshop threads
            for (Workshop w : workshops) {
                w.start();
            }
            // Wait for all to finish
            for (Workshop w : workshops) {
                try {
                    w.join();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }

            long endTime = System.nanoTime();
            long durationNs = endTime - startTime;
            double durationMs = durationNs / 1_000_000.0;

            // Display performance metrics
            System.out.println("\n=== Performance Metrics ===");
            System.out.printf("Total execution time: %.2f ms%n", durationMs);
            System.out.printf("Total items processed: %d%n", counter.getCount());
            System.out.printf("Total errors encountered: %d%n", errorCounter.get());
            System.out.printf("Final input stock level: %d%n", inputStock.size());
            for (int i = 0; i < intermediateStocks.size(); i++) {
                System.out.printf("Intermediate stock %d level: %d%n", i + 1, intermediateStocks.get(i).size());
            }
            System.out.printf("Final output stock level: %d%n", outputStock.size());
        }
    }

    /* ---------- Main ---------- */
    public static void main(String[] args) {
        int version = 1;
        int totalItems = 10;
        int itemsToProcess = 6;

        // Parse command line arguments if provided
        try {
            if (args.length > 0) version = Integer.parseInt(args[0]);
            if (args.length > 1) totalItems = Integer.parseInt(args[1]);
            if (args.length > 2) itemsToProcess = Integer.parseInt(args[2]);
        } catch (NumberFormatException e) {
            System.err.println("Invalid arguments. Using default values.");
        }

        if (version < 1 || version > 4) {
            System.err.println("Version must be between 1 and 4. Using default version 1.");
            version = 1;
        }

        Factory factory = new Factory(version, totalItems, itemsToProcess);
        factory.runSimulation();
    }
}

