public class GameOfLifePatterns {

    /* Creates a square boolean grid of the specified size */
    public static boolean[][] createGrid(int size) {
        return new boolean[size][size];
    }

    /* Counts the number of live (true) cells in the grid */
    public static int countLiveCells(boolean[][] grid) {
        int count = 0;
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j]) {
                    count++;
                }
            }
        }
        return count;
    }

    /* Applies a pattern to the grid at the given offset */
    public static void applyPattern(boolean[][] grid, String patternName,
                                    int xOffset, int yOffset) {
        // Validate grid
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            throw new IllegalArgumentException("Grid must not be null or empty");
        }

        // Validate pattern name
        if (!"glider".equalsIgnoreCase(patternName)) {
            throw new IllegalArgumentException("Unsupported pattern: " + patternName);
        }

        // Validate offsets (must be non‑negative and within grid bounds)
        if (xOffset < 0 || yOffset < 0 || xOffset >= grid.length || yOffset >= grid[0].length) {
            throw new IllegalArgumentException("Invalid offsets: (" + xOffset + ", " + yOffset + ")");
        }

        // Glider relative coordinates
        Coordinate[] glider = {
            new Coordinate(0, 0),
            new Coordinate(1, 0),
            new Coordinate(2, 0),
            new Coordinate(2, 1),
            new Coordinate(1, 2)
        };

        // Apply the pattern, setting only cells that are within bounds
        for (Coordinate c : glider) {
            int x = xOffset + c.x;
            int y = yOffset + c.y;
            if (x >= 0 && x < grid.length && y >= 0 && y < grid[0].length) {
                grid[x][y] = true;
            }
        }
    }

    /* Private static nested class representing a coordinate */
    private static class Coordinate {
        public int x;
        public int y;

        public Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

