import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;

/**
 * Utility class providing enhanced test utilities.
 */
public final class EnhancedTestUtils {

    private EnhancedTestUtils() {
        // Prevent instantiation
    }

    /**
     * Creates a list containing {@code count} elements generated by the supplied {@link Supplier}.
     * An optional {@link Consumer} validator can be applied to each element, and an optional
     * {@link Function} transformer can be applied before adding the element to the result list.
     * Any {@link RuntimeException} thrown by the validator is wrapped in a new {@link RuntimeException}.
     *
     * @param count      the number of elements to generate; must be non‑negative
     * @param supplier   the supplier used to generate each element; must not be {@code null}
     * @param validator  an optional validator applied to each element; may be {@code null}
     * @param transformer an optional transformer applied to each element before adding to the result list; may be {@code null}
     * @param <T>        the type of elements produced by the supplier
     * @param <R>        the type of elements returned in the resulting list
     * @return a {@link List} containing {@code count} elements produced by {@code supplier}
     * @throws IllegalArgumentException if {@code count} is negative or {@code supplier} is {@code null}
     */
    public static <T, R> List<R> createEnhancedList(
            int count,
            Supplier<T> supplier,
            Consumer<T> validator,
            Function<T, R> transformer) {

        if (count < 0) {
            throw new IllegalArgumentException("Count must be non-negative");
        }
        if (supplier == null) {
            throw new IllegalArgumentException("Supplier must not be null");
        }

        List<R> result = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            T element = supplier.get();

            if (validator != null) {
                try {
                    validator.accept(element);
                } catch (RuntimeException e) {
                    throw new RuntimeException("Validator threw an exception", e);
                }
            }

            R transformed;
            if (transformer != null) {
                transformed = transformer.apply(element);
            } else {
                @SuppressWarnings("unchecked")
                R casted = (R) element;
                transformed = casted;
            }

            result.add(transformed);
        }
        return result;
    }
}

