import java.util.*;

/**
 * A simple deterministic finite automaton (DFA) implementation.
 *
 * <p>Usage example (in the main method):
 * <pre>
 *     DFA dfa = new DFA();
 *     State s0 = new State("q0");
 *     State s1 = new State("q1");
 *     dfa.addState(s0);          // first added state becomes the initial state
 *     dfa.addState(s1);
 *     dfa.setFinal(s1);          // q1 is an accepting state
 *
 *     // Define transitions for alphabet {a, b}
 *     dfa.addTransition(s0, 'a', s1);
 *     dfa.addTransition(s0, 'b', s0);
 *     dfa.addTransition(s1, 'a', s1);
 *     dfa.addTransition(s1, 'b', s0);
 *
 *     System.out.println(dfa.accepts("a"));   // true
 *     System.out.println(dfa.accepts("b"));   // false
 *     System.out.println(dfa.accepts("ba"));  // true
 * </pre>
 */
public class DFA {

    /** Represents a state in the DFA. */
    public static class State {
        private final String name;
        private final Map<Character, State> transitions = new HashMap<>();
        private boolean isFinal = false;

        public State(String name) {
            this.name = Objects.requireNonNull(name, "State name cannot be null");
        }

        /** Adds a transition for a given input symbol. */
        public void addTransition(char symbol, State target) {
            transitions.put(symbol, Objects.requireNonNull(target, "Target state cannot be null"));
        }

        /** Retrieves the next state for a given input symbol. */
        public State getTransition(char symbol) {
