 * <p>The DFA automatically builds its alphabet from all symbols used in transitions.
 * When a transition is added via {@link #addTransition(State, char, State)},
 * the symbol is added to the DFA's alphabet set.
 *
 * <p>Both {@link State} and {@link DFA} provide {@code toString()} methods that
 * describe the automaton in a human‑readable form.
 */
public class DFA {

    /** Represents a state in the DFA. */
    public static class State {
        private final String name;
        private final Map<Character, State> transitions = new LinkedHashMap<>();
        private boolean isFinal = false;

        public State(String name) {
            this.name = Objects.requireNonNull(name, "State name cannot be null");
        }

        /** Adds a transition for a given input symbol. */
        public void addTransition(char symbol, State target) {
            transitions.put(symbol, Objects.requireNonNull(target, "Target state cannot be null"));
        }

        /** Retrieves the next state for a given input symbol. */
        public State getTransition(char symbol) {
            return transitions.get(symbol);
        }

        /** Marks this state as an accepting (final) state. */
        public void setFinal(boolean isFinal) {
            this.isFinal = isFinal;
        }

        /** Returns true if this state is accepting. */
        public boolean isFinal() {
            return isFinal;
        }

        /** Returns the name of the state. */
        public String getName() {
            return name;
        }

        /** Human‑readable representation of the state and its transitions. */
        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            sb.append(name).append(":");
            for (Map.Entry<Character, State> e : transitions.entrySet()) {
                sb.append(" --").append(e.getKey()).append("-> ").append(e.getValue().name);
            }
            return sb.toString();
        }
    }

    private final List<State> states = new ArrayList<>();
    private State initialState = null;
    private final Set<Character> alphabet = new LinkedHashSet<>();

    /** Adds a state to the DFA. The first added state becomes the initial state. */
    public void addState(State state) {
        Objects.requireNonNull(state, "State cannot be null");
        states.add(state);
        if (initialState == null) {
            initialState = state;
        }
    }

    /** Marks a state as accepting. */
    public void setFinal(State state) {
        Objects.requireNonNull(state, "State cannot be null");
        state.setFinal(true);
    }

    /** Adds a transition from one state to another on a given input symbol. */
    public void addTransition(State from, char symbol, State to) {
        Objects.requireNonNull(from, "From state cannot be null");
        Objects.requireNonNull(to, "To state cannot be null");
        from.addTransition(symbol, to);
        alphabet.add(symbol); // automatically build alphabet
    }

    /** Returns the alphabet of the DFA (all symbols used in transitions). */
    public Set<Character> getAlphabet() {
        return Collections.unmodifiableSet(alphabet);
    }

    /**
     * Simulates the DFA on the given input string.
     * Returns {@code true} if the string is accepted, {@code false} otherwise.
     * The method returns {@code false} immediately if a transition for a symbol
     * does not exist.
     */
    public boolean accepts(String input) {
        if (initialState == null) {
            throw new IllegalStateException("DFA has no initial state.");
        }
        State current = initialState;
        for (char c : input.toCharArray()) {
            State next = current.getTransition(c);
            if (next == null) {
                return false; // No valid transition – reject immediately
            }
            current = next;
        }
        return current.isFinal();
    }

    /** Human‑readable representation of the DFA. */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("DFA Summary:\n");
        sb.append("  Number of states: ").append(states.size()).append("\n");
        sb.append("  Alphabet: ").append(alphabet).append("\n");
        sb.append("  Initial state: ").append(initialState != null ? initialState.getName() : "none").append("\n");
        sb.append("  Final states: ");
        List<String> finals = new ArrayList<>();
        for (State s : states) {
            if (s.isFinal()) finals.add(s.getName());
        }
        sb.append(finals).append("\n");
        sb.append("  Transitions:\n");
        for (State s : states) {
            sb.append("    ").append(s.toString()).append("\n");
        }
        return sb.toString();
    }

    /** Simple demonstration of the DFA. */
    public static void main(String[] args) {
        DFA dfa = new DFA();

        // Create states
        State q0 = new State("q0");
        State q1 = new State("q1");
        State q2 = new State("q2");

        // Add states to DFA
        dfa.addState(q0); // initial state
        dfa.addState(q1);
        dfa.addState(q2);

        // Define accepting state
        dfa.setFinal(q2);

        // Define transitions for alphabet {0, 1}
        dfa.addTransition(q0, '0', q1);
        dfa.addTransition(q0, '1', q0);
        dfa.addTransition(q1, '0', q2);
        dfa.addTransition(q1, '1', q1);
        dfa.addTransition(q2, '0', q2);
        dfa.addTransition(q2, '1', q2);

        // Test strings
        String[] testStrings = {"0", "1", "00", "01", "10", "110", "0011"};
        for (String s : testStrings) {
            System.out.printf("Input \"%s\" accepted? %b%n", s, dfa.accepts(s));
        }

        // Display DFA summary
        System.out.println("\n" + dfa);
    }
}

