import java.util.Map;
import java.util.HashMap;
import java.util.regex.Pattern;

public class ServerApprovalHandler {
    private String serverName;
    private String serverIp;
    private int realmId;
    private int imageId;
    private int hardwareProfileId;
    private Map<String, Boolean> approvalStatus;

    public ServerApprovalHandler(String serverName, String serverIp,
                                 int realmId, int imageId, int hardwareProfileId) {
        this.serverName = serverName;
        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
    }

    /**
     * Validates the server configuration.
     *
     * @return a map containing validation results for each field.
     */
    public Map<String, Boolean> validateConfiguration() {
        Map<String, Boolean> validationResults = new HashMap<>();

        // Server name must not be null or empty
        validationResults.put("serverNameValid",
                serverName != null && !serverName.trim().isEmpty());

        // Simple IPv4 address validation
        boolean ipValid = false;
        if (serverIp != null) {
            String ipPattern = "\\b(?:\\d{1,3}\\.){3}\\d{1,3}\\b";
            ipValid = Pattern.matches(ipPattern, serverIp);
        }
        validationResults.put("serverIpValid", ipValid);

        // realmId, imageId, hardwareProfileId must be positive
        validationResults.put("realmIdValid", realmId > 0);
        validationResults.put("imageIdValid", imageId > 0);
        validationResults.put("hardwareProfileIdValid", hardwareProfileId > 0);

        return validationResults;
    }

    /**
     * Processes the approval based on configuration validation.
     *
     * @return a map containing approval status, a message, and validation results.
     */
    public Map<String, Object> processApproval() {
        Map<String, Object> result = new HashMap<>();

        Map<String, Boolean> validationResults = validateConfiguration();
        boolean allValid = validationResults.values().stream().allMatch(v -> v);

        approvalStatus.put("approved", allValid);

        String message = allValid
                ? "Configuration approved."
                : "Configuration rejected due to validation failures.";

        result.put("approvalStatus", approvalStatus);
        result.put("message", message);
        result.put("validationResults", validationResults);

        return result;
    }

    // Optional: main method for quick demonstration
    public static void main(String[] args) {
        ServerApprovalHandler handler = new ServerApprovalHandler(
                "TestServer", "192.168.1.10", 1, 100, 200);

        Map<String, Object> approvalResult = handler.processApproval();

        System.out.println("Approval Status: " + approvalResult.get("approvalStatus"));
        System.out.println("Message: " + approvalResult.get("message"));
        System.out.println("Validation Results: " + approvalResult.get("validationResults"));
    }
}

