import java.util.HashMap;
import java.util.Map;

/**
 * Represents a player with a unique ID and a score.
 */
class PlayerInfo {
    private final String playerId;
    private int score;

    public PlayerInfo(String playerId, int score) {
        this.playerId = playerId;
        this.score = score;
    }

    public String getPlayerId() {
        return playerId;
    }

    public int getScore() {
        return score;
    }

    public void setScore(int score) {
        this.score = score;
    }

    @Override
    public String toString() {
        return "PlayerInfo{id='" + playerId + "', score=" + score + "}";
    }
}

/**
 * Manages player registrations and ensures unique player IDs.
 */
class PlayerManager {
    private final Map<String, PlayerInfo> players = new HashMap<>();

    /**
     * Registers a new player with the given ID and initial score.
     *
     * @param playerId Unique identifier for the player.
     * @param initialScore Initial score for the player.
     * @return true if registration succeeded, false if the ID already exists.
     */
    public boolean registerPlayer(String playerId, int initialScore) {
        if (players.containsKey(playerId)) {
            return false; // Duplicate ID, registration rejected.
        }
        players.put(playerId, new PlayerInfo(playerId, initialScore));
        return true;
    }

    /**
     * Retrieves a player by ID.
     *
     * @param playerId The ID of the player to retrieve.
     * @return The PlayerInfo object, or null if not found.
     */
    public PlayerInfo getPlayer(String playerId) {
        return players.get(playerId);
    }

    /**
     * Returns the total number of registered players.
     *
     * @return Number of players.
     */
    public int getPlayerCount() {
        return players.size();
    }
}

/**
 * Demonstrates the player management system.
 */
public class Main {
    public static void main(String[] args) {
        PlayerManager manager = new PlayerManager();

        // Attempt to register players
        boolean addedAlice = manager.registerPlayer("alice", 10);
        boolean addedBob = manager.registerPlayer("bob", 20);
        boolean addedAliceAgain = manager.registerPlayer("alice", 15); // Should fail

        System.out.println("Alice added: " + addedAlice);          // true
        System.out.println("Bob added: " + addedBob);              // true
        System.out.println("Alice added again: " + addedAliceAgain); // false

        // Retrieve and display player info
        PlayerInfo alice = manager.getPlayer("alice");
        PlayerInfo bob = manager.getPlayer("bob");

        System.out.println(alice); // PlayerInfo{id='alice', score=10}
        System.out.println(bob);   // PlayerInfo{id='bob', score=20}

        // Update score
        alice.setScore(25);
        System.out.println("Alice after score update: " + alice);

        // Total players
        System.out.println("Total registered players: " + manager.getPlayerCount());
    }
}

