/**
 * Manages player registrations, removals, score updates, and turn order.
 * All operations are thread‑safe.
 */
class PlayerManager {
    // Thread‑safe map of player ID to PlayerInfo
    private final ConcurrentMap<String, PlayerInfo> players = new ConcurrentHashMap<>();
    // Thread‑safe queue of active players for round‑robin turns
    private final ConcurrentLinkedQueue<PlayerInfo> queue = new ConcurrentLinkedQueue<>();

    /**
     * Registers a new player with the given ID and initial score.
     *
     * @param playerId Unique identifier for the player.
     * @param initialScore Initial score for the player.
     * @return true if registration succeeded, false if the ID already exists.
     */
    public synchronized boolean registerPlayer(String playerId, int initialScore) {
        if (players.containsKey(playerId)) {
            return false; // Duplicate ID, registration rejected.
        }
        PlayerInfo player = new PlayerInfo(playerId, initialScore);
        players.put(playerId, player);
        queue.offer(player);
        return true;
    }

    /**
     * Removes a player by marking them inactive and removing them from the queue.
     *
     * @param playerId The ID of the player to remove.
     * @return true if removal succeeded, false if the player does not exist or is already inactive.
     */
    public synchronized boolean removePlayer(String playerId) {
        PlayerInfo player = players.get(playerId);
        if (player == null || !player.isActive()) {
            return false; // Player not found or already inactive.
        }
        player.setActive(false);
        queue.remove(player); // Removes the reference from the queue.
        return true;
    }

    /**
     * Updates the score of an existing active player by the given delta.
     *
     * @param playerId The ID of the player to update.
     * @param delta The amount to add to the player's score (can be negative).
     * @return true if the update succeeded, false if the player does not exist or is inactive.
     */
    public synchronized boolean updateScore(String playerId, int delta) {
        PlayerInfo player = players.get(playerId);
        if (player == null || !player.isActive()) {
            return false; // Player not found or inactive.
        }
        player.setScore(player.getScore() + delta);
        return true;
    }

    /**
     * Retrieves a player by ID.
     *
     * @param playerId The ID of the player to retrieve.
     * @return The PlayerInfo object, or null if not found.
     */
    public PlayerInfo getPlayer(String playerId) {
        return players.get(playerId);
    }

    /**
     * Returns the total number of registered players.
     *
     * @return Number of players.
     */
    public int getPlayerCount() {
        return players.size();
    }

    /**
     * Returns the number of active players in the queue.
     *
     * @return Number of active players.
     */
    public int getActivePlayerCount() {
        return queue.size();
    }

    /**
     * Returns the queue of active players.
     *
     * @return The queue of active players.
     */
    public ConcurrentLinkedQueue<PlayerInfo> getQueue() {
        return queue;
    }

    /**
     * Retrieves the next player in round‑robin order.
     * The player is moved to the back of the queue after retrieval.
     *
     * @return The next active PlayerInfo, or null if no active players exist.
     */
    public synchronized PlayerInfo getNextPlayer() {
        PlayerInfo next = queue.poll();
        if (next == null) {
            return null; // No active players.
        }
        queue.offer(next); // Move to back for round‑robin.
        return next;
    }
}

/**
 * Demonstrates the player management system with removal, score updates, and turn order.
 */
public class Main {
    public static void main(String[] args) {
        PlayerManager manager = new PlayerManager();

        // Register players
        manager.registerPlayer("alice", 10);
        manager.registerPlayer("bob", 20);
