        // Attempt to update score of removed player
        boolean updateAlice = manager.updateScore("alice", 10); // false

        // Demonstrate round‑robin turns
        System.out.println("\nRound‑robin turns:");
        for (int i = 0; i < 5; i++) {
            PlayerInfo next = manager.getNextPlayer();
            if (next != null) {
                System.out.println("Turn " + (i + 1) + ": " + next.getPlayerId());
            } else {
                System.out.println("Turn " + (i + 1) + ": No active players");
            }
        }

        // Print results
        System.out.println("\nRemoved Alice: " + removedAlice);
        System.out.println("Removed Alice again: " + removedAliceAgain);
        System.out.println("Update Alice after removal: " + updateAlice);

        System.out.println("\nAll players:");
        for (String id : new String[]{"alice", "bob", "carol"}) {
