import java.util.*;

public class PaginationUtils {
    /**
     * Returns a sublist of {@code items} starting at {@code offset} and containing at most {@code limit} elements.
     *
     * @param items  the original list of items (may be {@code null})
     * @param limit  the maximum number of items to return (negative values are treated as 0)
     * @param offset the starting index (negative values are treated as 0)
     * @param <T>    the type of elements in the list
     * @return a sublist based on the provided limit and offset; never {@code null}
     */
    public static <T> List<T> paginate(List<T> items, int limit, int offset) {
        if (items == null) {
            return Collections.emptyList();
        }

        int size = items.size();

        // Normalize offset and limit
        if (offset < 0) {
            offset = 0;
        }
        if (limit < 0) {
            limit = 0;
        }

        // If offset is beyond the list size, return an empty list
        if (offset >= size) {
            return Collections.emptyList();
        }

        int end = Math.min(offset + limit, size);
        return items.subList(offset, end);
    }
}
