    private final List<UnitTest> tests = new ArrayList<>();

    /**
     * Adds a test to the runner.
     *
     * @param test the UnitTest to add.
     */
    public void addTest(UnitTest test) {
        tests.add(test);
    }

    /**
     * Runs all added tests. Each test's runTest method is invoked.
     * Exceptions thrown by a test are caught and reported, but do not
     * stop the execution of subsequent tests.
     *
     * @return the number of tests that were executed.
     */
    public int runAll() {
        int count = 0;
        for (UnitTest test : tests) {
            try {
                test.runTest();
                System.out.println("Test \"" + test.getTestName() + "\" passed.");
            } catch (Exception e) {
                System.out.println("Test \"" + test.getTestName() + "\" failed: " + e.getMessage());
            }
            count++;
        }
        return count;
    }
}

