     */
    String getTestName();
}

/**
 * A simple test runner that keeps a list of UnitTest instances,
 * executes them, and returns a TestResult containing the number
 * of passed, failed, and error tests as well as detailed messages.
 */
class UnitTestRunner {
    private final List<UnitTest> tests = new ArrayList<>();

    /**
     * Adds a test to the runner.
     *
     * @param test the UnitTest to add.
     */
    public void addTest(UnitTest test) {
        tests.add(test);
    }

    /**
     * Inner class that holds the result of a test run.
     */
    public static class TestResult {
        public final int passed;
        public final int failed;
        public final int errors;
        public final List<String> details;

        public TestResult(int passed, int failed, int errors, List<String> details) {
            this.passed = passed;
            this.failed = failed;
            this.errors = errors;
            this.details = Collections.unmodifiableList(details);
        }
    }

    /**
     * Runs all added tests. Each test's runTest method is invoked.
     * AssertionError is treated as a test failure; any other Exception
     * is treated as an error. The method collects counts and detailed
     * messages for each outcome.
     *
     * @return a TestResult containing the number of passed, failed,
     *         and error tests, plus a list of detailed messages.
     */
    public TestResult runAllTests() {
        int passed = 0;
        int failed = 0;
        int errors = 0;
        List<String> details = new ArrayList<>();

        for (UnitTest test : tests) {
            String testName = test.getTestName();
            try {
