/**
 * Processor that stores messages, tracks counts per destination,
 * and returns a processing result with metadata.
 * All public methods are thread‑safe via the synchronized keyword.
 */
public class EnhancedMessageProcessor {
    // Stores the most recent message for each destination.
    private final Map<String, LinkedHashMap<String, Message>> destMessages = new LinkedHashMap<>();
    // Stores all messages in insertion order.
    private final Map<String, Message> globalMessages = new LinkedHashMap<>();
    // Tracks the number of messages per destination.
    private final Map<String, Integer> counts = new HashMap<>();

    /**
     * Stores the given message for the specified destination and returns a success result.
     * The result includes metadata with the total number of messages sent to that destination.
     *
     * @param message     the message to store
     * @param destination the destination identifier
     * @return a ProcessingResult indicating success and containing metadata
     */
    public synchronized ProcessingResult postMessage(Message message, String destination) {
        // Store per‑destination message
        destMessages.computeIfAbsent(destination, k -> new LinkedHashMap<>())
                    .put(message.getId(), message);

        // Store globally to preserve insertion order
        globalMessages.put(message.getId(), message);

        // Update count
        int count = counts.getOrDefault(destination, 0) + 1;
        counts.put(destination, count);

        Map<String, Object> metadata = new LinkedHashMap<>();
        metadata.put("totalMessages", count);

        return new ProcessingResult(Status.SUCCESS, message.getId(), metadata);
    }

    /**
     * Retrieves the latest message stored for the specified destination.
     *
     * @param destination the destination identifier
     * @return the most recent Message, or null if none exists for that destination
     */
    public synchronized Message getMessage(String destination) {
        LinkedHashMap<String, Message> msgs = destMessages.get(destination);
        if (msgs == null || msgs.isEmpty()) {
            return null;
        }
        // The last inserted message is the last entry in the LinkedHashMap
        return msgs.values().iterator().next();
    }

    /**
     * Returns all messages whose content matches the specified type.
     * The returned map preserves the insertion order of the messages.
     *
     * @param contentType the content type to filter by
     * @return a LinkedHashMap of message IDs to Messages that match the type
     */
    public synchronized Map<String, Message> getMessagesByType(String contentType) {
        Map<String, Message> result = new LinkedHashMap<>();
        for (Message msg : globalMessages.values()) {
            if (msg.getContent().equals(contentType)) {
                result.put(msg.getId(), msg);
            }
        }
        return result;
    }

    /**
     * Removes all messages for the specified destination.
     *
     * @param destination the destination identifier
     * @return Status.SUCCESS if messages were removed, Status.FAILURE if none existed
     */
    public synchronized Status clearMessages(String destination) {
        LinkedHashMap<String, Message> msgs = destMessages.remove(destination);
        if (msgs == null || msgs.isEmpty()) {
            return Status.FAILURE;
        }

        // Remove each message from the global map
        for (String msgId : msgs.keySet()) {
            globalMessages.remove(msgId);
        }

        // Remove count entry
        counts.remove(destination);

        return Status.SUCCESS;
    }
}

