public class FrequencyPlanner {

    public static class FrequencyAssignment {
        private final int requiredBandwidth;

        public FrequencyAssignment(int requiredBandwidth) {
            this.requiredBandwidth = requiredBandwidth;
        }

        public int getRequiredBandwidth() {
            return requiredBandwidth;
        }
    }

    public static class Channel {
        private final int availableBandwidth;

        public Channel(int availableBandwidth) {
            this.availableBandwidth = availableBandwidth;
        }

        public int getAvailableBandwidth() {
            return availableBandwidth;
        }
    }

    public static class Plan {
        private final List<FrequencyAssignment> assignments;
        private final List<Channel> channels;

        public Plan(List<FrequencyAssignment> assignments, List<Channel> channels) {
            this.assignments = assignments;
            this.channels = channels;
        }

        public List<FrequencyAssignment> getAssignments() {
            return assignments;
        }

        public List<Channel> getChannels() {
            return channels;
        }

        public int getTotalRequiredBandwidth() {
            int total = 0;
            for (FrequencyAssignment fa : assignments) {
                total += fa.getRequiredBandwidth();
            }
            return total;
        }

        public int getTotalAvailableBandwidth() {
            int total = 0;
            for (Channel ch : channels) {
                total += ch.getAvailableBandwidth();
            }
            return total;
        }
    }

    public static Plan createPlan(int[] requiredBandwidths, int[] availableBandwidths) {
        List<FrequencyAssignment> assignments = new ArrayList<>();
        for (int bw : requiredBandwidths) {
            if (bw > 0) {
                assignments.add(new FrequencyAssignment(bw));
            }
        }

        List<Channel> channels = new ArrayList<>();
        for (int bw : availableBandwidths) {
            if (bw > 0) {
                channels.add(new Channel(bw));
            }
        }

        return new Plan(assignments, channels);
    }

    // Optional main method for demonstration
    public static void main(String[] args) {
        int[] required = {10, -5, 20, 0, 15};
        int[] available = {30, 25, -10, 5};

        Plan plan = createPlan(required, available);

        System.out.println("Total required bandwidth: " + plan.getTotalRequiredBandwidth());
        System.out.println("Total available bandwidth: " + plan.getTotalAvailableBandwidth());
    }
}
