import java.util.*;

public class ListDivider {
    /**
     * Performs element‑wise integer division of two lists.
     *
     * @param list1 the dividend list
     * @param list2 the divisor list
     * @return a new list containing the integer division results
     * @throws IllegalArgumentException if the lists are null or of different sizes
     * @throws ArithmeticException      if a divisor is zero
     */
    public static List<Integer> divideLists(List<Integer> list1, List<Integer> list2) {
        if (list1 == null || list2 == null) {
            throw new IllegalArgumentException("Input lists cannot be null");
        }
        if (list1.size() != list2.size()) {
            throw new IllegalArgumentException("Lists must have the same size");
        }

        List<Integer> result = new ArrayList<>(list1.size());
        for (int i = 0; i < list1.size(); i++) {
            int divisor = list2.get(i);
            if (divisor == 0) {
                throw new ArithmeticException("Division by zero at index " + i);
            }
            result.add(list1.get(i) / divisor);
        }
        return result;
    }
}

