import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Basic authentication service that supports username, email, or user ID as identifiers.
 * It uses three thread‑safe caches (accountCache, emailCache, idCache) to avoid repeated
 * database lookups. If a user is not found in the caches, a simulated database lookup
 * is performed and the result is stored in all caches.
 */
public class AuthService {

    /* --------------------------- User class --------------------------- */

    /**
     * Simple User representation.
     */
    public static class User {
        private final String username;
        private final String email;
        private final String displayName;

        public User(String username, String email, String displayName) {
            this.username = username;
            this.email = email;
            this.displayName = displayName;
        }

        public String getUsername() {
            return username;
        }

        public String getEmail() {
            return email;
        }

        public String getDisplayName() {
            return displayName;
        }

        @Override
        public String toString() {
            return "User{username='" + username + "', email='" + email + "', displayName='" + displayName + "'}";
        }
    }

    /* --------------------------- Caches --------------------------- */

    /** Cache keyed by account name (username). */
    private static final ConcurrentHashMap<String, User> accountCache = new ConcurrentHashMap<>();

    /** Cache keyed by email address. */
    private static final ConcurrentHashMap<String, User> emailCache = new ConcurrentHashMap<>();

    /** Cache keyed by user ID. */
    private static final ConcurrentHashMap<Long, User> idCache = new ConcurrentHashMap<>();

    /* --------------------------- Mock data --------------------------- */

    private static final String MOCK_USERNAME = "testuser";
    private static final String MOCK_EMAIL = "test@example.com";
    private static final String MOCK_PASSWORD = "password";
    private static final Long MOCK_ID = 1L;

    /* --------------------------- Authentication --------------------------- */

    /**
     * Authenticates a user based on an identifier (username, email, or user ID) and password.
     *
     * @param identifier The identifier, which can be a String (username or email) or a Long (user ID).
     * @param password   The password to validate.
     * @return A map containing:
     *         - "authenticated" (Boolean)
     *         - "user" (User) if authentication succeeds
     *         - "error" (String) if authentication fails
     * @throws IllegalArgumentException if the identifier is neither a String nor a Long.
     */
    public static Map<String, Object> authenticateUser(Object identifier, String password) {
        Map<String, Object> result = new java.util.HashMap<>();

        // 1. Try to find the user in the appropriate cache
        User cachedUser = null;
        if (identifier instanceof String) {
            String idStr = (String) identifier;
            if (idStr.contains("@")) {
                cachedUser = emailCache.get(idStr);
            } else {
                cachedUser = accountCache.get(idStr);
            }
        } else if (identifier instanceof Long) {
            Long idLong = (Long) identifier;
            cachedUser = idCache.get(idLong);
        } else {
            throw new IllegalArgumentException("Identifier must be a String or Long");
        }

        // 2. If found in cache, verify password
        if (cachedUser != null) {
            if (MOCK_PASSWORD.equals(password)) {
                result.put("authenticated", true);
                result.put("user", cachedUser);
                return result;
            } else {
                result.put("authenticated", false);
                result.put("error", "Invalid password.");
                return result;
            }
        }

        // 3. Not found in cache – simulate database lookup
        User dbUser = findUserInDatabase(identifier, password);
        if (dbUser != null) {
            // Cache the user in all caches
            cacheUser(dbUser);
            result.put("authenticated", true);
            result.put("user", dbUser);
        } else {
            result.put("authenticated", false);
            result.put("error", "Invalid username/email/ID or password.");
        }

        return result;
    }

    /* --------------------------- Helper methods --------------------------- */

    /**
     * Simulates a database lookup for a user.
     *
     * @param identifier The identifier (String or Long).
     * @param password   The password to validate.
     * @return The User if credentials match; otherwise null.
     */
    private static User findUserInDatabase(Object identifier, String password) {
        if (!MOCK_PASSWORD.equals(password)) {
            return null;
        }

        if (identifier instanceof String) {
            String idStr = (String) identifier;
            if (idStr.contains("@")) {
                if (MOCK_EMAIL.equalsIgnoreCase(idStr)) {
                    return new User(MOCK_USERNAME, MOCK_EMAIL, "Test User");
                }
            } else {
                if (MOCK_USERNAME.equalsIgnoreCase(idStr)) {
                    return new User(MOCK_USERNAME, MOCK_EMAIL, "Test User");
                }
            }
        } else if (identifier instanceof Long) {
            Long idLong = (Long) identifier;
            if (MOCK_ID.equals(idLong)) {
                return new User(MOCK_USERNAME, MOCK_EMAIL, "Test User");
            }
        }

        return null;
    }

    /**
     * Stores the user in all three caches.
     *
     * @param user The user to cache.
     */
    private static void cacheUser(User user) {
        accountCache.put(user.getUsername(), user);
        emailCache.put(user.getEmail(), user);
        idCache.put(MOCK_ID, user);
    }

    /* --------------------------- Demo --------------------------- */

    public static void main(String[] args) {
