        }
    }

    public static class PointLight {
        private Vector3 position;
        private Vector3 color;

        public PointLight() {
            this(new Vector3(), new Vector3(1, 1, 1));
        }

        public PointLight(Vector3 position, Vector3 color) {
            this.position = position;
            this.color = color;
        }

        public Vector3 getPosition() { return position; }
        public void setPosition(Vector3 position) { this.position = position; }

        public Vector3 getColor() { return color; }
        public void setColor(Vector3 color) { this.color = color; }
    }

    // --------------------------------------------------------------------
    // EnhancedSpotLight fields
    // --------------------------------------------------------------------

    private PointLight baseLight;
    private Vector3 direction;
    private double cutoff;       // inner cutoff in degrees
    private double outerCutoff;  // outer cutoff in degrees
    private double exponent;     // falloff exponent

    // --------------------------------------------------------------------
    // Constructors
    // --------------------------------------------------------------------

    public EnhancedSpotLight() {
        this(new PointLight(), new Vector3(0, 0, -1), 30.0, 45.0, 1.0);
    }

    public EnhancedSpotLight(PointLight baseLight, Vector3 direction,
                             double cutoff, double outerCutoff, double exponent) {
        setBaseLight(baseLight);
        setDirection(direction);
        setCutoff(cutoff);
        setOuterCutoff(outerCutoff);
        setExponent(exponent);
