        if (direction == null) {
            throw new IllegalArgumentException("direction cannot be null");
        }
        this.direction = direction;
    }

    public double getCutoff() { return cutoff; }
    public void setCutoff(double cutoff) {
        if (cutoff < 0 || cutoff > 90) {
            throw new IllegalArgumentException("cutoff must be between 0 and 90 degrees");
        }
        if (this.outerCutoff != 0 && cutoff >= this.outerCutoff) {
            throw new IllegalArgumentException("cutoff must be less than outerCutoff");
        }
        this.cutoff = cutoff;
    }

    public double getOuterCutoff() { return outerCutoff; }
    public void setOuterCutoff(double outerCutoff) {
        if (outerCutoff < 0 || outerCutoff > 90) {
            throw new IllegalArgumentException("outerCutoff must be between 0 and 90 degrees");
        }
        if (outerCutoff <= this.cutoff) {
            throw new IllegalArgumentException("outerCutoff must be greater than cutoff");
        }
        this.outerCutoff = outerCutoff;
    }

    public double getExponent() { return exponent; }
    public void setExponent(double exponent) {
        if (exponent <= 0) {
            throw new IllegalArgumentException("exponent must be positive");
        }
        this.exponent = exponent;
    }

    // --------------------------------------------------------------------
    // Core functionality
    // --------------------------------------------------------------------

    /**
     * Calculates the intensity of the spotlight at a given point.
     * The intensity is based on the angular attenuation between the
     * spotlight direction and the vector from the light to the point.
     * A smooth transition is applied between the inner (cutoff) and
     * outer (outerCutoff) angles using the falloff exponent.
     *
     * @param point The point at which to evaluate intensity.
     * @return Intensity value between 0.0 and 1.0.
     */
    public double calculateIntensity(Vector3 point) {
        // Vector from light to point
        Vector3 toPoint = point.sub(baseLight.getPosition()).normalized();

        // Normalized spotlight direction
        Vector3 dir = direction.normalized();

        // Cosine of the angle between direction and toPoint
        double dot = dir.dot(toPoint);

        // Cosines of cutoff angles
        double cosInner = Math.cos(Math.toRadians(cutoff));
        double cosOuter = Math.cos(Math.toRadians(outerCutoff));

        if (dot >= cosInner) {
            // Inside inner cone – full intensity
            return 1.0;
        } else if (dot <= cosOuter) {
            // Outside outer cone – no intensity
            return 0.0;
        } else {
            // Smooth transition between inner and outer cones
            double factor = (dot - cosOuter) / (cosInner - cosOuter);
            // Clamp factor to [0,1] to avoid numerical issues
            factor = Math.max(0.0, Math.min(1.0, factor));
            return Math.pow(factor, exponent);
        }
    }
}

