import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Represents a category with an id, name and parent id.
 */
class Category {
    private int id;
    private String name;
    private int parentId;

    public Category(int id, String name, int parentId) {
        this.id = id;
        this.name = name;
        this.parentId = parentId;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public int getParentId() { return parentId; }

    public void setId(int id) { this.id = id; }
    public void setName(String name) { this.name = name; }
    public void setParentId(int parentId) { this.parentId = parentId; }
}

/**
 * Node used in the category tree. Each node holds its own id, name and a list of child nodes.
 */
class CategoryNode {
    private int id;
    private String name;
    private List<CategoryNode> children = new ArrayList<>();

    public CategoryNode(int id, String name) {
        this.id = id;
        this.name = name;
    }

    public int getId() { return id; }
    public String getName() { return name; }
    public List<CategoryNode> getChildren() { return children; }

    public void setId(int id) { this.id = id; }
    public void setName(String name) { this.name = name; }
    public void setChildren(List<CategoryNode> children) { this.children = children; }

    public void addChild(CategoryNode child) {
        children.add(child);
    }
}

/**
 * Result wrapper for the list of root category nodes.
 */
class CatResult {
    private List<CategoryNode> data;

    public CatResult() {
        this.data = new ArrayList<>();
    }

    public CatResult(List<CategoryNode> data) {
        this.data = data;
    }

    public List<CategoryNode> getData() { return data; }
    public void setData(List<CategoryNode> data) { this.data = data; }
}

/**
 * Service that manages categories and builds a tree structure.
 */
class ItemCatService {
    // Stores raw category information by id
    private Map<Integer, Category> categoryMap = new HashMap<>();
    // Stores tree nodes by id
    private Map<Integer, CategoryNode> nodeMap = new HashMap<>();
    // List of root nodes (parentId == 0)
    private List<CategoryNode> roots = new ArrayList<>();

    /**
     * Adds a new category. Assumes that if parentId != 0, the parent has already been added.
     */
    public void addCategory(int id, String name, int parentId) {
        Category cat = new Category(id, name, parentId);
        categoryMap.put(id, cat);

        CategoryNode node = new CategoryNode(id, name);
        nodeMap.put(id, node);

        if (parentId == 0) {
            roots.add(node);
        } else {
            CategoryNode parentNode = nodeMap.get(parentId);
            if (parentNode != null) {
                parentNode.addChild(node);
            } else {
                // In a real system we might throw an exception or handle this case.
                // For this minimal implementation we simply ignore the child.
            }
        }
    }

    /**
     * Returns the category tree wrapped in a CatResult.
     * If no categories exist, returns an empty CatResult.
     */
    public CatResult getItemCatList() {
        if (roots.isEmpty()) {
            return new CatResult();
        }
        return new CatResult(roots);
    }
}

