/**
 * Service that manages categories and builds a tree structure.
 */
class ItemCatService {
    // Stores raw category information by id, preserving insertion order
    private Map<Integer, Category> categoryMap = new LinkedHashMap<>();

    /**
     * Adds a new category. Assumes that if parentId != 0, the parent may or may not have been added yet.
     */
    public void addCategory(int id, String name, int parentId) {
        Category cat = new Category(id, name, parentId);
        categoryMap.put(id, cat);
    }

    /**
     * Builds the category tree recursively and returns it wrapped in a CatResult.
     * Skips any category whose parent ID does not exist in the categories list.
     * The order of root categories matches the order they were added.
     */
    public CatResult getItemCatList() {
        if (categoryMap.isEmpty()) {
            return new CatResult();
        }

        // Map from parentId to list of child categories, preserving insertion order
        Map<Integer, List<Category>> parentToChildren = new LinkedHashMap<>();

        // Build parent-to-children mapping, skipping categories with missing parents
        for (Category cat : categoryMap.values()) {
            int parentId = cat.getParentId();
            if (parentId == 0 || categoryMap.containsKey(parentId)) {
                parentToChildren
                    .computeIfAbsent(parentId, k -> new ArrayList<>())
                    .add(cat);
            }
            // else: parent missing – skip this category entirely
        }

        // Find root categories (parentId == 0) in insertion order
        List<CategoryNode> roots = new ArrayList<>();
        List<Category> rootCategories = parentToChildren.getOrDefault(0, new ArrayList<>());
        for (Category rootCat : rootCategories) {
            CategoryNode rootNode = buildNodeRecursive(rootCat, parentToChildren);
            roots.add(rootNode);
        }

        return new CatResult(roots);
    }

    /**
     * Recursively builds a CategoryNode and its children.
     */
    private CategoryNode buildNodeRecursive(Category cat, Map<Integer, List<Category>> parentToChildren) {
        CategoryNode node = new CategoryNode(cat.getId(), cat.getName());
        List<Category> children = parentToChildren.getOrDefault(cat.getId(), new ArrayList<>());
        for (Category childCat : children) {
            CategoryNode childNode = buildNodeRecursive(childCat, parentToChildren);
            node.addChild(childNode);
        }
        return node;
    }
}

